import struct
def jpeg_info(path):
    data=open(path,'rb').read()
    print(path, len(data), data[:20])
    i=2
    while i<len(data):
        if data[i]!=0xFF:
            print(" not marker at",i); break
        m=data[i+1]
        if m in (0xD8,0xD9) or 0xD0<=m<=0xD7:
            print(f" FF{m:02X}"); i+=2; continue
        if m==0xDA:
            print(" SOS"); break
        ln=struct.unpack('>H',data[i+2:i+4])[0]
        name={0xC0:"SOF0 baseline",0xC2:"SOF2 progressive",0xC4:"DHT",0xDB:"DQT",0xDD:"DRI",0xE0:"APP0",0xE1:"APP1",0xE2:"APP2",0xEE:"APP14",0xFE:"COM"}.get(m, f"{m:02X}")
        extra=""
        if m in (0xC0,0xC2):
            prec=data[i+4]; h=struct.unpack('>H',data[i+5:i+7])[0]; w=struct.unpack('>H',data[i+7:i+9])[0]; comp=data[i+9]
            extra=f" {w}x{h} prec{prec} comps{comp} "
            for c in range(comp):
                cid=data[i+10+c*3]; hv=data[i+11+c*3]; tq=data[i+12+c*3]
                extra+=f"[id{cid} H{hv>>4} V{hv&15} tq{tq}]"
        if m==0xE1:
            extra=" "+repr(data[i+4:i+4+20])
        if m==0xE0:
            extra=" "+repr(data[i+4:i+4+20])
        print(f" FF{m:02X} {name} len{ln}{extra}")
        i+=2+ln
for p in ["assets/j0.JPG","/tmp/t1/out/j0.JPG"]:
    jpeg_info(p)
