import struct, sys, os, zlib
def jpeg_info(path):
    data=open(path,'rb').read()
    print(path, len(data))
    i=2
    while i<len(data)-1:
        if data[i]!=0xFF:
            i+=1; continue
        m=data[i+1]
        if m==0xDA: print(" SOS"); break
        if m in (0xD8,0xD9) or 0xD0<=m<=0xD7:
            i+=2; continue
        if i+4>len(data): break
        ln=struct.unpack('>H',data[i+2:i+4])[0]
        name={0xC0:"SOF0",0xC1:"SOF1",0xC2:"SOF2",0xC4:"DHT",0xDB:"DQT",0xDD:"DRI",0xE0:"APP0",0xE1:"APP1EXIF",0xE2:"APP2ICC",0xED:"APP13",0xEE:"APP14",0xFE:"COM"}.get(m, f"{m:02X}")
        extra=""
        if m in (0xC0,0xC1,0xC2):
            h=struct.unpack('>H',data[i+5:i+7])[0]; w=struct.unpack('>H',data[i+7:i+9])[0]; comp=data[i+9]
            extra=f" {w}x{h} comps{comp} "
            for c in range(comp):
                extra+=f"[{data[i+10+c*3]} H{data[i+11+c*3]>>4}V{data[i+11+c*3]&15}]"
        if 0xE0<=m<=0xEF: extra=" "+repr(data[i+4:i+min(i+2+ln,i+30)])
        print(f" FF{m:02X} {name} len{ln}{extra}")
        i+=2+ln
def png_info(path):
    data=open(path,'rb').read()
    print(path, len(data))
    i=8
    while i<len(data):
        ln=struct.unpack('>I',data[i:i+4])[0]; typ=data[i+4:i+8].decode('latin1')
        extra=""
        if typ=="IHDR":
            w,h=struct.unpack('>II',data[i+8:i+16]); bd=data[i+16]; ct=data[i+17]; comp=data[i+18]; filt=data[i+19]; inter=data[i+20]
            extra=f" {w}x{h} bitdepth{bd} colortype{ct} interlace{inter}"
        if typ in ("tEXt","iTXt","zTXt","eXIf","iCCP"): extra=" "+repr(data[i+8:i+8+min(ln,40)])
        print(f" {typ} len{ln}{extra}")
        i+=12+ln
        if typ=="IEND": break
def webp_info(path):
    data=open(path,'rb').read()
    print(path, len(data), data[:16])
    # RIFF
    i=12
    while i+8<=len(data):
        typ=data[i:i+4]; ln=struct.unpack('<I',data[i+4:i+8])[0]
        print(f" {typ} len{ln} {data[i+8:i+8+min(ln,20)]!r}")
        i+=8+ln+(ln&1)
def gif_info(path):
    data=open(path,'rb').read()
    print(path, len(data), data[:20])
    w,h=struct.unpack('<HH',data[6:10]); print(f" {w}x{h} packed{data[10]:08b} bg{data[11]} aspect{data[12]}")
def tiff_info(path):
    data=open(path,'rb').read()
    print(path, len(data), data[:100])
for p in sys.argv[1:]:
    ext=os.path.splitext(p)[1].lower()
    try:
        if ext in (".jpg",".jpeg"): jpeg_info(p)
        elif ext==".png": png_info(p)
        elif ext==".webp": webp_info(p)
        elif ext==".gif": gif_info(p)
        elif ext in (".tif",".tiff"): tiff_info(p)
        else:
            d=open(p,'rb').read(16)
            print(p, os.path.getsize(p), d)
            if d[:2]==b'\xff\xd8': jpeg_info(p)
            elif d[:8]==b'\x89PNG\r\n\x1a\n': png_info(p)
            elif d[:4]==b'RIFF': webp_info(p)
            elif d[:3]==b'GIF': gif_info(p)
    except Exception as e:
        print(p, "ERR", e)
