{"command":"rm -rf /tmp/out && mkdir -p /tmp/out
for f in assets/j0.JPG assets/p0.png assets/w0.webp assets/g1.gif assets/t0.tif; do
  for mode in "q80" "q0" "q100" "lossless"; do
    case $mode in
      q80) args="-q 80";;
      q0) args="-q 0";;
      q100) args="-q 100";;
      lossless) args="--lossless";;
    esac
    rm -rf /tmp/out; mkdir -p /tmp/out
    echo "=== $f $mode"
    timeout 60 ./executable $args -o /tmp/out "$f" 2>&1; echo "exit:$?"
    ls -l /tmp/out
    for o in /tmp/out/*; do if [ -f "$o" ]; then python3 /tmp/inspect.py "$o"; cmp -s "$f" "$o" && echo "IDENTICAL"; fi; done
  done
done"}

