import os, pty, subprocess, select, time, fcntl, termios, struct
def run(mode):
    m_out,s_out=pty.openpty(); m_err,s_err=pty.openpty()
    for fd in [s_out,s_err]:
        fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH",24,80,0,0))
    env=os.environ.copy(); env["TERM"]="xterm"
    if mode=="both":
        out_fd,err_fd=s_out,s_err
    elif mode=="stdout_tty_only":
        out_fd=s_out; err_fd=open("/tmp/errfile.txt","wb")
