 d={}
 for i in range(n):
  tag,typ,cnt,val=struct.unpack('<HHI4s',data[off+2+i*12:off+14+i*12])
  if typ==3 and cnt==1: v=struct.unpack('<H',val[:2])[0]
  elif typ==4 and cnt==1: v=struct.unpack('<I',val)[0]
