import zlib,struct
def decode(path):
 d=open(path,'rb').read(); i=8; idat=b''; plte=[]; trns=b''
 while i<len(d):
  ln=struct.unpack('>I',d[i:i+4])[0]; typ=d[i+4:i+8]; data=d[i+8:i+8+ln]; i+=12+ln
  if typ==b'IHDR': w,h,bd,ct,comp,filt,inter=struct.unpack('>IIBBBBB',data)
  elif typ==b'IDAT': idat+=data
  elif typ==b'PLTE': plte=[tuple(data[j:j+3]) for j in range(0,len(data),3)]
  elif typ==b'tRNS': trns=data
 raw=zlib.decompress(idat)
 channels={0:1,2:3,3:1,4:2,6:4}[ct]
 # bits per pixel
 bpp_bits=channels*bd
 rowbits=w*bpp_bits
 rowbytes=(rowbits+7)//8
 bpp_bytes=max(1,(bpp_bits+7)//8)  # for filtering, bytes of a pixel rounded up
 rows=[]; prev=bytearray(rowbytes); pos=0
 # no Adam7 support in this small tool
 if inter: raise ValueError('interlaced')
 for y in range(h):
  f=raw[pos]; pos+=1; cur=bytearray(raw[pos:pos+rowbytes]); pos+=rowbytes
  if f==1:
   for x in range(bpp_bytes,len(cur)): cur[x]=(cur[x]+cur[x-bpp_bytes])&255
  elif f==2:
   for x in range(len(cur)): cur[x]=(cur[x]+prev[x])&255
  elif f==3:
   for x in range(len(cur)):
    a=cur[x-bpp_bytes] if x>=bpp_bytes else 0; cur[x]=(cur[x]+((a+prev[x])//2))&255
  elif f==4:
   for x in range(len(cur)):
    a=cur[x-bpp_bytes] if x>=bpp_bytes else 0; b=prev[x]; c=prev[x-bpp_bytes] if x>=bpp_bytes else 0
    p=a+b-c; pa=abs(p-a); pb=abs(p-b); pc=abs(p-c); pr=a if (pa<=pb and pa<=pc) else (b if pb<=pc else c)
    cur[x]=(cur[x]+pr)&255
  rows.append(bytes(cur)); prev=cur
 # unpack pixels to RGBA tuples
 pixels=[]
 def get_samples(row):
  if bd==8: return list(row)
  if bd==16: return [row[j] for j in range(0,len(row),2)] # high byte only approx (return maybe first)
  # subbyte: samples per byte
  vals=[]
  per=8//bd; mask=(1<<bd)-1
  for byte in row:
   for s in range(per-1,-1,-1): vals.append((byte>>(s*bd))&mask)
  return vals[:w*channels]
 for y in range(h):
  vals=get_samples(rows[y])
  for x in range(w):
   s=vals[x*channels:(x+1)*channels]
   if ct==0:
    maxv=(1<<bd)-1; v=s[0]*255//maxv if bd<8 else s[0]; pixels.append((v,v,v,255))
   elif ct==2: pixels.append((*s,255))
   elif ct==3:
    idx=s[0]; r,g,b=plte[idx]; a=trns[idx] if idx<len(trns) else 255; pixels.append((r,g,b,a))
   elif ct==4: pixels.append((s[0],s[0],s[0],s[1]))
   elif ct==6: pixels.append(tuple(s))
 return (w,h,bd,ct,inter,plte,pixels)
if __name__=="__main__":
 import sys
 for p in sys.argv[1:]:
  w,h,bd,ct,inter,plte,pix=decode(p); print(p,w,h,bd,ct,"unique",len(set(pix)),"first",pix[:8],"pal",plte[:8])
