use std::collections::HashSet;
use std::env;
use std::ffi::{OsStr, OsString};
use std::io::IsTerminal;
use std::path::{Path, PathBuf};

#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum ArgId {
    Quality, Lossless, MaxSize, Width, Height, LongEdge, ShortEdge, NoUpscale,
    Output, SameFolder, Format, PngOptLevel, JpegChroma, JpegBaseline, Zopfli,
    Exif, KeepDates, StripIcc, Suffix, Recursive, KeepStructure, DryRun,
    Threads, Overwrite, MinSavings, Quiet, Verbose, Help, Version, Files,
}
use ArgId::*;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum OutputFormat { Jpeg, Png, Gif, Webp, Tiff, Original }
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Chroma { C444, C422, C420, C411, Auto }
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum OverwritePolicy { All, Never, Bigger }
#[derive(Clone, Copy, PartialEq, Debug)]
pub enum MinSavings { Percent(f64), Absolute(u64) }

#[derive(Clone, Debug)]
pub struct Args {
    pub quality: Option<u8>,
    pub lossless: bool,
    pub max_size: Option<u64>,
    pub width: Option<u32>,
    pub height: Option<u32>,
    pub long_edge: Option<u32>,
    pub short_edge: Option<u32>,
    pub no_upscale: bool,
    pub output: Option<PathBuf>,
    pub same_folder_as_input: bool,
    pub format: OutputFormat,
    pub png_opt_level: u8,
    pub jpeg_chroma_subsampling: Chroma,
    pub jpeg_baseline: bool,
    pub zopfli: bool,
    pub exif: bool,
    pub keep_dates: bool,
    pub strip_icc: bool,
    pub suffix: Option<String>,
    pub recursive: bool,
    pub keep_structure: bool,
    pub dry_run: bool,
    pub threads: u32,
    pub overwrite: OverwritePolicy,
    pub min_savings: Option<MinSavings>,
    pub quiet: bool,
    pub verbose: u8,
    pub files: Vec<String>,
}

impl Default for Args {
    fn default() -> Self {
        Self {
            quality: None, lossless: false, max_size: None,
            width: None, height: None, long_edge: None, short_edge: None, no_upscale: false,
            output: None, same_folder_as_input: false, format: OutputFormat::Original,
            png_opt_level: 3, jpeg_chroma_subsampling: Chroma::Auto, jpeg_baseline: false, zopfli: false,
            exif: false, keep_dates: false, strip_icc: false, suffix: None,
            recursive: false, keep_structure: false, dry_run: false, threads: 0,
            overwrite: OverwritePolicy::All, min_savings: None, quiet: false, verbose: 1,
            files: Vec::new(),
        }
    }
}

#[derive(Debug)]
pub struct CliExit {
    pub code: i32,
    pub stdout: String,
    pub stderr: String,
}
impl CliExit {
    fn out(s: String) -> Self { Self { code: 0, stdout: s, stderr: String::new() } }
    fn err(s: String) -> Self { Self { code: 2, stdout: String::new(), stderr: s } }
}

#[derive(Clone, Copy)]
struct Spec {
    id: ArgId,
    short: Option<char>,
    long: &'static str,
    value_name: Option<&'static str>,
    group: Option<u8>, // 0 compression, 1 output
    empty_is_missing: bool,
}

const SPECS: &[Spec] = &[
    Spec{id:Quality,short:Some('q'),long:"quality",value_name:Some("QUALITY"),group:Some(0),empty_is_missing:false},
    Spec{id:Lossless,short:None,long:"lossless",value_name:None,group:Some(0),empty_is_missing:false},
    Spec{id:MaxSize,short:None,long:"max-size",value_name:Some("MAX_SIZE"),group:Some(0),empty_is_missing:false},
    Spec{id:Width,short:None,long:"width",value_name:Some("WIDTH"),group:None,empty_is_missing:false},
    Spec{id:Height,short:None,long:"height",value_name:Some("HEIGHT"),group:None,empty_is_missing:false},
    Spec{id:LongEdge,short:None,long:"long-edge",value_name:Some("LONG_EDGE"),group:None,empty_is_missing:false},
    Spec{id:ShortEdge,short:None,long:"short-edge",value_name:Some("SHORT_EDGE"),group:None,empty_is_missing:false},
    Spec{id:NoUpscale,short:None,long:"no-upscale",value_name:None,group:None,empty_is_missing:false},
    Spec{id:Output,short:Some('o'),long:"output",value_name:Some("OUTPUT"),group:Some(1),empty_is_missing:true},
    Spec{id:SameFolder,short:None,long:"same-folder-as-input",value_name:None,group:Some(1),empty_is_missing:false},
    Spec{id:Format,short:None,long:"format",value_name:Some("FORMAT"),group:None,empty_is_missing:true},
    Spec{id:PngOptLevel,short:None,long:"png-opt-level",value_name:Some("PNG_OPT_LEVEL"),group:None,empty_is_missing:false},
    Spec{id:JpegChroma,short:None,long:"jpeg-chroma-subsampling",value_name:Some("JPEG_CHROMA_SUBSAMPLING"),group:None,empty_is_missing:true},
    Spec{id:JpegBaseline,short:None,long:"jpeg-baseline",value_name:None,group:None,empty_is_missing:false},
    Spec{id:Zopfli,short:None,long:"zopfli",value_name:None,group:None,empty_is_missing:false},
    Spec{id:Exif,short:Some('e'),long:"exif",value_name:None,group:None,empty_is_missing:false},
    Spec{id:KeepDates,short:None,long:"keep-dates",value_name:None,group:None,empty_is_missing:false},
    Spec{id:StripIcc,short:None,long:"strip-icc",value_name:None,group:None,empty_is_missing:false},
    Spec{id:Suffix,short:None,long:"suffix",value_name:Some("SUFFIX"),group:None,empty_is_missing:false},
    Spec{id:Recursive,short:Some('R'),long:"recursive",value_name:None,group:None,empty_is_missing:false},
    Spec{id:KeepStructure,short:Some('S'),long:"keep-structure",value_name:None,group:None,empty_is_missing:false},
    Spec{id:DryRun,short:Some('d'),long:"dry-run",value_name:None,group:None,empty_is_missing:false},
    Spec{id:Threads,short:None,long:"threads",value_name:Some("THREADS"),group:None,empty_is_missing:false},
    Spec{id:Overwrite,short:Some('O'),long:"overwrite",value_name:Some("OVERWRITE"),group:None,empty_is_missing:true},
    Spec{id:MinSavings,short:None,long:"min-savings",value_name:Some("MIN_SAVINGS"),group:None,empty_is_missing:false},
    Spec{id:Quiet,short:Some('Q'),long:"quiet",value_name:None,group:None,empty_is_missing:false},
    Spec{id:Verbose,short:None,long:"verbose",value_name:Some("VERBOSE"),group:None,empty_is_missing:false},
    Spec{id:Help,short:Some('h'),long:"help",value_name:None,group:None,empty_is_missing:false},
    Spec{id:Version,short:Some('V'),long:"version",value_name:None,group:None,empty_is_missing:false},
];

fn spec(id: ArgId) -> &'static Spec { SPECS.iter().find(|s| s.id == id).unwrap() }
fn spec_by_long(name: &str) -> Option<&'static Spec> { SPECS.iter().find(|s| s.long == name) }
fn spec_by_short(c: char) -> Option<&'static Spec> { SPECS.iter().find(|s| s.short == Some(c)) }

impl Spec {
    fn canonical(&self) -> String {
        match self.value_name {
            Some(v) => format!("--{} <{}>", self.long, v),
            None => format!("--{}", self.long),
        }
    }
    fn possible_values(&self) -> Option<&'static [&'static str]> {
        match self.id {
            Format => Some(&["jpeg", "png", "gif", "webp", "tiff", "original"]),
            JpegChroma => Some(&["4:4:4", "4:2:2", "4:2:0", "4:1:1", "auto"]),
            Overwrite => Some(&["all", "never", "bigger"]),
            _ => None,
        }
    }
}

// ---------- styling ----------
#[derive(Clone, Copy)]
pub struct Style { pub enabled: bool }
impl Style {
    pub fn wrap(&self, code: &str, s: &str) -> String {
        if self.enabled { format!("\x1b[{}m{}\x1b[0m", code, s) } else { s.to_string() }
    }
    pub fn bold(&self, s: &str) -> String { self.wrap("1", s) }
    pub fn yellow(&self, s: &str) -> String { self.wrap("33", s) }
    pub fn green(&self, s: &str) -> String { self.wrap("32", s) }
    pub fn red_bold(&self, s: &str) -> String {
        if self.enabled { format!("\x1b[1m\x1b[31m{}\x1b[0m", s) } else { s.to_string() }
    }
    pub fn heading(&self, s: &str) -> String {
        if self.enabled { format!("\x1b[1m\x1b[4m{}\x1b[0m", s) } else { s.to_string() }
    }
}

pub fn clap_color_stdout() -> bool { anstream_color(true) }
pub fn clap_color_stderr() -> bool { anstream_color(false) }
fn anstream_color(stdout: bool) -> bool {
    if let Ok(v) = env::var("CLICOLOR_FORCE") {
        if v != "0" { return true; }
    }
    if env::var_os("NO_COLOR").is_some() { return false; }
    if let Ok(v) = env::var("CLICOLOR") { if v == "0" { return false; } }
    if let Ok(v) = env::var("TERM") { if v == "dumb" { return false; } }
    if stdout { std::io::stdout().is_terminal() } else { std::io::stderr().is_terminal() }
}

// For the main report output (`colored`-style behaviour).
pub fn report_color() -> bool {
    if let Ok(v) = env::var("CLICOLOR_FORCE") {
        if v != "0" { return true; }
    }
    if env::var_os("NO_COLOR").is_some() { return false; }
    if let Ok(v) = env::var("CLICOLOR") { if v == "0" { return false; } }
    std::io::stdout().is_terminal()
}
// For progress bars (console-crate-style behaviour).
pub fn term_color(stdout: bool) -> bool {
    if env::var_os("NO_COLOR").is_some() { return false; }
    if let Ok(v) = env::var("CLICOLOR") { if v == "0" { return false; } }
    if let Ok(v) = env::var("CLICOLOR_FORCE") {
        if v != "0" { return true; }
    }
    if let Ok(v) = env::var("TERM") { if v == "dumb" { return false; } }
    if stdout { std::io::stdout().is_terminal() } else { std::io::stderr().is_terminal() }
}

fn bin_name() -> String {
    let mut args = env::args_os();
    if let Some(a0) = args.next() {
        if let Some(name) = Path::new(&a0).file_name() {
            let s = name.to_string_lossy().into_owned();
            if !s.is_empty() { return s; }
        }
    }
    "caesiumclt".to_string()
}

