fn spec(id: ArgId) -> &'static Spec { SPECS.iter().find(|s| s.id == id).unwrap() }
fn spec_by_long(name: &str) -> Option<&'static Spec> { SPECS.iter().find(|s| s.long == name) }
fn spec_by_short(c: char) -> Option<&'static Spec> { SPECS.iter().find(|s| s.short == Some(c)) }

impl Spec {
    fn canonical(&self) -> String {
        match self.value_name {
            Some(v) => format!("--{} <{}>", self.long, v),
            None => format!("--{}", self.long),
        }
    }
    fn possible_values(&self) -> Option<&'static [&'static str]> {
        match self.id {
            Format => Some(&["jpeg", "png", "gif", "webp", "tiff", "original"]),
            JpegChroma => Some(&["4:4:4", "4:2:2", "4:2:0", "4:1:1", "auto"]),
            Overwrite => Some(&["all", "never", "bigger"]),
            _ => None,
        }
    }
}

// ---------- styling ----------
#[derive(Clone, Copy)]
pub struct Style { pub enabled: bool }
impl Style {
    pub fn wrap(&self, code: &str, s: &str) -> String {
        if self.enabled { format!("\x1b[{}m{}\x1b[0m", code, s) } else { s.to_string() }
    }
    pub fn bold(&self, s: &str) -> String { self.wrap("1", s) }
    pub fn yellow(&self, s: &str) -> String { self.wrap("33", s) }
    pub fn green(&self, s: &str) -> String { self.wrap("32", s) }
    pub fn red_bold(&self, s: &str) -> String {
        if self.enabled { format!("\x1b[1m\x1b[31m{}\x1b[0m", s) } else { s.to_string() }
    }
    pub fn heading(&self, s: &str) -> String {
        if self.enabled { format!("\x1b[1m\x1b[4m{}\x1b[0m", s) } else { s.to_string() }
    }
}

pub fn clap_color_stdout() -> bool { anstream_color(true) }
pub fn clap_color_stderr() -> bool { anstream_color(false) }
fn anstream_color(stdout: bool) -> bool {
    if let Ok(v) = env::var("CLICOLOR_FORCE") {
        if v != "0" { return true; }
    }
    if env::var_os("NO_COLOR").is_some() { return false; }
    if let Ok(v) = env::var("CLICOLOR") { if v == "0" { return false; } }
    if let Ok(v) = env::var("TERM") { if v == "dumb" { return false; } }
    if stdout { std::io::stdout().is_terminal() } else { std::io::stderr().is_terminal() }
}

// For the main report output (`colored`-style behaviour).
pub fn report_color() -> bool {
    if let Ok(v) = env::var("CLICOLOR_FORCE") {
        if v != "0" { return true; }
    }
    if env::var_os("NO_COLOR").is_some() { return false; }
    if let Ok(v) = env::var("CLICOLOR") { if v == "0" { return false; } }
    std::io::stdout().is_terminal()
}
// For progress bars (console-crate-style behaviour).
pub fn term_color(stdout: bool) -> bool {
    if env::var_os("NO_COLOR").is_some() { return false; }
    if let Ok(v) = env::var("CLICOLOR") { if v == "0" { return false; } }
    if let Ok(v) = env::var("CLICOLOR_FORCE") {
        if v != "0" { return true; }
    }
    if let Ok(v) = env::var("TERM") { if v == "dumb" { return false; } }
    if stdout { std::io::stdout().is_terminal() } else { std::io::stderr().is_terminal() }
}

fn bin_name() -> String {
    let mut args = env::args_os();
    if let Some(a0) = args.next() {
        if let Some(name) = Path::new(&a0).file_name() {
            let s = name.to_string_lossy().into_owned();
            if !s.is_empty() { return s; }
        }
    }
    "caesiumclt".to_string()
}

