fn render_help(long: bool, bin: &str, style: Style) -> String {
    let plain = if long { HELP_LONG } else { HELP_SHORT }.replacen("__BIN__", bin, 1);
    if !style.enabled { return plain; }
    let mut out = String::new();
    for line in plain.lines() {
        if let Some(rest) = line.strip_prefix("Usage: ") {
            // rest begins with bin
            let after_bin = rest.strip_prefix(bin).unwrap_or(rest);
            out.push_str(&format!("{} {}{}\n", style.heading("Usage:"), style.bold(bin), after_bin));
        } else if line == "Arguments:" || line == "Options:" {
            out.push_str(&style.heading(line));
            out.push('\n');
        } else {
            out.push_str(&style_option_line(line, style));
            out.push('\n');
        }
    }
    out
}

fn style_option_line(line: &str, style: Style) -> String {
    // Possible values entries in the long help: "          - all:    ..."
    let trimmed = line.trim_start();
    let indent_len = line.len() - trimmed.len();
    let indent = &line[..indent_len];
    if indent_len == 10 {
        if let Some(rest) = trimmed.strip_prefix("- ") {
            if let Some(colon) = rest.find(':') {
                let (name, tail) = rest.split_at(colon);
                if !name.contains(' ') {
                    return format!("{}- {}{}", indent, style.bold(name), tail);
                }
            }
        }
        return line.to_string();
    }
    if !trimmed.starts_with('-') { return line.to_string(); }
    // "-q, --quality <QUALITY>" or "--lossless" or "-h, --help"
    let mut result = String::from(indent);
    let mut rest = trimmed;
    // short flag
    if rest.starts_with('-') && !rest.starts_with("--") {
        // up to comma or space
        let end = rest.find(|c| c == ',' || c == ' ').unwrap_or(rest.len());
        result.push_str(&style.bold(&rest[..end]));
        result.push_str(&rest[end..end + rest[end..].chars().take_while(|c| *c == ',' || *c == ' ').map(|c| c.len_utf8()).sum::<usize>()]);
        let consumed = result.len() - indent.len() - style_extra_len(&rest[..end], style);
        let _ = consumed;
        rest = &rest[end..];
        // skip ", "
        let skip: usize = rest.chars().take_while(|c| *c == ',' || *c == ' ').map(|c| c.len_utf8()).sum();
        rest = &rest[skip..];
    }
    if rest.starts_with("--") {
        let end = rest.find(' ').unwrap_or(rest.len());
        result.push_str(&style.bold(&rest[..end]));
        result.push_str(&rest[end..]);
    } else {
        result.push_str(rest);
    }
    result
}
fn style_extra_len(_s: &str, _style: Style) -> usize { 0 }

// ---------- suggestions ----------
fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() { return 1.0; }
    if a.is_empty() || b.is_empty() { return 0.0; }
    if a == b { return 1.0; }
    let match_dist = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut a_match = vec![false; a.len()];
    let mut b_match = vec![false; b.len()];
    let mut matches = 0usize;
    for i in 0..a.len() {
        let start = i.saturating_sub(match_dist);
        let end = (i + match_dist + 1).min(b.len());
        for j in start..end {
            if !b_match[j] && a[i] == b[j] {
                a_match[i] = true; b_match[j] = true; matches += 1; break;
            }
        }
    }
    if matches == 0 { return 0.0; }
    let mut transpositions = 0usize;
    let mut j = 0usize;
    for i in 0..a.len() {
        if a_match[i] {
            while !b_match[j] { j += 1; }
            if a[i] != b[j] { transpositions += 1; }
            j += 1;
        }
    }
    let m = matches as f64;
    (m / a.len() as f64 + m / b.len() as f64 + (m - (transpositions / 2) as f64) / m) / 3.0
}
fn jaro_winkler(a: &str, b: &str) -> f64 {
    let j = jaro(a, b);
    if j > 0.7 {
        let prefix = a.chars().zip(b.chars()).take_while(|(x, y)| x == y).take(4).count();
        j + 0.1 * prefix as f64 * (1.0 - j)
    } else { j }
}
fn did_you_mean(input: &str, candidates: &[String]) -> Option<String> {
    let mut best: Option<(f64, String)> = None;
    for cand in candidates {
        let conf = jaro_winkler(input, cand);
        if conf > 0.8 {
            match &best {
                Some((bc, _)) if *bc >= conf => {}
                _ => best = Some((conf, cand.clone())),
            }
        }
    }
    best.map(|(_, s)| s)
}

// ---------- usage ----------
fn usage_line(bin: &str, style: Style, used: &[ArgId], files_present: bool, fallback: bool) -> String {
    let mut s = format!("{} {}", style.heading("Usage:"), style.bold(bin));
    if fallback {
        s.push_str(" [OPTIONS]");
    } else {
        let mut seen: HashSet<ArgId> = HashSet::new();
        for id in used {
            if !seen.insert(*id) { continue; }
            let sp = spec(*id);
            if sp.group.is_some() { continue; }
            if *id == Files { continue; }
            s.push(' ');
            s.push_str(&style.bold(&format!("--{}", sp.long)));
            if let Some(v) = sp.value_name {
                s.push_str(&format!(" <{}>", v));
            }
        }
    }
    s.push_str(" <--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>> <--output <OUTPUT>|--same-folder-as-input>");
    if files_present && !fallback { s.push_str(" <FILES>..."); } else { s.push_str(" [FILES]..."); }
    s
}
fn for_more(style: Style) -> String {
    format!("For more information, try '{}'.", style.bold("--help"))
}

// ---------- byte size parsing ----------
fn parse_unit(unit: &str) -> Option<u64> {
    let u = unit.to_ascii_uppercase();
    let v: u64 = match u.as_str() {
        "B" => 1,
        "K" | "KB" => 1_000,
        "KI" | "KIB" => 1_024,
        "M" | "MB" => 1_000u64.pow(2),
        "MI" | "MIB" => 1_024u64.pow(2),
        "G" | "GB" => 1_000u64.pow(3),
        "GI" | "GIB" => 1_024u64.pow(3),
        "T" | "TB" => 1_000u64.pow(4),
        "TI" | "TIB" => 1_024u64.pow(4),
        "P" | "PB" => 1_000u64.pow(5),
        "PI" | "PIB" => 1_024u64.pow(5),
        "E" | "EB" => 1_000u64.pow(6),
        "EI" | "EIB" => 1_024u64.pow(6),
        _ => return None,
    };
    Some(v)
}
fn parse_byte_size(s: &str) -> Result<u64, String> {
    if let Ok(v) = s.parse::<u64>() { return Ok(v); }
    let mut number_end = s.len();
    for (i, c) in s.char_indices() {
        if !(c.is_ascii_digit() || c == '.') { number_end = i; break; }
    }
    let (number, rest) = s.split_at(number_end);
    let value: f64 = number.parse::<f64>().map_err(|e| format!("couldn't parse {:?} into a ByteSize, {}", s, e))?;
    let unit_str = rest.trim_start();
    let mult = parse_unit(unit_str).ok_or_else(|| format!("couldn't parse {:?} into a known SI unit, Failed to parse unit \"{}\"", unit_str, unit_str))?;
    Ok((value * mult as f64) as u64)
}
fn parse_max_size(s: &str) -> Result<u64, String> {
    parse_byte_size(s).map_err(|e| format!("Invalid size format: {}", e))
}
fn parse_min_savings(s: &str) -> Result<MinSavings, String> {
    let trimmed = s.trim();
    if trimmed.is_empty() {
        return Err("Value cannot be empty. Use percentage (e.g., '10%'), size with unit (e.g., '100KB', '1MB'), or plain number as bytes".to_string());
    }
    if let Some(pct_part) = trimmed.strip_suffix('%') {
        let pct_str = pct_part.trim();
        let pct: f64 = pct_str.parse::<f64>().map_err(|_| format!("Invalid percentage value: '{}'", pct_str))?;
        if !(0.0..=100.0).contains(&pct) {
            return Err(format!("Percentage must be between 0 and 100, got {}", pct));
        }
        return Ok(MinSavings::Percent(pct));
    }
    match parse_byte_size(trimmed) {
        Ok(v) => Ok(MinSavings::Absolute(v)),
        Err(_) => Err(format!("Invalid size format: '{}'. Use percentage (e.g., '10%'), size with unit (e.g., '100KB', '1MB'), or plain number as bytes", s)),
    }
}

// ---------- parser ----------
struct Occ {
    id: ArgId,
    value: Option<OsString>,
    validated: bool,
}

struct Parser {
    bin: String,
    style: Style,
    occs: Vec<Occ>,
    files: Vec<OsString>,
    args: Args,
}

impl Parser {
    fn error_header(&self) -> String { self.style.red_bold("error:") }
    fn used_ids(&self) -> Vec<ArgId> { self.occs.iter().map(|o| o.id).collect() }
    fn files_present(&self) -> bool { !self.files.is_empty() }

    fn err_unknown_long(&self, display: &str) -> CliExit {
        let candidates: Vec<String> = SPECS.iter().map(|s| format!("--{}", s.long)).collect();
        let suggestion = did_you_mean(display, &candidates);
        let mut used = self.used_ids();
        let mut tip;
        if let Some(sugg) = &suggestion {
            if let Some(sp) = spec_by_long(&sugg[2..]) { used.push(sp.id); }
            tip = format!("  {} a similar argument exists: '{}'", self.style.green("tip:"), self.style.green(sugg));
        } else {
            tip = format!("  {} to pass '{}' as a value, use '{}'", self.style.green("tip:"), self.style.yellow(display), self.style.green(&format!("-- {}", display)));
        }
        let usage = usage_line(&self.bin, self.style, &used, self.files_present(), false);
        // If no used args at all and no suggestion, clap uses the full fallback usage.
        let usage = if used.is_empty() && !self.files_present() {
            usage_line(&self.bin, self.style, &[], false, true)
        } else { usage };
        CliExit::err(format!(
            "{} unexpected argument '{}' found\n\n{}\n\n{}\n\n{}\n",
            self.error_header(), self.style.yellow(display), tip, usage, for_more(self.style)
        ))
    }
    fn err_unknown_short(&self, c: char) -> CliExit {
        let display = format!("-{}", c);
        let usage = usage_line(&self.bin, self.style, &[], false, true);
        CliExit::err(format!(
            "{} unexpected argument '{}' found\n\n  {} to pass '{}' as a value, use '{}'\n\n{}\n\n{}\n",
            self.error_header(), self.style.yellow(&display), self.style.green("tip:"),
            self.style.yellow(&display), self.style.green(&format!("-- {}", display)), usage, for_more(self.style)
        ))
    }
    fn err_missing_value(&self, sp: &Spec) -> CliExit {
        let mut s = format!("{} a value is required for '{}' but none was supplied\n", self.error_header(), self.style.yellow(&sp.canonical()));
        if let Some(vals) = sp.possible_values() {
            let list: Vec<String> = vals.iter().map(|v| self.style.green(v)).collect();
            s.push_str(&format!("  [possible values: {}]\n", list.join(", ")));
        }
        s.push_str(&format!("\n{}\n", for_more(self.style)));
        CliExit::err(s)
    }
    fn err_unexpected_value(&self, sp: &Spec, val: &str) -> CliExit {
        let mut used = self.used_ids();
        used.push(sp.id);
        let usage = usage_line(&self.bin, self.style, &used, self.files_present(), false);
        CliExit::err(format!(
            "{} unexpected value '{}' for '{}' found; no more were expected\n\n{}\n\n{}\n",
            self.error_header(), self.style.yellow(val), self.style.bold(&format!("--{}", sp.long)), usage, for_more(self.style)
        ))
    }
    fn err_multiple(&self, sp: &Spec) -> CliExit {
        let usage = usage_line(&self.bin, self.style, &[], false, true);
        CliExit::err(format!(
            "{} the argument '{}' cannot be used multiple times\n\n{}\n\n{}\n",
            self.error_header(), self.style.yellow(&sp.canonical()), usage, for_more(self.style)
        ))
    }
    fn err_invalid_utf8(&self) -> CliExit {
        let usage = usage_line(&self.bin, self.style, &[], false, true);
        CliExit::err(format!(
            "{} invalid UTF-8 was detected in one or more arguments\n\n{}\n\n{}\n",
            self.error_header(), usage, for_more(self.style)
        ))
    }
    fn err_invalid_value(&self, sp: &Spec, val: &str, reason: Option<String>) -> CliExit {
        let mut s;
        if let Some(vals) = sp.possible_values() {
            s = format!("{} invalid value '{}' for '{}'\n", self.error_header(), self.style.yellow(val), self.style.bold(&sp.canonical()));
            let list: Vec<String> = vals.iter().map(|v| self.style.green(v)).collect();
            s.push_str(&format!("  [possible values: {}]\n", list.join(", ")));
            let cands: Vec<String> = vals.iter().map(|v| v.to_string()).collect();
            if let Some(sugg) = did_you_mean(val, &cands) {
                s.push_str(&format!("\n  {} a similar value exists: '{}'\n", self.style.green("tip:"), self.style.green(&sugg)));
            }
        } else {
            s = format!("{} invalid value '{}' for '{}': {}\n", self.error_header(), self.style.yellow(val), self.style.bold(&sp.canonical()), reason.unwrap_or_default());
        }
        s.push_str(&format!("\n{}\n", for_more(self.style)));
        CliExit::err(s)
    }

    fn validate_value(&mut self, idx: usize) -> Result<(), CliExit> {
        let (id, raw) = {
            let occ = &self.occs[idx];
            (occ.id, occ.value.clone())
        };
        let sp = spec(id);
        if sp.value_name.is_none() {
            match id {
                Lossless => self.args.lossless = true,
                NoUpscale => self.args.no_upscale = true,
                SameFolder => self.args.same_folder_as_input = true,
                JpegBaseline => self.args.jpeg_baseline = true,
                Zopfli => self.args.zopfli = true,
                Exif => self.args.exif = true,
                KeepDates => self.args.keep_dates = true,
                StripIcc => self.args.strip_icc = true,
                Recursive => self.args.recursive = true,
                KeepStructure => self.args.keep_structure = true,
                DryRun => self.args.dry_run = true,
                Quiet => self.args.quiet = true,
                _ => {}
            }
            self.occs[idx].validated = true;
            return Ok(());
        }
        let raw_os = raw.unwrap_or_default();
        // Enum parsers operate on a lossy string; other string based parsers
        // reject invalid UTF-8.  The output path accepts arbitrary bytes.
        if id == Output {
            self.args.output = Some(PathBuf::from(raw_os));
            self.occs[idx].validated = true;
            return Ok(());
        }
        let is_enum = matches!(id, Format | JpegChroma | Overwrite);
        let value_string: String = if is_enum {
            raw_os.to_string_lossy().into_owned()
        } else {
            match raw_os.to_str() {
                Some(s) => s.to_string(),
                None => return Err(self.err_invalid_utf8()),
            }
        };
        let val = value_string.as_str();
        macro_rules! invalid {
            ($reason:expr) => { return Err(self.err_invalid_value(sp, val, Some($reason))) };
        }
        match id {
            Quality => {
                let v: u32 = match val.parse() { Ok(v) => v, Err(_) => invalid!(format!("'{}' is not a valid number", val)) };
                if v > 100 { invalid!(format!("Quality must be between 0 and 100, but got {}", v)); }
                self.args.quality = Some(v as u8);
            }
            MaxSize => {
                match parse_max_size(val) { Ok(v) => self.args.max_size = Some(v), Err(e) => invalid!(e) }
            }
            Width | Height | LongEdge | ShortEdge | Threads => {
                let v: i64 = match val.parse() { Ok(v) => v, Err(e) => invalid!(e.to_string()) };
                if !(0..=4294967295i64).contains(&v) { invalid!(format!("{} is not in 0..=4294967295", v)); }
                let v = v as u32;
                match id {
                    Width => self.args.width = Some(v),
                    Height => self.args.height = Some(v),
                    LongEdge => self.args.long_edge = Some(v),
                    ShortEdge => self.args.short_edge = Some(v),
                    _ => self.args.threads = v,
                }
            }
            PngOptLevel => {
                let v: u8 = match val.parse() { Ok(v) => v, Err(_) => invalid!(format!("'{}' is not a valid number", val)) };
                if v > 6 { invalid!(format!("PNG optimization level must be between 0 and 6, but got {}", v)); }
                self.args.png_opt_level = v;
            }
            Verbose => {
                let v: u8 = match val.parse() { Ok(v) => v, Err(_) => invalid!(format!("'{}' is not a valid number", val)) };
                if v > 3 { invalid!(format!("Verbosity must be between 0 and 3, but got {}", v)); }
                self.args.verbose = v;
            }
            Format => {
                self.args.format = match val {
                    "jpeg" => OutputFormat::Jpeg, "png" => OutputFormat::Png, "gif" => OutputFormat::Gif,
                    "webp" => OutputFormat::Webp, "tiff" => OutputFormat::Tiff, "original" => OutputFormat::Original,
                    _ => return Err(self.err_invalid_value(sp, val, None)),
                };
            }
            JpegChroma => {
                self.args.jpeg_chroma_subsampling = match val {
                    "4:4:4" => Chroma::C444, "4:2:2" => Chroma::C422, "4:2:0" => Chroma::C420,
                    "4:1:1" => Chroma::C411, "auto" => Chroma::Auto,
                    _ => return Err(self.err_invalid_value(sp, val, None)),
                };
            }
            Overwrite => {
                self.args.overwrite = match val {
                    "all" => OverwritePolicy::All, "never" => OverwritePolicy::Never, "bigger" => OverwritePolicy::Bigger,
                    _ => return Err(self.err_invalid_value(sp, val, None)),
                };
            }
            Suffix => { self.args.suffix = Some(value_string.clone()); }
            MinSavings => {
                match parse_min_savings(val) { Ok(v) => self.args.min_savings = Some(v), Err(e) => invalid!(e) }
            }
            _ => {}
        }
        self.occs[idx].validated = true;
        Ok(())
    }

    fn validate_pending(&mut self) -> Result<(), CliExit> {
        for i in 0..self.occs.len() {
            if !self.occs[i].validated { self.validate_value(i)?; }
        }
        Ok(())
    }

    fn check_conflicts(&self) -> Result<(), CliExit> {
        let present: Vec<ArgId> = self.occs.iter().map(|o| o.id).collect();
        let has = |id: ArgId| present.contains(&id);
        for (i, id) in present.iter().enumerate() {
            for other in present.iter().skip(i + 1) {
                if conflicts(*id, *other) {
                    let usage = usage_line(&self.bin, self.style, &present, self.files_present(), false);
                    return Err(CliExit::err(format!(
                        "{} the argument '{}' cannot be used with '{}'\n\n{}\n\n{}\n",
                        self.error_header(), self.style.yellow(&spec(*id).canonical()),
                        self.style.yellow(&spec(*other).canonical()), usage, for_more(self.style)
                    )));
                }
            }
            let _ = has;
        }
        Ok(())
    }

    fn check_required(&self) -> Result<(), CliExit> {
        let present: Vec<ArgId> = self.occs.iter().map(|o| o.id).collect();
        let compression = present.iter().any(|id| spec(*id).group == Some(0));
        let output = present.iter().any(|id| spec(*id).group == Some(1));
        if compression && output { return Ok(()); }
        let mut s = format!("{} the following required arguments were not provided:\n", self.error_header());
        if !compression {
            s.push_str(&format!("  {}\n", self.style.green("<--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>>")));
        }
        if !output {
            s.push_str(&format!("  {}\n", self.style.green("<--output <OUTPUT>|--same-folder-as-input>")));
        }
        let usage = usage_line(&self.bin, self.style, &present, self.files_present(), false);
        s.push_str(&format!("\n{}\n\n{}\n", usage, for_more(self.style)));
        Err(CliExit::err(s))
    }
}

fn conflicts(a: ArgId, b: ArgId) -> bool {
    let (ga, gb) = (spec(a).group, spec(b).group);
    if ga.is_some() && ga == gb && a != b { return true; }
    let pair = |x, y| (a == x && b == y) || (a == y && b == x);
    pair(Width, LongEdge) || pair(Width, ShortEdge) || pair(Height, LongEdge) || pair(Height, ShortEdge)
        || pair(LongEdge, ShortEdge) || pair(Quiet, Verbose)
}

#[derive(Clone, Copy, PartialEq)]
enum NextClass { Value, Missing, Unknown }

fn token_is_option_like(tok: &OsString) -> NextClass {
    let bytes = os_bytes(tok);
    if bytes == b"--" { return NextClass::Missing; }
    if bytes.len() < 2 || bytes[0] != b'-' { return NextClass::Value; }
    if bytes == b"-" { return NextClass::Value; }
    let lossy = tok.to_string_lossy();
    if lossy.starts_with("--") {
        let name = &lossy[2..];
        let name = name.split('=').next().unwrap_or("");
        if spec_by_long(name).is_some() { NextClass::Missing } else { NextClass::Unknown }
    } else {
        let c = lossy[1..].chars().next().unwrap_or('\0');
        if spec_by_short(c).is_some() { NextClass::Missing } else { NextClass::Unknown }
    }
}

#[cfg(unix)]
fn os_bytes(s: &OsStr) -> Vec<u8> {
    use std::os::unix::ffi::OsStrExt;
    s.as_bytes().to_vec()
}
#[cfg(not(unix))]
fn os_bytes(s: &OsStr) -> Vec<u8> { s.to_string_lossy().into_owned().into_bytes() }

pub fn parse() -> Result<Args, CliExit> {
    let argv: Vec<OsString> = env::args_os().skip(1).collect();
    parse_from(argv)
}

pub fn parse_from(argv: Vec<OsString>) -> Result<Args, CliExit> {
    let bin = bin_name();
    let mut parser = Parser {
        bin: bin.clone(),
        style: Style { enabled: clap_color_stderr() },
        occs: Vec::new(),
        files: Vec::new(),
        args: Args::default(),
    };
    let stdout_style = Style { enabled: clap_color_stdout() };
    let mut only_positional = false;
    let mut i = 0usize;
    while i < argv.len() {
        let tok = argv[i].clone();
        let bytes = os_bytes(&tok);
        if !only_positional && bytes == b"--" {
            parser.validate_pending()?;
            only_positional = true;
            i += 1;
            continue;
        }
        if !only_positional && bytes.len() > 2 && bytes.starts_with(b"--") {
            // long option
            let lossy = tok.to_string_lossy().into_owned();
            let body = &lossy[2..];
            let (name, attached) = match body.find('=') {
                Some(pos) => (&body[..pos], Some(OsString::from(&body[pos + 1..]))),
                None => (body, None),
            };
            let display = format!("--{}", name);
            let sp = match spec_by_long(name) {
                Some(s) => s,
                None => return Err(parser.err_unknown_long(&display)),
            };
            if sp.value_name.is_none() && attached.is_some() {
                let val = attached.as_ref().unwrap().to_string_lossy().into_owned();
                return Err(parser.err_unexpected_value(sp, &val));
            }
            // Recognised token: validate prior pending values first.
            parser.validate_pending()?;
            if sp.id == Help {
                return Err(CliExit::out(render_help(true, &bin, stdout_style)));
            }
            if sp.id == Version {
                return Err(CliExit::out("caesiumclt 1.3.0\n".to_string()));
            }
            if sp.value_name.is_some() {
                let value: OsString = if let Some(v) = attached {
                    v
                } else {
                    match argv.get(i + 1) {
                        None => return Err(parser.err_missing_value(sp)),
                        Some(next) => match token_is_option_like(next) {
                            NextClass::Value => { i += 1; next.clone() }
                            NextClass::Missing => return Err(parser.err_missing_value(sp)),
                            NextClass::Unknown => { i += 1; continue; }
                        },
                    }
                };
                if value.is_empty() && sp.empty_is_missing {
                    return Err(parser.err_missing_value(sp));
                }
                if parser.occs.iter().any(|o| o.id == sp.id) {
                    return Err(parser.err_multiple(sp));
                }
                parser.occs.push(Occ { id: sp.id, value: Some(value), validated: false });
            } else {
                if parser.occs.iter().any(|o| o.id == sp.id) {
                    return Err(parser.err_multiple(sp));
                }
                parser.occs.push(Occ { id: sp.id, value: None, validated: false });
            }
            i += 1;
            continue;
        }
        if !only_positional && bytes.len() > 1 && bytes[0] == b'-' && bytes != b"-" && !bytes.starts_with(b"--") {
            let lossy = tok.to_string_lossy().into_owned();
            let cluster: Vec<char> = lossy[1..].chars().collect();
            if cluster.is_empty() {
                parser.validate_pending()?;
                parser.files.push(tok.clone());
                i += 1;
                continue;
            }
            // First char must be recognised before pending validation happens.
            if spec_by_short(cluster[0]).is_none() {
                return Err(parser.err_unknown_short(cluster[0]));
            }
            parser.validate_pending()?;
            let mut j = 0usize;
            let mut consumed_next = false;
            while j < cluster.len() {
                let c = cluster[j];
                let sp = match spec_by_short(c) {
                    Some(s) => s,
                    None => return Err(parser.err_unknown_short(c)),
                };
                if sp.id == Help {
                    return Err(CliExit::out(render_help(false, &bin, stdout_style)));
                }
                if sp.id == Version {
                    return Err(CliExit::out("caesiumclt 1.3.0\n".to_string()));
                }
                if sp.value_name.is_some() {
                    // Remainder of the cluster is the value.
                    let rest: String = cluster[j + 1..].iter().collect();
                    let value: OsString = if let Some(v) = rest.strip_prefix('=') {
                        OsString::from(v)
                    } else if !rest.is_empty() {
                        OsString::from(&rest)
                    } else {
                        match argv.get(i + 1) {
                            None => return Err(parser.err_missing_value(sp)),
                            Some(next) => match token_is_option_like(next) {
                                NextClass::Value => { consumed_next = true; next.clone() }
                                NextClass::Missing => return Err(parser.err_missing_value(sp)),
                                NextClass::Unknown => {
                                    // Skip this whole option; the unknown
                                    // token will be handled next iteration.
                                    // Discard the booleans already pushed in
                                    // this cluster? clap keeps them as used
                                    // only for long errors; short unknown
                                    // errors use fallback usage anyway.
                                    consumed_next = false;
                                    // break out with a sentinel
                                    // (value stays unset)
                                    // We emulate by jumping i to next token.
                                    // Use a flag via empty value + missing check below.
                                    // Simpler: advance i and restart loop.
                                    // (handled after while loop)
                                    // Mark by setting j beyond and a flag.
                                    // NOTE: implemented by early continue of outer loop.
                                    // To do that we use a goto-like flag:
                                    // store in `consumed_next` = false and set a var.
                                    // We'll break with special handling:
                                    // SAFETY: use a panic-free return path:
                                    // set i += 1 and continue outer by returning from closure is
                                    // not possible; use a label via loop control below.
                                    // We instead directly process the unknown token:
                                    // (it is at i+1)
                                    // Fall through to unknown handling by
                                    // incrementing i and using `continue` on
                                    // the outer while (achieved by setting a flag).
                                    // --- implemented below with `skip_to_next` ---
                                    OsString::new() // placeholder, replaced below
                                }
                            },
                        }
                    };
                    // Handle the "next token is unknown" case: if there was
                    // no attached value and the next token classifies as
                    // Unknown, abandon this option and let the outer loop
                    // process that token.
                    if rest.is_empty() {
                        if let Some(next) = argv.get(i + 1) {
                            if token_is_option_like(next) == NextClass::Unknown {
                                i += 1;
                                // restart outer loop without recording
                                // (booleans earlier in cluster remain)
                                // Use a marker: break inner loop and skip i increment at end.
                                // We set a flag on the parser by abusing consumed_next.
                                // Simplest: go to next outer iteration:
                                // (Rust: use a labelled block)
                                // We achieve it by setting a local and breaking.
                                // NOTE: see `goto_next` below.
                                // To keep control flow simple we directly
                                // return the unknown error for that token:
                                let ntok = next.clone();
                                let nlossy = ntok.to_string_lossy().into_owned();
                                if nlossy.starts_with("--") {
                                    let body2 = &nlossy[2..];
                                    let name2 = body2.split('=').next().unwrap_or("");
                                    return Err(parser.err_unknown_long(&format!("--{}", name2)));
                                } else {
                                    let c2 = nlossy[1..].chars().next().unwrap_or('\0');
                                    return Err(parser.err_unknown_short(c2));
                                }
                            }
                        }
                    }
                    if value.is_empty() && sp.empty_is_missing {
                        return Err(parser.err_missing_value(sp));
                    }
                    if parser.occs.iter().any(|o| o.id == sp.id) {
                        return Err(parser.err_multiple(sp));
                    }
                    parser.occs.push(Occ { id: sp.id, value: Some(value), validated: false });
                    j = cluster.len();
                } else {
                    if parser.occs.iter().any(|o| o.id == sp.id) {
                        return Err(parser.err_multiple(sp));
                    }
                    parser.occs.push(Occ { id: sp.id, value: None, validated: false });
                    j += 1;
                }
            }
            if consumed_next { i += 1; }
            i += 1;
            continue;
        }
        // positional
        parser.validate_pending()?;
        parser.files.push(tok.clone());
        i += 1;
    }
    parser.validate_pending()?;
    // Files must be valid UTF-8 (Vec<String> in the original).
    let mut files: Vec<String> = Vec::new();
    for f in &parser.files {
        match f.to_str() {
            Some(s) => files.push(s.to_string()),
            None => return Err(parser.err_invalid_utf8()),
        }
    }
    parser.args.files = files;
    parser.check_conflicts()?;
    parser.check_required()?;
    Ok(parser.args)
}
RS
