use std::collections::HashMap;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ColorKind { L8, La8, Rgb8, Rgba8, L16, La16, Rgb16, Rgba16 }
impl ColorKind {
    pub fn channels(&self) -> usize {
        match self { Self::L8 | Self::L16 => 1, Self::La8 | Self::La16 => 2, Self::Rgb8 | Self::Rgb16 => 3, Self::Rgba8 | Self::Rgba16 => 4 }
