    }
}

#[derive(Clone, Debug)]
pub struct Raster {
    pub width: u32,
    pub height: u32,
    pub kind: ColorKind,
    // Samples packed in row-major order. 16-bit samples are stored little-endian.
    pub data: Vec<u8>,
}

impl Raster {
    pub fn new(width: u32, height: u32, kind: ColorKind, data: Vec<u8>) -> Self { Self { width, height, kind, data } }
    pub fn pixel_count(&self) -> usize { (self.width as usize) * (self.height as usize) }
    pub fn bytes_per_pixel(&self) -> usize { self.kind.channels() * self.kind.sample_bytes() }
    pub fn sample(&self, pixel: usize, channel: usize) -> u32 {
        let idx = (pixel * self.kind.channels() + channel) * self.kind.sample_bytes();
        if self.kind.sample_bytes() == 2 {
            u16::from_le_bytes([self.data[idx], self.data[idx + 1]]) as u32
        } else { self.data[idx] as u32 }
    }
    pub fn set_sample(&mut self, pixel: usize, channel: usize, v: u32) {
        let idx = (pixel * self.kind.channels() + channel) * self.kind.sample_bytes();
        if self.kind.sample_bytes() == 2 {
            self.data[idx..idx + 2].copy_from_slice(&(v as u16).to_le_bytes());
        } else { self.data[idx] = v as u8; }
    }
    pub fn max_sample(&self) -> u32 { if self.kind.is_16() { 65535 } else { 255 } }

    pub fn rgba8(&self) -> Vec<u8> {
        let mut out = vec![0u8; self.pixel_count() * 4];
        let ch = self.kind.channels();
        for i in 0..self.pixel_count() {
            let s = |c: usize| -> u8 {
                let v = self.sample(i, c);
                if self.kind.is_16() { (v >> 8) as u8 } else { v as u8 }
            };
            let px = match ch {
                1 => { let g = s(0); [g, g, g, 255] }
                2 => { let g = s(0); [g, g, g, s(1)] }
                3 => [s(0), s(1), s(2), 255],
                _ => [s(0), s(1), s(2), s(3)],
            };
            out[i * 4..i * 4 + 4].copy_from_slice(&px);
        }
        out
    }

    pub fn from_rgba8(width: u32, height: u32, rgba: Vec<u8>) -> Self {
        Self::new(width, height, ColorKind::Rgba8, rgba)
    }

    // Convert to the 8-bit version of the same colour kind.
    pub fn to_8bit(&self) -> Raster {
        if !self.kind.is_16() { return self.clone(); }
        let mut out = Raster::new(self.width, self.height, self.kind.to_8(), vec![0; self.pixel_count() * self.kind.channels()]);
        for i in 0..self.pixel_count() {
            for c in 0..self.kind.channels() {
                out.set_sample(i, c, self.sample(i, c) >> 8);
            }
        }
        out
    }

    pub fn has_alpha(&self) -> bool {
        if !self.kind.has_alpha() { return false; }
        let ac = self.kind.channels() - 1;
        let max = self.max_sample();
        (0..self.pixel_count()).any(|i| self.sample(i, ac) < max)
    }

    pub fn apply_orientation(&self, orientation: u16) -> Raster {
        if !(1..=8).contains(&orientation) || orientation == 1 { return self.clone(); }
        let (w, h) = (self.width as i64, self.height as i64);
        let swap = orientation >= 5;
        let (ow, oh) = if swap { (h as u32, w as u32) } else { (w as u32, h as u32) };
        let bpp = self.bytes_per_pixel();
        let mut out = vec![0u8; (ow as usize) * (oh as usize) * bpp];
        for y in 0..h {
            for x in 0..w {
                let (ox, oy): (i64, i64) = match orientation {
                    2 => (w - 1 - x, y),
                    3 => (w - 1 - x, h - 1 - y),
                    4 => (x, h - 1 - y),
                    5 => (y, x),
                    6 => (h - 1 - y, x),
                    7 => (h - 1 - y, w - 1 - x),
                    8 => (y, w - 1 - x),
                    _ => (x, y),
                };
                let src = ((y as u32 * self.width + x as u32) as usize) * bpp;
                let dst = ((oy as u32 * ow + ox as u32) as usize) * bpp;
                out[dst..dst + bpp].copy_from_slice(&self.data[src..src + bpp]);
            }
        }
        Raster::new(ow, oh, self.kind, out)
    }

    pub fn resize(&self, new_w: u32, new_h: u32) -> Raster {
        if new_w == self.width && new_h == self.height { return self.clone(); }
        // Vertical pass first, then horizontal (as in common Rust image code).
        let mut cur = self.clone();
        if new_h != cur.height {
            cur = resample_axis(&cur, new_h, true);
        }
        if new_w != cur.width {
            cur = resample_axis(&cur, new_w, false);
        }
        cur
    }
}

fn lanczos3(x: f32) -> f32 {
    if x == 0.0 { return 1.0; }
    let ax = x.abs();
    if ax >= 3.0 { return 0.0; }
    let px = std::f32::consts::PI * x;
    (px.sin() / px) * ((px / 3.0).sin() / (px / 3.0))
}

fn coefficients(in_size: u32, out_size: u32) -> Vec<Vec<(usize, f32)>> {
    let ratio = in_size as f32 / out_size as f32;
    let scale = ratio.max(1.0);
    let support = 3.0 * scale;
    let mut result = Vec::with_capacity(out_size as usize);
    for o in 0..out_size {
        let center = (o as f32 + 0.5) * ratio - 0.5;
        let mut start = (center - support).ceil() as i64;
        let mut end = (center + support).floor() as i64;
        if start < 0 { start = 0; }
        if end > in_size as i64 - 1 { end = in_size as i64 - 1; }
        let mut coeffs = Vec::new();
        let mut sum = 0.0f32;
        for i in start..=end {
            let w = lanczos3((i as f32 - center) / scale);
            if w != 0.0 { coeffs.push((i as usize, w)); sum += w; }
        }
        if coeffs.is_empty() {
            let nearest = ((o as usize) * (in_size as usize) / (out_size as usize)).min(in_size as usize - 1);
            coeffs.push((nearest, 1.0));
            sum = 1.0;
        }
        if sum != 0.0 {
            for c in coeffs.iter_mut() { c.1 /= sum; }
        }
        result.push(coeffs);
    }
    result
}

fn resample_axis(img: &Raster, new_size: u32, vertical: bool) -> Raster {
    let ch = img.kind.channels();
    let max = img.max_sample() as f32;
    if vertical {
        let coeffs = coefficients(img.height, new_size);
        let mut out = Raster::new(img.width, new_size, img.kind, vec![0; (img.width as usize) * (new_size as usize) * img.bytes_per_pixel()]);
        for oy in 0..new_size as usize {
            for x in 0..img.width as usize {
                for c in 0..ch {
                    let mut acc = 0.0f32;
                    for (iy, w) in &coeffs[oy] {
                        acc += img.sample(iy * img.width as usize + x, c) as f32 * w;
                    }
                    out.set_sample(oy * img.width as usize + x, c, acc.clamp(0.0, max).round() as u32);
                }
            }
        }
        out
    } else {
        let coeffs = coefficients(img.width, new_size);
        let mut out = Raster::new(new_size, img.height, img.kind, vec![0; (new_size as usize) * (img.height as usize) * img.bytes_per_pixel()]);
        for y in 0..img.height as usize {
            for ox in 0..new_size as usize {
                for c in 0..ch {
                    let mut acc = 0.0f32;
                    for (ix, w) in &coeffs[ox] {
                        acc += img.sample(y * img.width as usize + ix, c) as f32 * w;
                    }
                    out.set_sample(y * new_size as usize + ox, c, acc.clamp(0.0, max).round() as u32);
                }
            }
        }
        out
    }
}

// ---------- metadata ----------
#[derive(Clone, Debug, Default)]
pub struct Metadata {
    pub exif: Option<Vec<u8>>,
    pub icc: Option<Vec<u8>>,
    pub orientation: Option<u16>,
}

pub fn exif_orientation(exif: &[u8]) -> Option<u16> {
    // TIFF header inside the EXIF payload.
    if exif.len() < 8 { return None; }
    let le = match &exif[0..2] { b"II" => true, b"MM" => false, _ => return None };
    let rd16 = |o: usize| -> Option<u16> {
        if o + 2 > exif.len() { return None; }
        Some(if le { u16::from_le_bytes([exif[o], exif[o + 1]]) } else { u16::from_be_bytes([exif[o], exif[o + 1]]) })
    };
    let rd32 = |o: usize| -> Option<u32> {
        if o + 4 > exif.len() { return None; }
        Some(if le { u32::from_le_bytes([exif[o], exif[o+1], exif[o+2], exif[o+3]]) } else { u32::from_be_bytes([exif[o], exif[o+1], exif[o+2], exif[o+3]]) })
    };
    if rd16(2)? != 42 { return None; }
    let mut ifd = rd32(4)? as usize;
    for _ in 0..8 {
        if ifd == 0 { return None; }
        let count = rd16(ifd)? as usize;
        for i in 0..count {
            let e = ifd + 2 + i * 12;
            if e + 12 > exif.len() { return None; }
            let tag = rd16(e)?;
            if tag == 0x0112 {
                let typ = rd16(e + 2)?;
                let cnt = rd32(e + 4)?;
                if typ == 3 && cnt >= 1 {
                    return rd16(e + 8);
                }
                if typ == 4 && cnt >= 1 {
                    return rd32(e + 8).map(|v| v as u16);
                }
                return None;
            }
            if tag == 0x8769 {
                if let Some(off) = rd32(e + 8) {
                    // Search the EXIF sub-IFD for orientation as well.
                    let saved = ifd;
                    let _ = saved;
                    // simple inline scan
                    let sub = off as usize;
                    if let Some(c2) = rd16(sub) {
                        for k in 0..c2 as usize {
                            let e2 = sub + 2 + k * 12;
                            if rd16(e2) == Some(0x0112) { return rd16(e2 + 8); }
                        }
                    }
                }
            }
        }
        let next_off = ifd + 2 + count * 12;
        ifd = rd32(next_off)? as usize;
    }
    None
}

// ---------- quantisation ----------
pub struct Quantized {
    pub palette: Vec<[u8; 4]>,
    pub indices: Vec<u8>,
    pub pixels: Vec<u8>, // RGBA8 after mapping / dithering
}

struct ColorBox {
    colors: Vec<([u8; 4], u32)>,
    total: u64,
}

impl ColorBox {
    fn mean_and_error(&self) -> ([f64; 4], f64) {
        // Premultiplied mean for the palette colour and straight mean for error.
        let mut sums = [0f64; 4];
        let mut sum_a = 0f64;
        let mut prem = [0f64; 3];
        for (c, n) in &self.colors {
            let n = *n as f64;
            for k in 0..4 { sums[k] += c[k] as f64 * n; }
            let a = c[3] as f64 / 255.0;
            sum_a += c[3] as f64 * n;
            for k in 0..3 { prem[k] += c[k] as f64 * a * n; }
        }
        let total = self.total.max(1) as f64;
        let straight = [sums[0] / total, sums[1] / total, sums[2] / total, sums[3] / total];
        let mut err = 0f64;
        for (c, n) in &self.colors {
            let mut d = 0f64;
            for k in 0..4 { let diff = c[k] as f64 - straight[k]; d += diff * diff; }
            err += d * *n as f64;
        }
        let alpha = sum_a / total;
        let mean = if sum_a > 0.0 {
            [prem[0] * 255.0 / sum_a, prem[1] * 255.0 / sum_a, prem[2] * 255.0 / sum_a, alpha]
        } else { straight };
        (mean, err)
    }
}

fn split_box(b: ColorBox) -> Vec<ColorBox> {
    if b.colors.len() <= 1 { return vec![b]; }
    let mut mins = [255u8; 4];
    let mut maxs = [0u8; 4];
    for (c, _) in &b.colors {
        for k in 0..4 { mins[k] = mins[k].min(c[k]); maxs[k] = maxs[k].max(c[k]); }
    }
    let mut channel = 0usize;
    let mut best_range = 0i32;
    for k in 0..4 {
        let r = maxs[k] as i32 - mins[k] as i32;
        if r > best_range { best_range = r; channel = k; }
    }
    if best_range == 0 { return vec![b]; }
    let mut colors = b.colors;
    colors.sort_by_key(|(c, _)| c[channel]);
    let half = b.total / 2;
    let mut acc = 0u64;
    let mut split_at = colors.len() / 2;
    for (i, (_, n)) in colors.iter().enumerate() {
        acc += *n as u64;
        if acc >= half { split_at = (i + 1).min(colors.len() - 1); break; }
    }
    if split_at == 0 { split_at = 1; }
    let right = colors.split_off(split_at);
    let lt: u64 = colors.iter().map(|(_, n)| *n as u64).sum();
    let rt: u64 = right.iter().map(|(_, n)| *n as u64).sum();
    vec![ColorBox { colors, total: lt }, ColorBox { colors: right, total: rt }]
}

pub fn quantize(rgba: &[u8], width: u32, height: u32, quality: u8, max_colors: usize) -> Quantized {
    let npix = (width as usize) * (height as usize);
    let mut hist: HashMap<[u8; 4], u32> = HashMap::new();
    for i in 0..npix {
        let c = [rgba[i*4], rgba[i*4+1], rgba[i*4+2], rgba[i*4+3]];
        *hist.entry(c).or_insert(0) += 1;
    }
    let target_max = max_colors.min(256);
    let mut boxes = vec![ColorBox { colors: hist.iter().map(|(c, n)| (*c, *n)).collect(), total: npix as u64 }];
    if quality == 0 {
        while boxes.len() < 2.min(target_max) {
            // Split the only/largest box once.
            let b = boxes.remove(0);
            boxes = split_box(b);
            if boxes.len() <= 1 { break; }
        }
    } else {
        let threshold = ((100.0 - quality as f64) / 100.0).powi(2) * 2000.0;
        loop {
            if boxes.len() >= target_max { break; }
            // Current mean squared error per pixel.
            let total_err: f64 = boxes.iter().map(|b| b.mean_and_error().1).sum();
            let mse = total_err / (npix.max(1) as f64);
            if mse <= threshold { break; }
            // Split the box with the largest error.
            let mut best_idx: Option<usize> = None;
            let mut best_err = 0.0f64;
            for (i, b) in boxes.iter().enumerate() {
                if b.colors.len() > 1 {
                    let e = b.mean_and_error().1;
                    if e > best_err { best_err = e; best_idx = Some(i); }
                }
            }
            let Some(idx) = best_idx else { break };
            let b = boxes.remove(idx);
            let parts = split_box(b);
            if parts.len() == 1 { boxes.push(parts.into_iter().next().unwrap()); break; }
            boxes.extend(parts);
        }
    }
    let mut palette: Vec<[u8; 4]> = boxes.iter().map(|b| {
        let (m, _) = b.mean_and_error();
        [m[0].clamp(0.0,255.0).round() as u8, m[1].clamp(0.0,255.0).round() as u8, m[2].clamp(0.0,255.0).round() as u8, m[3].clamp(0.0,255.0).round() as u8]
    }).collect();
    if palette.is_empty() { palette.push([0,0,0,255]); }
    // Exact-colour fast path.
    let exact = hist.len() <= palette.len() && boxes.iter().all(|b| b.colors.len() == 1);
    let nearest = |c: [f32; 4], palette: &[[u8;4]]| -> usize {
        let mut best = 0usize; let mut bestd = f32::INFINITY;
        for (i, p) in palette.iter().enumerate() {
            // Distance in premultiplied space plus alpha.
            let pa = p[3] as f32 / 255.0;
            let ca = (c[3].clamp(0.0,255.0)) / 255.0;
            let dr = c[0] * ca - p[0] as f32 * pa;
            let dg = c[1] * ca - p[1] as f32 * pa;
            let db = c[2] * ca - p[2] as f32 * pa;
            let da = c[3] - p[3] as f32;
            let d = dr*dr + dg*dg + db*db + da*da;
            if d < bestd { bestd = d; best = i; }
        }
        best
    };
    let mut indices = vec![0u8; npix];
    let mut pixels = vec![0u8; npix * 4];
    if exact {
        let mut map: HashMap<[u8;4], u8> = HashMap::new();
        for (i, p) in palette.iter().enumerate() { map.insert(*p, i as u8); }
        for i in 0..npix {
            let c = [rgba[i*4], rgba[i*4+1], rgba[i*4+2], rgba[i*4+3]];
            let idx = *map.get(&c).unwrap_or(&0);
            indices[i] = idx;
            pixels[i*4..i*4+4].copy_from_slice(&c);
        }
        return Quantized { palette, indices, pixels };
    }
    // Floyd–Steinberg dithering with row error buffers.
    let w = width as usize;
    let h = height as usize;
    let mut err_cur = vec![[0f32; 4]; w + 2];
    let mut err_next = vec![[0f32; 4]; w + 2];
    // Cache nearest lookup for exact original colours (helps flat areas).
    let mut cache: HashMap<[u8;4], usize> = HashMap::new();
    for y in 0..h {
        for x in 0..w {
            let i = y * w + x;
            let orig = [rgba[i*4], rgba[i*4+1], rgba[i*4+2], rgba[i*4+3]];
            let adjusted = [
                orig[0] as f32 + err_cur[x + 1][0],
                orig[1] as f32 + err_cur[x + 1][1],
                orig[2] as f32 + err_cur[x + 1][2],
                orig[3] as f32 + err_cur[x + 1][3],
            ];
            let clamped = [adjusted[0].clamp(0.0,255.0), adjusted[1].clamp(0.0,255.0), adjusted[2].clamp(0.0,255.0), adjusted[3].clamp(0.0,255.0)];
            let idx = if err_cur[x + 1] == [0.0; 4] {
                *cache.entry(orig).or_insert_with(|| nearest([orig[0] as f32, orig[1] as f32, orig[2] as f32, orig[3] as f32], &palette))
            } else {
                nearest(clamped, &palette)
            };
            indices[i] = idx as u8;
            let p = palette[idx];
            pixels[i*4..i*4+4].copy_from_slice(&p);
            let err = [clamped[0] - p[0] as f32, clamped[1] - p[1] as f32, clamped[2] - p[2] as f32, clamped[3] - p[3] as f32];
            // distribute: right 7/16, down-left 3/16, down 5/16, down-right 1/16
            for k in 0..4 {
                err_cur[x + 2][k] += err[k] * 7.0 / 16.0;
                err_next[x][k] += err[k] * 3.0 / 16.0;
                err_next[x + 1][k] += err[k] * 5.0 / 16.0;
                err_next[x + 2][k] += err[k] * 1.0 / 16.0;
            }
        }
        std::mem::swap(&mut err_cur, &mut err_next);
        for e in err_next.iter_mut() { *e = [0.0; 4]; }
    }
    // Re-order palette by usage (descending) for better PNG filtering, remapping indices.
    let mut counts = vec![0u64; palette.len()];
    for idx in &indices { counts[*idx as usize] += 1; }
    let mut order: Vec<usize> = (0..palette.len()).collect();
    order.sort_by(|a, b| counts[*b].cmp(&counts[*a]).then(a.cmp(b)));
    let mut remap = vec![0u8; palette.len()];
    let mut new_palette = Vec::with_capacity(palette.len());
    for (new_idx, old_idx) in order.iter().enumerate() {
        remap[*old_idx] = new_idx as u8;
        new_palette.push(palette[*old_idx]);
    }
    if new_palette != palette {
        for idx in indices.iter_mut() { *idx = remap[*idx as usize]; }
        palette = new_palette;
    }
    Quantized { palette, indices, pixels }
}
