use std::fmt;

#[derive(Clone, Debug)]
pub struct CError {
    pub message: String,
    pub codes: Vec<u32>,
}
impl CError {
    pub fn new(message: impl Into<String>, code: u32) -> Self { Self { message: message.into(), codes: vec![code] } }
    pub fn with_codes(message: impl Into<String>, codes: Vec<u32>) -> Self { Self { message: message.into(), codes } }
    pub fn plain(message: impl Into<String>) -> Self { Self { message: message.into(), codes: vec![] } }
    pub fn render(&self) -> String {
        let mut s = self.message.clone();
        for c in &self.codes { s.push_str(&format!(" [{}]", c)); }
        s
    }
}
impl fmt::Display for CError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result { write!(f, "{}", self.render()) }
}
impl std::error::Error for CError {}
pub type CResult<T> = Result<T, CError>;
