use std::os::raw::{c_int, c_ulong};

#[link(name = "z")]
extern "C" {
    fn compressBound(sourceLen: c_ulong) -> c_ulong;
    fn compress2(dest: *mut u8, destLen: *mut c_ulong, source: *const u8, sourceLen: c_ulong, level: c_int) -> c_int;
    fn uncompress(dest: *mut u8, destLen: *mut c_ulong, source: *const u8, sourceLen: c_ulong) -> c_int;
}

pub fn compress(data: &[u8], level: i32) -> Vec<u8> {
    unsafe {
        let bound = compressBound(data.len() as c_ulong) as usize;
        let mut out = vec![0u8; bound.max(1)];
        let mut out_len = out.len() as c_ulong;
        let rc = compress2(out.as_mut_ptr(), &mut out_len, data.as_ptr(), data.len() as c_ulong, level as c_int);
        if rc != 0 {
            // Stored (uncompressed) zlib fallback built manually is overkill;
            // level 0 should essentially never fail with a bound-sized buffer.
            let mut out_len2 = out.len() as c_ulong;
            let _ = compress2(out.as_mut_ptr(), &mut out_len2, data.as_ptr(), data.len() as c_ulong, 0);
            out.truncate(out_len2 as usize);
            return out;
        }
        out.truncate(out_len as usize);
        out
    }
}

/// Errors mirror zlib return codes: negative values are stream/data errors.
pub fn decompress_exact(data: &[u8], expected: usize) -> Result<Vec<u8>, i32> {
    let mut out = vec![0u8; expected];
    let mut out_len = expected as c_ulong;
    let rc = unsafe { uncompress(out.as_mut_ptr(), &mut out_len, data.as_ptr(), data.len() as c_ulong) };
    if rc != 0 { return Err(rc); }
    out.truncate(out_len as usize);
    Ok(out)
}

pub fn decompress_grow(data: &[u8], initial: usize) -> Result<Vec<u8>, i32> {
    let mut cap = initial.max(1024);
    loop {
        match decompress_exact(data, cap) {
            Ok(v) => return Ok(v),
            Err(-5) => { // Z_BUF_ERROR: output buffer too small
                cap = cap.saturating_mul(2);
                if cap > 1usize << 31 { return Err(-5); }
            }
            Err(e) => return Err(e),
        }
    }
}
