pub fn crc32(data: &[u8]) -> u32 {
    // Standard PNG CRC (ISO 3309 polynomial), table generated on the fly.
    let mut crc: u32 = 0xFFFFFFFF;
    for &b in data {
        let mut c = (crc ^ (b as u32)) & 0xFF;
        for _ in 0..8 {
            c = if c & 1 != 0 { 0xEDB88320 ^ (c >> 1) } else { c >> 1 };
        }
        crc = (crc >> 8) ^ c;
    }
    crc ^ 0xFFFFFFFF
}

fn chunk_bytes(typ: &[u8; 4], data: &[u8], out: &mut Vec<u8>) {
    out.extend_from_slice(&(data.len() as u32).to_be_bytes());
    out.extend_from_slice(typ);
    out.extend_from_slice(data);
    let mut crc_data = Vec::with_capacity(4 + data.len());
    crc_data.extend_from_slice(typ);
    crc_data.extend_from_slice(data);
    out.extend_from_slice(&crc32(&crc_data).to_be_bytes());
}

#[derive(Clone, Debug)]
pub struct PngChunk {
    pub typ: [u8; 4],
    pub data: Vec<u8>,
    pub after_idat: bool,
}

#[derive(Clone, Debug)]
pub enum Trns {
    Gray(u16),
    Rgb(u16, u16, u16),
    Palette(Vec<u8>),
}

#[derive(Clone, Debug)]
pub enum PngErr {
    TooSmall,
    BadSignature,
    FirstNotIhdr([u8; 4]),
    IhdrLength(u32),
    ZeroDimensions,
    BadColorType,
    BadBitDepthCombo,
    Crc { typ: [u8; 4], computed: u32, stored: u32 },
    Truncated,
    InflateError,
    InvalidIdatSize,
    InvalidFilter(u8),
    InvalidChunk(String),
}

impl PngErr {
    pub fn to_cerror(&self, flavor: Flavor) -> CError {
        match flavor {
            Flavor::Zune => {
                let msg = match self {
                    Self::TooSmall => "PNG file is smaller than a PNG header".to_string(),
                    Self::BadSignature => "incorrect PNG signature, it's no PNG or corrupted".to_string(),
                    Self::FirstNotIhdr(_) => "first chunk is not the header chunk".to_string(),
                    Self::IhdrLength(_) => "header chunk must have a size of 13 bytes".to_string(),
                    Self::ZeroDimensions => "zero width or height is invalid".to_string(),
                    Self::BadColorType | Self::BadBitDepthCombo => "illegal PNG color type or bpp".to_string(),
                    Self::Crc { .. } => "invalid CRC encountered (checking CRC can be disabled)".to_string(),
                    Self::Truncated => "jumped past memory while inflating".to_string(),
                    Self::InflateError => "end of in buffer memory reached while inflating".to_string(),
                    Self::InvalidIdatSize => "invalid decompressed idat size".to_string(),
                    Self::InvalidFilter(_) => "invalid png filter specified".to_string(),
                    Self::InvalidChunk(m) => m.clone(),
                };
                CError::new(msg, 20204)
            }
            Flavor::Oxipng => {
                let msg = match self {
                    Self::BadSignature | Self::TooSmall => "Invalid header detected; Not a PNG file".to_string(),
                    Self::Crc { typ, .. } => format!("CRC Mismatch in {} chunk; May be recoverable by using --fix", String::from_utf8_lossy(typ)),
                    Self::Truncated => "Missing data in the file; the file is truncated".to_string(),
                    Self::FirstNotIhdr(t) => format!("CRC Mismatch in {} chunk; May be recoverable by using --fix", String::from_utf8_lossy(t)),
                    Self::ZeroDimensions => "Invalid image dimensions".to_string(),
                    Self::InvalidIdatSize | Self::InflateError => "Missing data in the file; the file is truncated".to_string(),
                    other => format!("{:?}", other),
                };
                CError::new(msg, 20210)
            }
            Flavor::Image(code) => {
                let msg = match self {
                    Self::BadSignature | Self::TooSmall => "The image format could not be determined".to_string(),
                    Self::FirstNotIhdr(t) => format!("Format error decoding Png: {} chunk appeared before IHDR chunk", chunk_type_debug(t)),
                    Self::Crc { typ, computed, stored } => format!(
                        "Format error decoding Png: CRC error: expected {:#010x} have {:#010x} while decoding {} chunk.",
                        computed, stored, chunk_type_debug(typ)
                    ),
                    Self::Truncated => "unexpected end of file".to_string(),
                    Self::InflateError => "Format error decoding Png: Corrupt deflate stream. InvalidUncompressedBlockLength".to_string(),
                    Self::InvalidIdatSize => "unexpected end of file".to_string(),
                    Self::ZeroDimensions => "Format error decoding Png: invalid image dimensions".to_string(),
                    other => format!("Format error decoding Png: {:?}", other),
                };
                CError::new(msg, code)
            }
        }
    }
}

fn chunk_type_debug(t: &[u8; 4]) -> String {
    let critical = t[0].is_ascii_uppercase();
    let private = t[1].is_ascii_uppercase();
    let reserved = t[2].is_ascii_uppercase();
    let safecopy = t[3].is_ascii_lowercase();
    format!(
        "ChunkType {{ type: {}, critical: {}, private: {}, reserved: {}, safecopy: {} }}",
        String::from_utf8_lossy(t), critical, private, reserved, safecopy
    )
}

#[derive(Clone, Copy)]
pub enum Flavor { Zune, Oxipng, Image(u32) }

pub struct PngImage {
    pub width: u32,
    pub height: u32,
    pub bit_depth: u8,
    pub color_type: u8,
    pub interlace: u8,
    pub palette: Vec<[u8; 3]>,
    pub trns: Option<Trns>,
    pub chunks: Vec<PngChunk>,
    // Expanded RGBA samples, each sample in 0..=sample_max.
    pub pixels: Vec<[u16; 4]>,
    pub sample_max: u32,
    pub raster_kind: ColorKind,
    pub metadata: Metadata,
    pub original: Vec<u8>,
    pub idat_raw: Vec<u8>,
}

fn channels_of(color_type: u8) -> usize {
    match color_type { 0 => 1, 2 => 3, 3 => 1, 4 => 2, 6 => 4, _ => 0 }
}

const ADAM7: [(u32, u32, u32, u32); 7] = [(0,0,8,8),(4,0,8,8),(0,4,4,8),(2,0,4,4),(0,2,2,4),(1,0,2,2),(0,1,1,2)];

fn pass_dims(w: u32, h: u32, interlace: u8) -> Vec<(u32, u32, u32, u32, u32, u32)> {
    // (x_start, y_start, x_step, y_step, pass_w, pass_h)
    if interlace == 0 { return vec![(0, 0, 1, 1, w, h)]; }
    ADAM7.iter().map(|(xs, ys, xstep, ystep)| {
        let pw = if w > *xs { (w - xs + xstep - 1) / xstep } else { 0 };
        let ph = if h > *ys { (h - ys + ystep - 1) / ystep } else { 0 };
        (*xs, *ys, *xstep, *ystep, pw, ph)
    }).collect()
}

fn row_bytes(width: u32, channels: usize, bit_depth: u8) -> usize {
    ((width as usize * channels * bit_depth as usize) + 7) / 8
}

pub fn parse_png(data: &[u8]) -> Result<PngImage, PngErr> {
    if data.len() < 33 { return Err(PngErr::TooSmall); }
    if &data[0..8] != b"\x89PNG\r\n\x1a\n" { return Err(PngErr::BadSignature); }
    // First chunk header.
    if data.len() < 8 + 8 { return Err(PngErr::TooSmall); }
    let first_len = u32::from_be_bytes([data[8], data[9], data[10], data[11]]);
    let first_type = [data[12], data[13], data[14], data[15]];
    if &first_type != b"IHDR" { return Err(PngErr::FirstNotIhdr(first_type)); }
    if first_len != 13 { return Err(PngErr::IhdrLength(first_len)); }
    let ihdr = &data[16..29];
    let width = u32::from_be_bytes([ihdr[0], ihdr[1], ihdr[2], ihdr[3]]);
    let height = u32::from_be_bytes([ihdr[4], ihdr[5], ihdr[6], ihdr[7]]);
    if width == 0 || height == 0 { return Err(PngErr::ZeroDimensions); }
    let bit_depth = ihdr[8];
    let color_type = ihdr[9];
    if !matches!(color_type, 0 | 2 | 3 | 4 | 6) { return Err(PngErr::BadColorType); }
    let interlace = ihdr[12];

    let mut palette: Vec<[u8; 3]> = Vec::new();
    let mut trns: Option<Trns> = None;
    let mut chunks: Vec<PngChunk> = Vec::new();
    let mut idat: Vec<u8> = Vec::new();
    let mut seen_idat = false;
    let mut seen_iend = false;
    let mut metadata = Metadata::default();

    let mut pos = 8usize;
    while pos < data.len() {
        if pos + 8 > data.len() { return Err(PngErr::Truncated); }
        let len = u32::from_be_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]) as usize;
        let typ = [data[pos+4], data[pos+5], data[pos+6], data[pos+7]];
        if pos + 8 + len + 4 > data.len() { return Err(PngErr::Truncated); }
        let cdata = &data[pos + 8..pos + 8 + len];
        let stored_crc = u32::from_be_bytes([data[pos+8+len], data[pos+9+len], data[pos+10+len], data[pos+11+len]]);
        let computed_crc = crc32(&data[pos + 4..pos + 8 + len]);
        if computed_crc != stored_crc {
            return Err(PngErr::Crc { typ, computed: computed_crc, stored: stored_crc });
        }
        match &typ {
            b"PLTE" => {
                palette = cdata.chunks_exact(3).map(|c| [c[0], c[1], c[2]]).collect();
            }
            b"tRNS" => {
                trns = Some(match color_type {
                    0 if cdata.len() >= 2 => Trns::Gray(u16::from_be_bytes([cdata[0], cdata[1]])),
                    2 if cdata.len() >= 6 => Trns::Rgb(
                        u16::from_be_bytes([cdata[0], cdata[1]]),
                        u16::from_be_bytes([cdata[2], cdata[3]]),
                        u16::from_be_bytes([cdata[4], cdata[5]])),
                    3 => Trns::Palette(cdata.to_vec()),
                    _ => Trns::Palette(cdata.to_vec()),
                });
            }
            b"IDAT" => { seen_idat = true; idat.extend_from_slice(cdata); }
            b"IEND" => { seen_iend = true; pos += 12 + len; break; }
            b"IHDR" => {}
            b"iCCP" => {
                chunks.push(PngChunk { typ, data: cdata.to_vec(), after_idat: seen_idat });
                if metadata.icc.is_none() {
                    if let Some(profile) = parse_iccp(cdata) { metadata.icc = Some(profile); }
                }
            }
            b"eXIf" => {
                chunks.push(PngChunk { typ, data: cdata.to_vec(), after_idat: seen_idat });
                if metadata.exif.is_none() { metadata.exif = Some(cdata.to_vec()); }
            }
            _ => {
                chunks.push(PngChunk { typ, data: cdata.to_vec(), after_idat: seen_idat });
            }
        }
        pos += 12 + len;
    }
    let _ = seen_iend;
    if let Some(exif) = &metadata.exif { metadata.orientation = exif_orientation(exif); }

    // Bit depth / colour type combination validation (after CRC checks).
    let valid_depth = match color_type {
        0 => matches!(bit_depth, 1 | 2 | 4 | 8 | 16),
        3 => matches!(bit_depth, 1 | 2 | 4 | 8),
        2 | 4 | 6 => matches!(bit_depth, 8 | 16),
        _ => false,
    };
    if !valid_depth { return Err(PngErr::BadBitDepthCombo); }
    if interlace > 1 { return Err(PngErr::InvalidChunk("unsupported interlace method".into())); }

    let channels = channels_of(color_type);
    let passes = pass_dims(width, height, interlace);
    let expected: usize = passes.iter().map(|(_, _, _, _, pw, ph)| {
        if *pw == 0 || *ph == 0 { 0 } else { (row_bytes(*pw, channels, bit_depth) + 1) * (*ph as usize) }
    }).sum();
    if idat.is_empty() { return Err(PngErr::InvalidIdatSize); }
    let raw = match z::decompress_exact(&idat, expected.max(1)) {
        Ok(v) => v,
        Err(_) => {
            // Try to distinguish a merely short/long stream from corruption:
            match z::decompress_grow(&idat, expected.max(1024)) {
                Ok(v) => v,
                Err(_) => return Err(PngErr::InflateError),
            }
        }
    };
    if raw.len() != expected { return Err(PngErr::InvalidIdatSize); }

    // Unfilter and unpack samples.
    let npix = (width as usize) * (height as usize);
    let mut raw_samples: Vec<Vec<u16>> = vec![vec![0u16; channels]; npix];
    let bpp = ((channels * bit_depth as usize) + 7) / 8;
    let bpp = bpp.max(1);
    let mut offset = 0usize;
    for (xs, ys, xstep, ystep, pw, ph) in &passes {
        if *pw == 0 || *ph == 0 { continue; }
        let rb = row_bytes(*pw, channels, bit_depth);
        let mut prev = vec![0u8; rb];
        for row in 0..*ph {
            let f = raw[offset];
            offset += 1;
            if f > 4 { return Err(PngErr::InvalidFilter(f)); }
            let mut cur = raw[offset..offset + rb].to_vec();
            offset += rb;
            unfilter(f, &mut cur, &prev, bpp);
            // Unpack this row's samples.
            let samples = unpack_row(&cur, *pw as usize, channels, bit_depth);
            for col in 0..*pw as usize {
                let x = xs + (col as u32) * xstep;
                let y = ys + row * ystep;
                let idx = (y as usize) * (width as usize) + x as usize;
                raw_samples[idx] = samples[col * channels..(col + 1) * channels].to_vec();
            }
            prev = cur;
        }
    }

    let sample_max: u32 = if bit_depth == 16 { 65535 } else { 255 };
    let mut pixels: Vec<[u16; 4]> = Vec::with_capacity(npix);
    for s in &raw_samples {
        let px: [u16; 4] = match color_type {
            0 => {
                let (v, full) = scale_sample(s[0], bit_depth);
                let mut a = full;
                if let Some(Trns::Gray(g)) = &trns { if s[0] == *g { a = 0; } }
                [v, v, v, a]
            }
            2 => {
                let (r, full) = scale_sample(s[0], bit_depth);
                let (g, _) = scale_sample(s[1], bit_depth);
                let (b, _) = scale_sample(s[2], bit_depth);
                let mut a = full;
                if let Some(Trns::Rgb(tr, tg, tb)) = &trns {
                    if s[0] == *tr && s[1] == *tg && s[2] == *tb { a = 0; }
                }
                [r, g, b, a]
            }
            3 => {
                let idx = s[0] as usize;
                let c = palette.get(idx).copied().unwrap_or([0, 0, 0]);
                let a = match &trns { Some(Trns::Palette(t)) => t.get(idx).copied().unwrap_or(255) as u16, _ => 255 };
                [c[0] as u16, c[1] as u16, c[2] as u16, a]
            }
            4 => {
                let (v, _) = scale_sample(s[0], bit_depth);
                let (a, _) = scale_sample(s[1], bit_depth);
                [v, v, v, a]
            }
            _ => {
                // 6
                let (r, _) = scale_sample(s[0], bit_depth);
                let (g, _) = scale_sample(s[1], bit_depth);
                let (b, _) = scale_sample(s[2], bit_depth);
                let (a, _) = scale_sample(s[3], bit_depth);
                [r, g, b, a]
            }
        };
        pixels.push(px);
    }

    let raster_kind = match (color_type, bit_depth) {
        (0, 16) => if matches!(trns, Some(Trns::Gray(_))) { ColorKind::La16 } else { ColorKind::L16 },
        (0, _) => if matches!(trns, Some(Trns::Gray(_))) { ColorKind::La8 } else { ColorKind::L8 },
        (2, 16) => if matches!(trns, Some(Trns::Rgb(..))) { ColorKind::Rgba16 } else { ColorKind::Rgb16 },
        (2, _) => if matches!(trns, Some(Trns::Rgb(..))) { ColorKind::Rgba8 } else { ColorKind::Rgb8 },
        (3, _) => if matches!(trns, Some(Trns::Palette(_))) { ColorKind::Rgba8 } else { ColorKind::Rgb8 },
        (4, 16) => ColorKind::La16,
        (4, _) => ColorKind::La8,
        (6, 16) => ColorKind::Rgba16,
        _ => ColorKind::Rgba8,
    };

    Ok(PngImage {
        width, height, bit_depth, color_type, interlace,
        palette, trns, chunks, pixels, sample_max, raster_kind, metadata,
        original: data.to_vec(), idat_raw: idat,
    })
}

fn scale_sample(v: u16, bit_depth: u8) -> (u16, u16) {
    match bit_depth {
        16 => (v, 65535),
        8 => (v, 255),
        d => {
            let max = ((1u32 << d) - 1) as u16;
            let scaled = if max == 0 { 0 } else { ((v as u32 * 255) / max as u32) as u16 };
            (scaled, 255)
        }
    }
}

fn unpack_row(row: &[u8], width: usize, channels: usize, bit_depth: u8) -> Vec<u16> {
    let total = width * channels;
    let mut out = Vec::with_capacity(total);
    match bit_depth {
        16 => {
            for i in 0..total { out.push(u16::from_be_bytes([row[i * 2], row[i * 2 + 1]])); }
        }
        8 => {
            for i in 0..total { out.push(row[i] as u16); }
        }
        d => {
            let per_byte = 8 / d as usize;
            let mask = ((1u16 << d) - 1) as u8;
            for &byte in row {
                for s in (0..per_byte).rev() {
                    if out.len() >= total { break; }
                    out.push(((byte >> (s * d as usize)) & mask) as u16);
                }
                if out.len() >= total { break; }
            }
            out.resize(total, 0);
        }
    }
    out
}

fn unfilter(f: u8, cur: &mut [u8], prev: &[u8], bpp: usize) {
    match f {
        0 => {}
        1 => for i in bpp..cur.len() { cur[i] = cur[i].wrapping_add(cur[i - bpp]); },
        2 => for i in 0..cur.len() { cur[i] = cur[i].wrapping_add(prev[i]); },
        3 => for i in 0..cur.len() {
            let a = if i >= bpp { cur[i - bpp] as u16 } else { 0 };
            cur[i] = cur[i].wrapping_add(((a + prev[i] as u16) / 2) as u8);
        },
        4 => for i in 0..cur.len() {
            let a = if i >= bpp { cur[i - bpp] as i32 } else { 0 };
            let b = prev[i] as i32;
            let c = if i >= bpp { prev[i - bpp] as i32 } else { 0 };
            let p = a + b - c;
            let pa = (p - a).abs(); let pb = (p - b).abs(); let pc = (p - c).abs();
            let pr = if pa <= pb && pa <= pc { a } else if pb <= pc { b } else { c };
            cur[i] = cur[i].wrapping_add(pr as u8);
        },
        _ => {}
    }
}

fn parse_iccp(data: &[u8]) -> Option<Vec<u8>> {
    let nul = data.iter().position(|b| *b == 0)?;
    if data.get(nul + 1).copied()? != 0 { return None; }
    let comp = &data[nul + 2..];
    z::decompress_grow(comp, comp.len() * 3 + 1024).ok()
}

impl PngImage {
    pub fn to_raster(&self) -> Raster {
        let kind = self.raster_kind;
        let ch = kind.channels();
        let npix = self.pixels.len();
        if kind.is_16() {
            let mut data = Vec::with_capacity(npix * ch * 2);
            for p in &self.pixels {
                let vals: [u16; 4] = if self.sample_max == 65535 { *p } else { [p[0] * 257, p[1] * 257, p[2] * 257, p[3] * 257] };
                match ch {
                    1 => data.extend_from_slice(&vals[0].to_le_bytes()),
                    2 => { data.extend_from_slice(&vals[0].to_le_bytes()); data.extend_from_slice(&vals[3].to_le_bytes()); }
                    3 => for k in 0..3 { data.extend_from_slice(&vals[k].to_le_bytes()); },
                    _ => for k in 0..4 { data.extend_from_slice(&vals[k].to_le_bytes()); },
                }
            }
            Raster::new(self.width, self.height, kind, data)
        } else {
            let mut data = Vec::with_capacity(npix * ch);
            for p in &self.pixels {
                let conv = |v: u16| -> u8 { if self.sample_max == 65535 { (v >> 8) as u8 } else { v as u8 } };
                match ch {
                    1 => data.push(conv(p[0])),
                    2 => { data.push(conv(p[0])); data.push(conv(p[3])); }
                    3 => { data.push(conv(p[0])); data.push(conv(p[1])); data.push(conv(p[2])); }
                    _ => { data.push(conv(p[0])); data.push(conv(p[1])); data.push(conv(p[2])); data.push(conv(p[3])); }
                }
            }
            Raster::new(self.width, self.height, kind, data)
        }
    }
}

// ---------- generic PNG encoding ----------
pub struct PngPixels {
    pub width: u32,
    pub height: u32,
    pub color_type: u8,
    pub bit_depth: u8,
    // Per-pixel samples in row-major order (values already in bit-depth range).
    pub samples: Vec<u16>,
    pub palette: Vec<[u8; 3]>,
    pub trns: Option<Vec<u8>>,
}
impl PngPixels {
    fn channels(&self) -> usize { channels_of(self.color_type) }
}

#[derive(Clone, Copy, PartialEq)]
enum FilterStrategy { Adaptive, Fixed(u8) }

fn filter_row(row: &[u8], prev: &[u8], bpp: usize, strategy: FilterStrategy) -> (u8, Vec<u8>) {
    let apply = |f: u8| -> Vec<u8> {
        let mut out = Vec::with_capacity(row.len());
        for i in 0..row.len() {
            let a = if i >= bpp { row[i - bpp] } else { 0 };
            let b = prev[i];
            let c = if i >= bpp { prev[i - bpp] } else { 0 };
            let v = match f {
                0 => row[i],
                1 => row[i].wrapping_sub(a),
                2 => row[i].wrapping_sub(b),
                3 => row[i].wrapping_sub(((a as u16 + b as u16) / 2) as u8),
                _ => {
                    let (a32, b32, c32) = (a as i32, b as i32, c as i32);
                    let p = a32 + b32 - c32;
                    let pa = (p - a32).abs(); let pb = (p - b32).abs(); let pc = (p - c32).abs();
                    let pr = if pa <= pb && pa <= pc { a } else if pb <= pc { b } else { c };
                    row[i].wrapping_sub(pr)
                }
            };
            out.push(v);
        }
        out
    };
    match strategy {
        FilterStrategy::Fixed(f) => (f, apply(f)),
        FilterStrategy::Adaptive => {
            let mut best: Option<(u8, Vec<u8>, i64)> = None;
            for f in 0..5u8 {
                let data = apply(f);
                let score: i64 = data.iter().map(|b| (*b as i8).unsigned_abs() as i64).sum();
                if best.as_ref().map(|(_, _, s)| score < *s).unwrap_or(true) {
                    best = Some((f, data, score));
                }
            }
            let (f, d, _) = best.unwrap();
            (f, d)
        }
    }
}

fn pack_row(samples: &[u16], bit_depth: u8) -> Vec<u8> {
    match bit_depth {
        16 => {
            let mut out = Vec::with_capacity(samples.len() * 2);
            for s in samples { out.extend_from_slice(&s.to_be_bytes()); }
            out
        }
        8 => samples.iter().map(|s| *s as u8).collect(),
        d => {
            let per_byte = 8 / d as usize;
            let mut out = Vec::with_capacity((samples.len() + per_byte - 1) / per_byte);
            for chunk in samples.chunks(per_byte) {
                let mut byte = 0u8;
                for (i, s) in chunk.iter().enumerate() {
                    let shift = (per_byte - 1 - i) * d as usize;
                    byte |= ((*s as u8) & ((1u8 << d) - 1)) << shift;
                }
                out.push(byte);
            }
            out
        }
    }
}

fn encode_idat(pix: &PngPixels, interlace: bool, strategy: FilterStrategy, level: i32) -> Vec<u8> {
    let ch = pix.channels();
    let bpp = ((ch * pix.bit_depth as usize) + 7) / 8;
    let bpp = bpp.max(1);
    let passes = pass_dims(pix.width, pix.height, if interlace { 1 } else { 0 });
    let mut raw = Vec::new();
    for (xs, ys, xstep, ystep, pw, ph) in &passes {
        if *pw == 0 || *ph == 0 { continue; }
        let mut prev = vec![0u8; row_bytes(*pw, ch, pix.bit_depth)];
        for row in 0..*ph {
            let y = ys + row * ystep;
            let mut samples = Vec::with_capacity((*pw as usize) * ch);
            for col in 0..*pw {
                let x = xs + col * xstep;
                let base = ((y as usize) * (pix.width as usize) + x as usize) * ch;
                samples.extend_from_slice(&pix.samples[base..base + ch]);
            }
            let packed = pack_row(&samples, pix.bit_depth);
            let (f, filtered) = filter_row(&packed, &prev, bpp, strategy);
            raw.push(f);
            raw.extend_from_slice(&filtered);
            prev = packed;
        }
    }
    z::compress(&raw, level)
}

fn ihdr_data(w: u32, h: u32, bit_depth: u8, color_type: u8, interlace: bool) -> Vec<u8> {
    let mut d = Vec::with_capacity(13);
    d.extend_from_slice(&w.to_be_bytes());
    d.extend_from_slice(&h.to_be_bytes());
    d.push(bit_depth); d.push(color_type); d.push(0); d.push(0); d.push(if interlace { 1 } else { 0 });
    d
}

pub fn encode_png_generic(raster: &Raster, metadata: &Metadata, include_metadata: bool) -> Vec<u8> {
    let pix = raster_to_pngpixels(raster);
    let mut out = Vec::new();
    out.extend_from_slice(b"\x89PNG\r\n\x1a\n");
    chunk_bytes(b"IHDR", &ihdr_data(pix.width, pix.height, pix.bit_depth, pix.color_type, false), &mut out);
    if include_metadata {
        if let Some(icc) = &metadata.icc {
            let mut d = b"icc\x00\x00".to_vec();
            d.extend_from_slice(&z::compress(icc, 6));
            chunk_bytes(b"iCCP", &d, &mut out);
        }
    }
    if !pix.palette.is_empty() {
        let plte: Vec<u8> = pix.palette.iter().flat_map(|c| *c).collect();
        chunk_bytes(b"PLTE", &plte, &mut out);
    }
    if let Some(trns) = &pix.trns { chunk_bytes(b"tRNS", trns, &mut out); }
    let idat = encode_idat(&pix, false, FilterStrategy::Adaptive, 6);
    chunk_bytes(b"IDAT", &idat, &mut out);
    if include_metadata {
        if let Some(exif) = &metadata.exif { chunk_bytes(b"eXIf", exif, &mut out); }
    }
    chunk_bytes(b"IEND", &[], &mut out);
    out
}

pub fn raster_to_pngpixels(raster: &Raster) -> PngPixels {
    let (color_type, bit_depth) = match raster.kind {
        ColorKind::L8 => (0, 8), ColorKind::La8 => (4, 8), ColorKind::Rgb8 => (2, 8), ColorKind::Rgba8 => (6, 8),
        ColorKind::L16 => (0, 16), ColorKind::La16 => (4, 16), ColorKind::Rgb16 => (2, 16), ColorKind::Rgba16 => (6, 16),
    };
    let ch = raster.kind.channels();
    let mut samples = Vec::with_capacity(raster.pixel_count() * ch);
    for i in 0..raster.pixel_count() {
        for c in 0..ch { samples.push(raster.sample(i, c) as u16); }
    }
    PngPixels { width: raster.width, height: raster.height, color_type, bit_depth, samples, palette: vec![], trns: None }
}

// ---------- lossless optimisation ----------
fn candidate_from_rgba16(png: &PngImage, depth8: bool) -> Vec<PngPixels> {
    let w = png.width; let h = png.height;
    let npix = png.pixels.len();
    let mut out: Vec<PngPixels> = Vec::new();
    let has_alpha = png.pixels.iter().any(|p| (p[3] as u32) < png.sample_max);
    let is_gray = png.pixels.iter().all(|p| p[0] == p[1] && p[1] == p[2]);
    if depth8 {
        // Base colour-type candidate.
        let to8 = |v: u16| -> u16 { if png.sample_max == 65535 { v / 257 } else { v } };
        let (ct, samples): (u8, Vec<u16>) = if is_gray && has_alpha {
            (4, png.pixels.iter().flat_map(|p| [to8(p[0]), to8(p[3])]).collect())
        } else if is_gray {
            (0, png.pixels.iter().map(|p| to8(p[0])).collect())
        } else if has_alpha {
            (6, png.pixels.iter().flat_map(|p| [to8(p[0]), to8(p[1]), to8(p[2]), to8(p[3])]).collect())
        } else {
            (2, png.pixels.iter().flat_map(|p| [to8(p[0]), to8(p[1]), to8(p[2])]).collect())
        };
        let mut bit_depth = 8u8;
        let mut samples = samples;
        if ct == 0 {
            // Try reducing the bit depth of a grayscale image.
            let vals: Vec<u16> = samples.clone();
            if vals.iter().all(|v| *v == 0 || *v == 255) {
                bit_depth = 1; samples = vals.iter().map(|v| if *v == 0 { 0 } else { 1 }).collect();
            } else if vals.iter().all(|v| *v % 85 == 0) {
                bit_depth = 2; samples = vals.iter().map(|v| *v / 85).collect();
            } else if vals.iter().all(|v| *v % 17 == 0) {
                bit_depth = 4; samples = vals.iter().map(|v| *v / 17).collect();
            }
        }
        out.push(PngPixels { width: w, height: h, color_type: ct, bit_depth, samples, palette: vec![], trns: None });

        // tRNS candidate for binary alpha over a colour/gray image.
        if has_alpha {
            let transparent_colours: Vec<[u16;4]> = {
                let mut set: Vec<[u16;4]> = Vec::new();
                for p in &png.pixels {
                    if p[3] == 0 && !set.contains(p) { set.push(*p); }
                    if set.len() > 1 { break; }
                }
                set
            };
            let binary = png.pixels.iter().all(|p| p[3] == 0 || (p[3] as u32) == png.sample_max);
            if binary && transparent_colours.len() == 1 {
                let tc = transparent_colours[0];
                let conflict = png.pixels.iter().any(|p| p[3] != 0 && p[0] == tc[0] && p[1] == tc[1] && p[2] == tc[2]);
                if !conflict {
                    if is_gray {
                        let s: Vec<u16> = png.pixels.iter().map(|p| to8(p[0])).collect();
                        let trns = to8(tc[0]).to_be_bytes().to_vec();
                        out.push(PngPixels { width: w, height: h, color_type: 0, bit_depth: 8, samples: s, palette: vec![], trns: Some(trns) });
                    } else {
                        let s: Vec<u16> = png.pixels.iter().flat_map(|p| [to8(p[0]), to8(p[1]), to8(p[2])]).collect();
                        let mut trns = Vec::new();
                        for k in 0..3 { trns.extend_from_slice(&to8(tc[k]).to_be_bytes()); }
                        out.push(PngPixels { width: w, height: h, color_type: 2, bit_depth: 8, samples: s, palette: vec![], trns: Some(trns) });
                    }
                }
            }
        }

        // Palette candidate.
        let mut uniq: HashMap<[u8;4], u32> = HashMap::new();
        let mut first_seen: HashMap<[u8;4], usize> = HashMap::new();
        for (i, p) in png.pixels.iter().enumerate() {
            let c = [to8(p[0]) as u8, to8(p[1]) as u8, to8(p[2]) as u8, to8(p[3]) as u8];
            *uniq.entry(c).or_insert(0) += 1;
            first_seen.entry(c).or_insert(i);
            if uniq.len() > 256 { break; }
        }
        if uniq.len() <= 256 {
            let mut colours: Vec<[u8;4]> = uniq.keys().copied().collect();
            colours.sort_by(|a, b| uniq[b].cmp(&uniq[a]).then(first_seen[a].cmp(&first_seen[b])));
            let index: HashMap<[u8;4], u16> = colours.iter().enumerate().map(|(i, c)| (*c, i as u16)).collect();
            let samples: Vec<u16> = png.pixels.iter().map(|p| {
                let c = [to8(p[0]) as u8, to8(p[1]) as u8, to8(p[2]) as u8, to8(p[3]) as u8];
                index[&c]
            }).collect();
            let palette: Vec<[u8;3]> = colours.iter().map(|c| [c[0], c[1], c[2]]).collect();
            let bd = if colours.len() <= 2 { 1 } else if colours.len() <= 4 { 2 } else if colours.len() <= 16 { 4 } else { 8 };
            let trns = if colours.iter().any(|c| c[3] < 255) {
                let last = colours.iter().rposition(|c| c[3] < 255).unwrap();
                Some(colours[..=last].iter().map(|c| c[3]).collect::<Vec<u8>>())
            } else { None };
            out.push(PngPixels { width: w, height: h, color_type: 3, bit_depth: bd, samples, palette, trns });
        }
    } else {
        // 16-bit candidates.
        let (ct, samples): (u8, Vec<u16>) = if is_gray && has_alpha {
            (4, png.pixels.iter().flat_map(|p| [p[0], p[3]]).collect())
        } else if is_gray {
            (0, png.pixels.iter().map(|p| p[0]).collect())
        } else if has_alpha {
            (6, png.pixels.iter().flat_map(|p| *p).collect())
        } else {
            (2, png.pixels.iter().flat_map(|p| [p[0], p[1], p[2]]).collect())
        };
        out.push(PngPixels { width: w, height: h, color_type: ct, bit_depth: 16, samples, palette: vec![], trns: None });
    }
    let _ = npix;
    out
}

fn transform_iccp(data: &[u8], level: i32) -> Vec<u8> {
    if let Some(profile) = parse_iccp(data) {
        let mut d = b"icc\x00\x00".to_vec();
        d.extend_from_slice(&z::compress(&profile, level));
        d
    } else {
        data.to_vec()
    }
}

fn encode_with_chunks(pix: &PngPixels, src: &PngImage, interlace: bool, strategy: FilterStrategy, zlib_level: i32, zopfli: bool, icc_level: i32) -> Vec<u8> {
    let mut out = Vec::new();
    out.extend_from_slice(b"\x89PNG\r\n\x1a\n");
    chunk_bytes(b"IHDR", &ihdr_data(pix.width, pix.height, pix.bit_depth, pix.color_type, interlace), &mut out);
    let keep_chunk = |typ: &[u8;4]| -> bool {
        if !zopfli { return true; }
        // In zopfli mode most ancillary chunks are stripped.
        typ == b"sRGB" || typ == b"pHYs" || typ == b"iCCP"
    };
    let has_srgb = src.chunks.iter().any(|c| &c.typ == b"sRGB");
    // Chunks that oxipng emits just before IDAT.
    let late_types: [&[u8;4]; 2] = [b"bKGD", b"hIST"];
    let mut late: Vec<&PngChunk> = Vec::new();
    for c in src.chunks.iter().filter(|c| !c.after_idat) {
        if late_types.contains(&&c.typ) { late.push(c); continue; }
        if !keep_chunk(&c.typ) { continue; }
        if zopfli && &c.typ == b"iCCP" && has_srgb { continue; }
        if &c.typ == b"iCCP" {
            chunk_bytes(&c.typ, &transform_iccp(&c.data, icc_level), &mut out);
        } else {
            chunk_bytes(&c.typ, &c.data, &mut out);
        }
    }
    if !pix.palette.is_empty() {
        let plte: Vec<u8> = pix.palette.iter().flat_map(|c| *c).collect();
        chunk_bytes(b"PLTE", &plte, &mut out);
    }
    if let Some(trns) = &pix.trns { chunk_bytes(b"tRNS", trns, &mut out); }
    for c in &late {
        if keep_chunk(&c.typ) || !zopfli { chunk_bytes(&c.typ, &c.data, &mut out); }
    }
    let idat = encode_idat(pix, interlace, strategy, zlib_level);
    chunk_bytes(b"IDAT", &idat, &mut out);
    for c in src.chunks.iter().filter(|c| c.after_idat) {
        if !keep_chunk(&c.typ) { continue; }
        if zopfli && &c.typ == b"iCCP" && has_srgb { continue; }
        if &c.typ == b"iCCP" {
            chunk_bytes(&c.typ, &transform_iccp(&c.data, icc_level), &mut out);
        } else {
            chunk_bytes(&c.typ, &c.data, &mut out);
        }
    }
    chunk_bytes(b"IEND", &[], &mut out);
    out
}

pub fn optimize_png(png: &PngImage, opt_level: u8, zopfli: bool) -> Vec<u8> {
    let reducible16 = png.sample_max == 65535 && png.pixels.iter().all(|p| p.iter().all(|v| v % 257 == 0));
    let depth8 = png.sample_max == 255 || reducible16;
    let candidates = candidate_from_rgba16(png, depth8);
    let (zlib_level, strategies): (i32, Vec<FilterStrategy>) = if zopfli {
        (9, vec![FilterStrategy::Adaptive, FilterStrategy::Fixed(4)])
    } else {
        match opt_level {
            0 => (1, vec![FilterStrategy::Adaptive]),
            1 => (6, vec![FilterStrategy::Adaptive]),
            2 => (6, vec![FilterStrategy::Adaptive]),
            3 => (6, vec![FilterStrategy::Adaptive]),
            4 => (9, vec![FilterStrategy::Adaptive, FilterStrategy::Fixed(4)]),
            5 => (9, vec![FilterStrategy::Adaptive, FilterStrategy::Fixed(0), FilterStrategy::Fixed(1), FilterStrategy::Fixed(2), FilterStrategy::Fixed(3), FilterStrategy::Fixed(4)]),
            _ => (9, vec![FilterStrategy::Adaptive, FilterStrategy::Fixed(0), FilterStrategy::Fixed(1), FilterStrategy::Fixed(2), FilterStrategy::Fixed(3), FilterStrategy::Fixed(4)]),
        }
    };
    let icc_level = if opt_level == 0 && !zopfli { 1 } else { 9 };
    let interlace = png.interlace == 1;
    let mut best: Option<Vec<u8>> = None;
    for pix in &candidates {
        for strat in &strategies {
            let encoded = encode_with_chunks(pix, png, interlace, *strat, zlib_level, zopfli, icc_level);
            if best.as_ref().map(|b| encoded.len() < b.len()).unwrap_or(true) { best = Some(encoded); }
        }
    }
    let best = best.unwrap_or_else(|| png.original.clone());
    if best.len() >= png.original.len() { png.original.clone() } else { best }
}

/// Lossy PNG: quantise, build an intermediate image, then choose the
/// smallest lossless representation of the quantised pixels.
pub fn compress_png_lossy(raster: &Raster, quality: u8, opt_level: u8, zopfli: bool, metadata: &Metadata, include_metadata: bool) -> Vec<u8> {
    let rgba = raster.rgba8();
    let q = crate::img::quantize(&rgba, raster.width, raster.height, quality, 256);
    // Build a synthetic PngImage around the quantised pixels so that the
    // representation search in the optimiser can be reused.
    let pixels: Vec<[u16;4]> = q.pixels.chunks_exact(4).map(|c| [c[0] as u16, c[1] as u16, c[2] as u16, c[3] as u16]).collect();
    let intermediate_kind = if raster.kind.is_16() { raster.kind.to_8() } else { raster.kind };
    let intermediate = {
        let mut r = Raster::new(raster.width, raster.height, intermediate_kind, vec![]);
        // Fill the intermediate raster's samples from the quantised pixels,
        // preserving the source colour kind (gray stays gray, etc.).
        let ch = intermediate_kind.channels();
        let mut data = Vec::with_capacity(raster.pixel_count() * ch);
        for p in &pixels {
            match ch {
                1 => data.push(p[0] as u8),
                2 => { data.push(p[0] as u8); data.push(p[3] as u8); }
                3 => { data.push(p[0] as u8); data.push(p[1] as u8); data.push(p[2] as u8); }
                _ => { data.push(p[0] as u8); data.push(p[1] as u8); data.push(p[2] as u8); data.push(p[3] as u8); }
            }
        }
        r.data = data;
        r
    };
    let intermediate_bytes = encode_png_generic(&intermediate, metadata, include_metadata);
    // Parse it back and run the optimiser; if anything fails, keep the bytes.
    match parse_png(&intermediate_bytes) {
        Ok(parsed) => optimize_png(&parsed, opt_level, zopfli),
        Err(_) => intermediate_bytes,
    }
}

pub fn png_dimensions(data: &[u8]) -> Option<(u32, u32)> {
    if data.len() < 24 { return None; }
    Some((u32::from_be_bytes([data[16], data[17], data[18], data[19]]), u32::from_be_bytes([data[20], data[21], data[22], data[23]])))
}

pub fn decode_png_to_raster(data: &[u8], flavor: Flavor) -> CResult<(Raster, Metadata)> {
    let png = parse_png(data).map_err(|e| e.to_cerror(flavor))?;
    Ok((png.to_raster(), png.metadata.clone()))
}
