fn err(msg: &str, code: u32) -> CError { CError::new(msg, code) }

struct RawFrame {
    x: u32, y: u32, w: u32, h: u32,
    indices: Vec<u8>,
    palette: Vec<[u8; 3]>,
    transparent: Option<u8>,
    delay_cs: u16,
    disposal: u8,
}

fn lzw_decode(data: &[u8], min_code: u8, expected: usize) -> CResult<Vec<u8>> {
    if !(2..=8).contains(&min_code) {
        return Err(err("malformed GIF image data", 20404));
    }
    let clear = 1u16 << min_code;
    let eoi = clear + 1;
    let mut dict: Vec<Vec<u8>> = (0..clear).map(|i| vec![i as u8]).collect();
    dict.push(vec![]); // clear
    dict.push(vec![]); // eoi
    let mut code_size = (min_code as u32) + 1;
    let mut out: Vec<u8> = Vec::with_capacity(expected);
    let mut prev: Option<Vec<u8>> = None;
    let mut bitpos = 0usize;
    let total_bits = data.len() * 8;
    let read_code = |bitpos: usize, size: u32, data: &[u8]| -> Option<u16> {
        if bitpos + size as usize > total_bits { return None; }
        let mut val = 0u32;
        for i in 0..size as usize {
            let byte = data[(bitpos + i) / 8];
            let bit = (byte >> ((bitpos + i) % 8)) & 1;
            val |= (bit as u32) << i;
        }
        Some(val as u16)
    };
    while out.len() < expected {
        let Some(code) = read_code(bitpos, code_size, data) else { break };
        bitpos += code_size as usize;
        if code == clear {
            dict.truncate((clear + 2) as usize);
            code_size = min_code as u32 + 1;
            prev = None;
            continue;
        }
        if code == eoi { break; }
        let entry: Vec<u8> = if (code as usize) < dict.len() {
            dict[code as usize].clone()
        } else if (code as usize) == dict.len() {
            match &prev {
                Some(p) => { let mut e = p.clone(); e.push(p[0]); e }
                None => return Err(err("malformed GIF image data", 20404)),
            }
        } else {
            return Err(err("malformed GIF image data", 20404));
        };
        out.extend_from_slice(&entry);
        if let Some(p) = &prev {
            let mut new_entry = p.clone();
            new_entry.push(entry[0]);
            dict.push(new_entry);
            if dict.len() as u32 == (1u32 << code_size) && code_size < 12 {
                code_size += 1;
            }
        }
        prev = Some(entry);
    }
    if out.len() < expected {
        return Err(CError::with_codes("Found no usable frames to encode", vec![20409, 20411]));
    }
    out.truncate(expected);
    Ok(out)
}

pub fn parse_gif(data: &[u8]) -> CResult<GifInfo> {
    if data.len() < 13 || &data[0..3] != b"GIF" {
        return Err(err("malformed GIF header", 20404));
    }
    if &data[3..6] != b"87a" && &data[3..6] != b"89a" {
        return Err(err("malformed GIF header", 20404));
    }
    let width = u16::from_le_bytes([data[6], data[7]]) as u32;
    let height = u16::from_le_bytes([data[8], data[9]]) as u32;
    let packed = data[10];
    let mut pos = 13usize;
    let mut global_palette: Vec<[u8;3]> = Vec::new();
    if packed & 0x80 != 0 {
        let n = 3 * (1usize << ((packed & 7) + 1));
        if pos + n > data.len() { return Err(CError::with_codes("Found no usable frames to encode", vec![20409, 20411])); }
        global_palette = data[pos..pos+n].chunks_exact(3).map(|c| [c[0],c[1],c[2]]).collect();
        pos += n;
    }
    let mut loop_count: Option<u16> = None;
    let mut raw_frames: Vec<RawFrame> = Vec::new();
    let mut gce = (0u8, 0u16, None::<u8>); // disposal, delay, transparent

    let read_subblocks = |data: &[u8], mut p: usize| -> Option<(Vec<Vec<u8>>, usize)> {
        let mut blocks = Vec::new();
        loop {
            if p >= data.len() { return None; }
            let sz = data[p] as usize;
            p += 1;
            if sz == 0 { break; }
            if p + sz > data.len() { return None; }
            blocks.push(data[p..p+sz].to_vec());
            p += sz;
        }
        Some((blocks, p))
    };

    while pos < data.len() {
        match data[pos] {
            0x3B => break,
            0x21 => {
                if pos + 1 >= data.len() { break; }
                let label = data[pos + 1];
                pos += 2;
                match label {
                    0xF9 => {
                        if pos >= data.len() { break; }
                        let sz = data[pos] as usize;
                        if sz < 4 || pos + 1 + sz >= data.len() { break; }
                        let p = data[pos + 1];
                        gce.0 = (p >> 2) & 7;
                        gce.1 = u16::from_le_bytes([data[pos+2], data[pos+3]]);
                        gce.2 = if p & 1 != 0 { Some(data[pos+4]) } else { None };
                        pos += 1 + sz + 1; // block + terminator
                    }
                    0xFF => {
                        // Application extension: first sub-block is the app id.
                        match read_subblocks(data, pos) {
                            Some((blocks, newp)) => {
                                pos = newp;
                                if blocks.len() >= 2 && &blocks[0] == b"NETSCAPE2.0" && blocks[1].len() >= 3 && blocks[1][0] == 1 {
                                    loop_count = Some(u16::from_le_bytes([blocks[1][1], blocks[1][2]]));
                                }
                            }
                            None => break,
                        }
                    }
                    0x01 => {
                        // Plain text: a fixed 12-byte block then sub-blocks.
                        if pos < data.len() {
                            let sz = data[pos] as usize;
                            match read_subblocks(data, pos + 1 + sz) {
                                Some((_, newp)) => pos = newp,
                                None => break,
                            }
                        }
                    }
                    _ => {
                        match read_subblocks(data, pos) {
                            Some((_, newp)) => pos = newp,
                            None => break,
                        }
                    }
                }
            }
            0x2C => {
                if pos + 10 > data.len() { break; }
                let x = u16::from_le_bytes([data[pos+1], data[pos+2]]) as u32;
                let y = u16::from_le_bytes([data[pos+3], data[pos+4]]) as u32;
                let w = u16::from_le_bytes([data[pos+5], data[pos+6]]) as u32;
                let h = u16::from_le_bytes([data[pos+7], data[pos+8]]) as u32;
                let ipacked = data[pos+9];
                pos += 10;
                let mut palette = global_palette.clone();
                if ipacked & 0x80 != 0 {
                    let n = 3 * (1usize << ((ipacked & 7) + 1));
                    if pos + n > data.len() { break; }
                    palette = data[pos..pos+n].chunks_exact(3).map(|c| [c[0],c[1],c[2]]).collect();
                    pos += n;
                }
                if pos >= data.len() { break; }
                let min_code = data[pos];
                pos += 1;
                let (blocks, newp) = match read_subblocks(data, pos) {
                    Some(v) => v,
                    None => break,
                };
                pos = newp;
                let compressed: Vec<u8> = blocks.into_iter().flatten().collect();
                let expected = (w as usize) * (h as usize);
                let decoded = lzw_decode(&compressed, min_code, expected)?;
                // Deinterlace if needed.
                let indices = if ipacked & 0x40 != 0 {
                    let mut out = vec![0u8; expected];
                    let passes = [(0u32, 8u32), (4, 8), (2, 4), (1, 2)];
                    let mut src = 0usize;
                    for (start, step) in passes {
                        let mut yy = start;
                        while yy < h {
                            let row_start = (yy as usize) * (w as usize);
                            out[row_start..row_start + w as usize].copy_from_slice(&decoded[src..src + w as usize]);
                            src += w as usize;
                            yy += step;
                        }
                    }
                    out
                } else { decoded };
                raw_frames.push(RawFrame { x, y, w, h, indices, palette, transparent: gce.2, delay_cs: gce.1, disposal: gce.0 });
                gce = (0, 0, None);
            }
            _ => break,
        }
    }

    if raw_frames.is_empty() {
        return Err(CError::with_codes("Found no usable frames to encode", vec![20409, 20411]));
    }

    // Composite frames.
    let npix = (width as usize) * (height as usize);
    let mut canvas = vec![0u8; npix * 4];
    let mut frames: Vec<GifFrame> = Vec::new();
    for raw in &raw_frames {
        let snapshot = canvas.clone();
        for row in 0..raw.h {
            for col in 0..raw.w {
                let idx = raw.indices[(row as usize) * (raw.w as usize) + col as usize];
                if Some(idx) == raw.transparent { continue; }
                let c = raw.palette.get(idx as usize).copied().unwrap_or([0,0,0]);
                let cx = raw.x + col;
                let cy = raw.y + row;
                if cx < width && cy < height {
                    let o = ((cy as usize) * (width as usize) + cx as usize) * 4;
                    canvas[o] = c[0]; canvas[o+1] = c[1]; canvas[o+2] = c[2]; canvas[o+3] = 255;
                }
            }
        }
        frames.push(GifFrame { rgba: canvas.clone(), delay_cs: raw.delay_cs, disposal: raw.disposal });
        match raw.disposal {
            2 => {
                for row in 0..raw.h {
                    for col in 0..raw.w {
                        let cx = raw.x + col; let cy = raw.y + row;
                        if cx < width && cy < height {
                            let o = ((cy as usize) * (width as usize) + cx as usize) * 4;
                            canvas[o..o+4].copy_from_slice(&[0,0,0,0]);
                        }
                    }
                }
            }
            3 => { canvas = snapshot; }
            _ => {}
        }
    }
    Ok(GifInfo { width, height, loop_count, frames })
}

impl GifInfo {
    pub fn first_frame_raster(&self) -> Raster {
        let rgba = self.frames.first().map(|f| f.rgba.clone()).unwrap_or_else(|| vec![0; (self.width as usize)*(self.height as usize)*4]);
        Raster::new(self.width, self.height, ColorKind::Rgba8, rgba)
    }
    pub fn metadata(&self) -> Metadata { Metadata::default() }
}

/// Transform input frame delays the way the observed encoder does:
/// each frame is timestamped by its cumulative *end* time, so the
/// resulting durations are rotated by one frame.
pub fn transform_delays(delays: &[u16]) -> Vec<u16> {
    let n = delays.len();
    if n <= 1 { return delays.to_vec(); }
    let pts0 = delays[0] as i64;
    // Relative start times after subtracting the first end timestamp.
    let mut starts: Vec<i64> = Vec::with_capacity(n);
    let mut acc: i64 = 0;
    for (i, d) in delays.iter().enumerate() {
        if i == 0 { starts.push(0); acc = 0; }
        else { acc += *d as i64; starts.push(acc); }
    }
    let mut dur: Vec<i64> = Vec::with_capacity(n);
    for i in 0..n - 1 { dur.push(starts[i + 1] - starts[i]); }
    let last = if pts0 >= 2 {
        pts0
    } else {
        // Use the last positive start interval as the final duration.
        let mut v = pts0;
        for i in (1..n).rev() {
            if starts[i] > starts[i-1] { v = starts[i] - starts[i-1]; break; }
        }
        v
    };
    dur.push(last);
    // Enforce a 2cs minimum, borrowing from later (then earlier) frames.
    for i in 0..n {
        if dur[i] >= 2 { continue; }
        let mut deficit = 2 - dur[i];
        dur[i] = 2;
        for j in (i + 1..n).chain(0..i) {
            if deficit <= 0 { break; }
            if dur[j] > 2 {
                let take = deficit.min(dur[j] - 2);
                dur[j] -= take;
                deficit -= take;
            }
        }
    }
    dur.iter().map(|d| (*d).clamp(0, 65535) as u16).collect()
}

fn lzw_encode(indices: &[u8], min_code: u8) -> Vec<u8> {
    let clear = 1u16 << min_code;
    let eoi = clear + 1;
    let mut dict: std::collections::HashMap<Vec<u8>, u16> = std::collections::HashMap::new();
    let reset = |dict: &mut std::collections::HashMap<Vec<u8>, u16>| {
        dict.clear();
        for i in 0..clear { dict.insert(vec![i as u8], i); }
    };
    reset(&mut dict);
    let mut next_code = eoi + 1;
    let mut code_size = (min_code as u32) + 1;
    let mut out: Vec<u8> = Vec::new();
    let mut bitbuf: u32 = 0;
    let mut bitcnt: u32 = 0;
    let mut emit = |code: u16, size: u32, out: &mut Vec<u8>, bitbuf: &mut u32, bitcnt: &mut u32| {
        *bitbuf |= (code as u32) << *bitcnt;
        *bitcnt += size;
        while *bitcnt >= 8 {
            out.push((*bitbuf & 0xFF) as u8);
            *bitbuf >>= 8;
            *bitcnt -= 8;
        }
    };
    emit(clear, code_size, &mut out, &mut bitbuf, &mut bitcnt);
    if indices.is_empty() {
        emit(eoi, code_size, &mut out, &mut bitbuf, &mut bitcnt);
    } else {
        let mut cur: Vec<u8> = vec![indices[0]];
        for &next in &indices[1..] {
            let mut candidate = cur.clone();
            candidate.push(next);
            if dict.contains_key(&candidate) {
                cur = candidate;
            } else {
                let code = dict[&cur];
                emit(code, code_size, &mut out, &mut bitbuf, &mut bitcnt);
                if next_code < 4096 {
                    dict.insert(candidate, next_code);
                    next_code += 1;
                    if next_code - 1 == (1u16 << code_size) && code_size < 12 {
                        code_size += 1;
                    }
                } else {
                    emit(clear, code_size, &mut out, &mut bitbuf, &mut bitcnt);
                    reset(&mut dict);
                    next_code = eoi + 1;
                    code_size = (min_code as u32) + 1;
                }
                cur = vec![next];
            }
        }
        let code = dict[&cur];
        emit(code, code_size, &mut out, &mut bitbuf, &mut bitcnt);
        emit(eoi, code_size, &mut out, &mut bitbuf, &mut bitcnt);
    }
    if bitcnt > 0 { out.push((bitbuf & 0xFF) as u8); }
    out
}

pub struct GifFrameSpec {
    pub rgba: Vec<u8>,
    pub delay_cs: u16,
}

pub fn encode_gif(width: u32, height: u32, frames: &[GifFrameSpec], loop_count: Option<u16>, quality: u8) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::new();
    out.extend_from_slice(b"GIF89a");
    out.extend_from_slice(&(width as u16).to_le_bytes());
    out.extend_from_slice(&(height as u16).to_le_bytes());
    out.push(0x80); out.push(0); out.push(0);
    out.extend_from_slice(&[0, 0, 0, 0, 0, 0]); // 2-entry global colour table
    if let Some(loopn) = loop_count {
        out.push(0x21); out.push(0xFF); out.push(11);
        out.extend_from_slice(b"NETSCAPE2.0");
        out.push(3); out.push(1);
        out.extend_from_slice(&loopn.to_le_bytes());
        out.push(0);
    }
    out.push(0x21); out.push(0xFE); out.push(7);
    out.extend_from_slice(b"gif.ski");
    out.push(0);

    let w = width as usize;
    let h = height as usize;
    let mut prev: Option<&Vec<u8>> = None;
    for (fi, frame) in frames.iter().enumerate() {
        // Bounding box of changed (or, for the first frame, all) pixels.
        let (mut x0, mut y0, mut x1, mut y1) = (w, h, 0usize, 0usize);
        let mut any = false;
        for y in 0..h {
            for x in 0..w {
                let i = (y * w + x) * 4;
                let changed = match prev {
                    None => true,
                    Some(p) => p[i..i+4] != frame.rgba[i..i+4],
                };
                if changed {
                    any = true;
                    x0 = x0.min(x); y0 = y0.min(y); x1 = x1.max(x + 1); y1 = y1.max(y + 1);
                }
            }
        }
        let (crop_x, crop_y, crop_w, crop_h, crop_rgba) = if !any {
            (0u32, 0u32, 1u32, 1u32, vec![0u8, 0, 0, 0])
        } else {
            let mut buf = Vec::with_capacity((x1 - x0) * (y1 - y0) * 4);
            for y in y0..y1 {
                for x in x0..x1 {
                    let i = (y * w + x) * 4;
                    let unchanged = prev.map(|p| p[i..i+4] == frame.rgba[i..i+4]).unwrap_or(false);
                    if unchanged {
                        buf.extend_from_slice(&[0, 0, 0, 0]);
                    } else {
                        buf.extend_from_slice(&frame.rgba[i..i+4]);
                    }
                }
            }
            (x0 as u32, y0 as u32, (x1 - x0) as u32, (y1 - y0) as u32, buf)
        };
        let uses_transparency = fi > 0 || crop_rgba.chunks_exact(4).any(|p| p[3] == 0);
        // Quantise the crop.
        let q = quantize(&crop_rgba, crop_w.max(1), crop_h.max(1), quality, 256);
        // Build a GIF palette: index 0 is transparency when needed.
        let mut gif_palette: Vec<[u8;3]> = Vec::new();
        let mut gif_indices: Vec<u8> = Vec::with_capacity(crop_w as usize * crop_h as usize);
        let mut index_map: std::collections::HashMap<[u8;3], u8> = std::collections::HashMap::new();
        if uses_transparency { gif_palette.push([0, 0, 0]); }
        let mut has_transparent_pixel = false;
        for px in q.pixels.chunks_exact(4) {
            if px[3] == 0 && uses_transparency {
                gif_indices.push(0);
                has_transparent_pixel = true;
            } else {
                let rgb = [px[0], px[1], px[2]];
                let idx = *index_map.entry(rgb).or_insert_with(|| {
                    gif_palette.push(rgb);
                    (gif_palette.len() - 1) as u8
                });
                gif_indices.push(idx);
            }
        }
        if gif_palette.is_empty() { gif_palette.push([0,0,0]); }
        // If we reserved transparency but nothing used it and this is the
        // first frame, drop the reservation.
        let transparent_flag = uses_transparency && has_transparent_pixel;
        // disposal: 2 for a first frame containing transparency, else 1.
        let disposal: u8 = if fi == 0 && transparent_flag { 2 } else { 1 };
        // Graphic Control Extension
        out.push(0x21); out.push(0xF9); out.push(4);
        out.push((disposal << 2) | if transparent_flag { 1 } else { 0 });
        out.extend_from_slice(&frame.delay_cs.to_le_bytes());
        out.push(0); // transparent index
        out.push(0);
        // Image descriptor
        let palette_len = gif_palette.len().next_power_of_two().max(2);
        let log2 = (usize::BITS - (palette_len - 1).leading_zeros()) as u8; // palette_len = 2^log2
        out.push(0x2C);
        out.extend_from_slice(&(crop_x as u16).to_le_bytes());
        out.extend_from_slice(&(crop_y as u16).to_le_bytes());
        out.extend_from_slice(&(crop_w as u16).to_le_bytes());
        out.extend_from_slice(&(crop_h as u16).to_le_bytes());
        out.push(0x80 | (log2 - 1));
        for i in 0..palette_len {
            let c = gif_palette.get(i).copied().unwrap_or([0,0,0]);
            out.extend_from_slice(&c);
        }
        let min_code = log2.max(2);
        out.push(min_code);
        let compressed = lzw_encode(&gif_indices, min_code);
        for block in compressed.chunks(255) {
            out.push(block.len() as u8);
            out.extend_from_slice(block);
        }
        out.push(0);
        prev = Some(&frame.rgba);
    }
    out.push(0x3B);
    out
}
