cat > src/webp.rs << 'RS'
use crate::error::{CError, CResult};
use crate::img::{ColorKind, Metadata, Raster};
use std::ffi::CString;
use std::os::raw::{c_char, c_int, c_void};
use std::sync::OnceLock;

#[cfg(unix)]
extern "C" {
    fn dlopen(filename: *const c_char, flag: c_int) -> *mut c_void;
    fn dlsym(handle: *mut c_void, symbol: *const c_char) -> *mut c_void;
}

type FnGetInfo = unsafe extern "C" fn(*const u8, usize, *mut c_int, *mut c_int) -> c_int;
type FnDecodeRGBA = unsafe extern "C" fn(*const u8, usize, *mut c_int, *mut c_int) -> *mut u8;
type FnDecodeRGB = unsafe extern "C" fn(*const u8, usize, *mut c_int, *mut c_int) -> *mut u8;
type FnEncodeRGBA = unsafe extern "C" fn(*const u8, c_int, c_int, c_int, f32, *mut *mut u8) -> usize;
type FnEncodeRGB = unsafe extern "C" fn(*const u8, c_int, c_int, c_int, f32, *mut *mut u8) -> usize;
type FnEncodeLosslessRGBA = unsafe extern "C" fn(*const u8, c_int, c_int, c_int, *mut *mut u8) -> usize;
type FnEncodeLosslessRGB = unsafe extern "C" fn(*const u8, c_int, c_int, c_int, *mut *mut u8) -> usize;
type FnFree = unsafe extern "C" fn(*mut c_void);
type FnGetFeatures = unsafe extern "C" fn(*const u8, usize, *mut WebPBitstreamFeatures) -> c_int;

#[repr(C)]
struct WebPBitstreamFeatures {
    width: c_int,
    height: c_int,
    has_alpha: c_int,
    has_animation: c_int,
    format: c_int,
    pad: [u32; 5],
}

struct LibWebP {
    get_info: FnGetInfo,
    decode_rgba: FnDecodeRGBA,
    decode_rgb: FnDecodeRGB,
    encode_rgba: FnEncodeRGBA,
    encode_rgb: FnEncodeRGB,
    encode_lossless_rgba: FnEncodeLosslessRGBA,
    encode_lossless_rgb: FnEncodeLosslessRGB,
    free: FnFree,
    get_features: Option<FnGetFeatures>,
}

static LIB: OnceLock<Option<LibWebP>> = OnceLock::new();

fn lib() -> Option<&'static LibWebP> {
    LIB.get_or_init(|| {
        #[cfg(unix)]
        unsafe {
            let mut handle: *mut c_void = std::ptr::null_mut();
            for name in ["libwebp.so.7", "libwebp.so"] {
                let cname = CString::new(name).unwrap();
                handle = dlopen(cname.as_ptr(), 1); // RTLD_LAZY
                if !handle.is_null() { break; }
            }
            if handle.is_null() { return None; }
            macro_rules! sym {
                ($name:literal, $ty:ty) => {{
                    let cname = CString::new($name).unwrap();
                    let p = dlsym(handle, cname.as_ptr());
                    if p.is_null() { return None; }
                    std::mem::transmute::<*mut c_void, $ty>(p)
                }};
            }
            let get_features = {
                let cname = CString::new("WebPGetFeatures").unwrap();
                let p = dlsym(handle, cname.as_ptr());
                if p.is_null() { None } else { Some(std::mem::transmute::<*mut c_void, FnGetFeatures>(p)) }
            };
            Some(LibWebP {
                get_info: sym!("WebPGetInfo", FnGetInfo),
                decode_rgba: sym!("WebPDecodeRGBA", FnDecodeRGBA),
                decode_rgb: sym!("WebPDecodeRGB", FnDecodeRGB),
                encode_rgba: sym!("WebPEncodeRGBA", FnEncodeRGBA),
                encode_rgb: sym!("WebPEncodeRGB", FnEncodeRGB),
                encode_lossless_rgba: sym!("WebPEncodeLosslessRGBA", FnEncodeLosslessRGBA),
                encode_lossless_rgb: sym!("WebPEncodeLosslessRGB", FnEncodeLosslessRGB),
                free: sym!("WebPFree", FnFree),
                get_features,
            })
        }
        #[cfg(not(unix))]
        { None }
    }).as_ref()
}

fn null_decoder_err() -> CError { CError::new("null_decoder", 20304) }

pub struct WebpInfo {
    pub width: u32,
    pub height: u32,
    pub has_alpha: bool,
    pub metadata: Metadata,
}

fn parse_webp_chunks(data: &[u8]) -> Metadata {
    let mut meta = Metadata::default();
    if data.len() < 12 { return meta; }
    let mut pos = 12usize;
    while pos + 8 <= data.len() {
        let typ = &data[pos..pos+4];
        let len = u32::from_le_bytes([data[pos+4], data[pos+5], data[pos+6], data[pos+7]]) as usize;
        if pos + 8 + len > data.len() { break; }
        let payload = &data[pos + 8..pos + 8 + len];
        match typ {
            b"EXIF" => { if meta.exif.is_none() { meta.exif = Some(payload.to_vec()); } }
            b"ICCP" => { if meta.icc.is_none() { meta.icc = Some(payload.to_vec()); } }
            _ => {}
        }
        pos += 8 + len + (len & 1);
    }
    if let Some(exif) = &meta.exif { meta.orientation = crate::img::exif_orientation(exif); }
    meta
}

pub fn webp_dimensions(data: &[u8]) -> Option<(u32, u32)> {
    // Parse the bitstream headers directly (also works if libwebp missing).
    if data.len() < 21 || &data[0..4] != b"RIFF" || &data[8..12] != b"WEBP" { return None; }
    match &data[12..16] {
        b"VP8 " => {
            if data.len() < 30 { return None; }
            let w = u16::from_le_bytes([data[26], data[27]]) & 0x3FFF;
            let h = u16::from_le_bytes([data[28], data[29]]) & 0x3FFF;
            Some((w as u32, h as u32))
        }
        b"VP8L" => {
            if data.len() < 25 { return None; }
            let bits = u32::from_le_bytes([data[21], data[22], data[23], data[24]]);
            Some(((bits & 0x3FFF) + 1, ((bits >> 14) & 0x3FFF) + 1))
        }
        b"VP8X" => {
            if data.len() < 30 { return None; }
            let w = u32::from_le_bytes([data[24], data[25], data[26], 0]) + 1;
            let h = u32::from_le_bytes([data[27], data[28], data[29], 0]) + 1;
            Some((w, h))
        }
        _ => None,
    }
}

pub fn decode_webp(data: &[u8]) -> CResult<(Raster, Metadata)> {
    let lib = lib().ok_or_else(null_decoder_err)?;
    let mut features = WebPBitstreamFeatures { width: 0, height: 0, has_alpha: 0, has_animation: 0, format: 0, pad: [0; 5] };
    let mut has_alpha = false;
    let mut w: c_int = 0;
    let mut h: c_int = 0;
    unsafe {
        if let Some(get_features) = lib.get_features {
            let rc = get_features(data.as_ptr(), data.len(), &mut features);
            if rc != 0 { return Err(null_decoder_err()); }
            has_alpha = features.has_alpha != 0;
            w = features.width; h = features.height;
            // Animated WebP: features report the canvas; WebPDecode* only
            // decodes still images, so treat animations as an error here and
            // let the caller fall back to first-frame handling if needed.
            if features.has_animation != 0 {
                // DecodeRGBA on an animated file actually returns the first
                // frame in recent libwebp versions, so simply proceed.
            }
        } else if (lib.get_info)(data.as_ptr(), data.len(), &mut w, &mut h) == 0 {
            return Err(null_decoder_err());
        }
    }
    if w <= 0 || h <= 0 { return Err(null_decoder_err()); }
    let (mut dw, mut dh) = (0 as c_int, 0 as c_int);
    let (pixels, kind) = unsafe {
        if has_alpha {
            let ptr = (lib.decode_rgba)(data.as_ptr(), data.len(), &mut dw, &mut dh);
            if ptr.is_null() { return Err(null_decoder_err()); }
            let len = (dw as usize) * (dh as usize) * 4;
            let v = std::slice::from_raw_parts(ptr, len).to_vec();
            (lib.free)(ptr as *mut c_void);
            (v, ColorKind::Rgba8)
        } else {
            let ptr = (lib.decode_rgb)(data.as_ptr(), data.len(), &mut dw, &mut dh);
            if ptr.is_null() {
                // Some VP8L files with alpha are not flagged by GetFeatures'
                // cheap header scan; retry as RGBA.
                let ptr2 = (lib.decode_rgba)(data.as_ptr(), data.len(), &mut dw, &mut dh);
                if ptr2.is_null() { return Err(null_decoder_err()); }
                let len = (dw as usize) * (dh as usize) * 4;
                let v = std::slice::from_raw_parts(ptr2, len).to_vec();
                (lib.free)(ptr2 as *mut c_void);
                // Determine whether any alpha is actually used.
                if v.chunks_exact(4).all(|p| p[3] == 255) {
                    let rgb: Vec<u8> = v.chunks_exact(4).flat_map(|p| [p[0], p[1], p[2]]).collect();
                    (rgb, ColorKind::Rgb8)
                } else {
                    (v, ColorKind::Rgba8)
                }
            } else {
                let len = (dw as usize) * (dh as usize) * 3;
                let v = std::slice::from_raw_parts(ptr, len).to_vec();
                (lib.free)(ptr as *mut c_void);
                (v, ColorKind::Rgb8)
            }
        }
    };
    let raster = Raster::new(dw as u32, dh as u32, kind, pixels);
    Ok((raster, parse_webp_chunks(data)))
}

pub fn encode_webp(raster: &Raster, quality: Option<u8>, metadata: &Metadata, include_metadata: bool) -> CResult<Vec<u8>> {
    // quality None => lossless
    let lib = lib().ok_or_else(|| CError::new("null_encoder", 20305))?;
    let rgba = raster.rgba8();
    let has_alpha = raster.has_alpha() || rgba.chunks_exact(4).any(|p| p[3] < 255);
    let w = raster.width as c_int;
    let h = raster.height as c_int;
    let mut out_ptr: *mut u8 = std::ptr::null_mut();
    let size = unsafe {
        if has_alpha {
            match quality {
                Some(q) => (lib.encode_rgba)(rgba.as_ptr(), w, h, w * 4, q as f32, &mut out_ptr),
                None => (lib.encode_lossless_rgba)(rgba.as_ptr(), w, h, w * 4, &mut out_ptr),
            }
        } else {
            // Convert to packed RGB.
            let rgb: Vec<u8> = rgba.chunks_exact(4).flat_map(|p| [p[0], p[1], p[2]]).collect();
            match quality {
                Some(q) => (lib.encode_rgb)(rgb.as_ptr(), w, h, w * 3, q as f32, &mut out_ptr),
                None => (lib.encode_lossless_rgb)(rgb.as_ptr(), w, h, w * 3, &mut out_ptr),
            }
        }
    };
    if size == 0 || out_ptr.is_null() {
        // Mirror the observed panic-inducing encoder error as a plain error.
        return Err(CError::new("VP8_ENC_ERROR_BAD_DIMENSION", 20305));
    }
    let encoded = unsafe {
        let v = std::slice::from_raw_parts(out_ptr, size).to_vec();
        (lib.free)(out_ptr as *mut c_void);
        v
    };
    if include_metadata && (metadata.icc.is_some() || metadata.exif.is_some()) {
        Ok(mux_metadata(&encoded, raster.width, raster.height, metadata))
    } else {
        Ok(encoded)
    }
}

fn write_chunk(out: &mut Vec<u8>, typ: &[u8;4], payload: &[u8]) {
    out.extend_from_slice(typ);
    out.extend_from_slice(&(payload.len() as u32).to_le_bytes());
    out.extend_from_slice(payload);
    if payload.len() % 2 == 1 { out.push(0); }
}

fn mux_metadata(encoded: &[u8], width: u32, height: u32, metadata: &Metadata) -> Vec<u8> {
    // Parse the encoded file into chunks.
    let mut chunks: Vec<([u8;4], Vec<u8>)> = Vec::new();
    let mut pos = 12usize;
    while pos + 8 <= encoded.len() {
        let mut typ = [0u8;4];
        typ.copy_from_slice(&encoded[pos..pos+4]);
        let len = u32::from_le_bytes([encoded[pos+4], encoded[pos+5], encoded[pos+6], encoded[pos+7]]) as usize;
        if pos + 8 + len > encoded.len() { break; }
        chunks.push((typ, encoded[pos+8..pos+8+len].to_vec()));
        pos += 8 + len + (len & 1);
    }
    let has_vp8x = chunks.first().map(|c| &c.0 == b"VP8X").unwrap_or(false);
    let mut out: Vec<u8> = Vec::new();
    out.extend_from_slice(b"RIFF");
    out.extend_from_slice(&[0,0,0,0]); // patched below
    out.extend_from_slice(b"WEBP");
    if has_vp8x {
        // Keep the original VP8X (flags unchanged), then pass through
        // chunks, inserting ICCP before the image chunk (but after ALPH).
        let mut inserted_icc = false;
        for (typ, payload) in &chunks {
            if (&typ == b"VP8 " || &typ == b"VP8L") && !inserted_icc {
                if let Some(icc) = &metadata.icc { write_chunk(&mut out, b"ICCP", icc); }
                inserted_icc = true;
            }
