use crate::error::{CError, CResult};
use crate::img::Raster;
use crate::z;

// TIFF encoding matching the observed layout: header, deflate-compressed
// strips, external tag values in ascending tag order, then the IFD.
pub fn encode_tiff(raster: &Raster, best_compression: bool) -> CResult<Vec<u8>> {
    let spp: usize = match raster.kind {
        crate::img::ColorKind::Rgb8 => 3,
        crate::img::ColorKind::Rgba8 => 4,
        other => {
            // L8 / Rgb16 get the bespoke message, other unsupported kinds
            // get the image-crate style message.
            return Err(match other {
                crate::img::ColorKind::L8 => CError::with_codes("Unsupported TIFF color type (L8)", vec![20506, 10405]),
                crate::img::ColorKind::Rgb16 => CError::with_codes("Unsupported TIFF color type (Rgb16)", vec![20506, 10405]),
                crate::img::ColorKind::L16 => CError::with_codes("Unsupported TIFF color type (L16)", vec![20506, 10405]),
                crate::img::ColorKind::Rgba16 => CError::with_codes("Unsupported TIFF color type (Rgba16)", vec![20506, 10405]),
                k => CError::new(format!("The encoder or decoder for Tiff does not support the color type `{}`", k.name()), 10404),
            });
        }
    };
    let w = raster.width;
    let h = raster.height;
    let rgba = raster.rgba8();
    let mut rgb = Vec::with_capacity((w as usize) * (h as usize) * spp);
    for px in rgba.chunks_exact(4) {
        rgb.extend_from_slice(&px[..spp]);
    }
    let row_bytes = (w as usize) * spp;
    let rows_per_strip: u32 = ((1_000_000usize + row_bytes - 1) / row_bytes.max(1)) as u32;
    let level = if best_compression { 9 } else { 6 };

    // Compress strips.
    let mut strip_data: Vec<Vec<u8>> = Vec::new();
    let mut y = 0u32;
    while y < h {
        let rows = rows_per_strip.min(h - y) as usize;
        let start = (y as usize) * row_bytes;
        let end = start + rows * row_bytes;
        strip_data.push(z::compress(&rgb[start..end], level));
        y += rows as u32;
    }
    if strip_data.is_empty() { strip_data.push(z::compress(&[], level)); }

    let mut out: Vec<u8> = Vec::new();
    out.extend_from_slice(b"II*\x00");
    out.extend_from_slice(&[0,0,0,0]); // IFD offset, patched below
    let mut strip_offsets: Vec<u32> = Vec::new();
    let mut strip_counts: Vec<u32> = Vec::new();
    for s in &strip_data {
        strip_offsets.push(out.len() as u32);
        strip_counts.push(s.len() as u32);
        out.extend_from_slice(s);
    }

    // External values, in ascending tag order: BitsPerSample (258),
    // StripOffsets (273, if multiple), StripByteCounts (279, if multiple),
    // XResolution (282), YResolution (283), SampleFormat (339).
    let bits: Vec<u16> = vec![8; spp];
    let sample_format: Vec<u16> = vec![1; spp];
    let write_shorts = |out: &mut Vec<u8>, vals: &[u16]| -> u32 {
        let off = out.len() as u32;
        for v in vals { out.extend_from_slice(&v.to_le_bytes()); }
        off
    };
    let write_longs = |out: &mut Vec<u8>, vals: &[u32]| -> u32 {
        let off = out.len() as u32;
        for v in vals { out.extend_from_slice(&v.to_le_bytes()); }
        off
    };
    let bits_off = write_shorts(&mut out, &bits);
    let strip_offsets_off = if strip_offsets.len() > 1 { write_longs(&mut out, &strip_offsets) } else { 0 };
    let strip_counts_off = if strip_counts.len() > 1 { write_longs(&mut out, &strip_counts) } else { 0 };
    let xres_off = out.len() as u32;
    out.extend_from_slice(&1u32.to_le_bytes()); out.extend_from_slice(&1u32.to_le_bytes());
    let yres_off = out.len() as u32;
    out.extend_from_slice(&1u32.to_le_bytes()); out.extend_from_slice(&1u32.to_le_bytes());
    let sf_off = write_shorts(&mut out, &sample_format);

    let ifd_offset = out.len() as u32;
    out[4..8].copy_from_slice(&ifd_offset.to_le_bytes());

    // Tag entries: (tag, type, count, value field as 4 bytes)
    let short_val = |v: u16| -> [u8;4] { let mut b = [0u8;4]; b[..2].copy_from_slice(&v.to_le_bytes()); b };
    let long_val = |v: u32| -> [u8;4] { v.to_le_bytes() };
    let entries: Vec<(u16, u16, u32, [u8;4])> = vec![
        (256, 4, 1, long_val(w)),
        (257, 4, 1, long_val(h)),
        (258, 3, spp as u32, long_val(bits_off)),
        (259, 3, 1, short_val(8)),          // Compression = Adobe Deflate
        (262, 3, 1, short_val(2)),          // Photometric = RGB
        (273, 4, strip_offsets.len() as u32, if strip_offsets.len() == 1 { long_val(strip_offsets[0]) } else { long_val(strip_offsets_off) }),
        (277, 3, 1, short_val(spp as u16)),
        (278, 4, 1, long_val(rows_per_strip)),
        (279, 4, strip_counts.len() as u32, if strip_counts.len() == 1 { long_val(strip_counts[0]) } else { long_val(strip_counts_off) }),
        (282, 5, 1, long_val(xres_off)),
        (283, 5, 1, long_val(yres_off)),
        (296, 3, 1, short_val(1)),
        (339, 3, spp as u32, long_val(sf_off)),
    ];
    out.extend_from_slice(&(entries.len() as u16).to_le_bytes());
    for (tag, typ, cnt, val) in &entries {
        out.extend_from_slice(&tag.to_le_bytes());
        out.extend_from_slice(&typ.to_le_bytes());
        out.extend_from_slice(&cnt.to_le_bytes());
        out.extend_from_slice(val);
    }
    out.extend_from_slice(&[0,0,0,0]);
    Ok(out)
}
