                        major: seg.payload[5], minor: seg.payload[6], units: seg.payload[7],
                        x_density: u16::from_be_bytes([seg.payload[8], seg.payload[9]]),
                        y_density: u16::from_be_bytes([seg.payload[10], seg.payload[11]]),
