                    metadata.exif = Some(seg.payload[6..].to_vec());
                }
                if seg.marker == 0xE2 && seg.payload.starts_with(b"ICC_PROFILE\0") && seg.payload.len() >= 14 {
                    icc_parts.push((seg.payload[12], seg.payload[14..].to_vec()));
                }
                if seg.marker == 0xEE && seg.payload.starts_with(b"Adobe") && seg.payload.len() >= 12 {
                    adobe_transform = Some(seg.payload[11]);
                }
            }
            0xDB => {
                let mut p = 0usize;
                while p < seg.payload.len() {
                    let pq = seg.payload[p] >> 4;
                    let tq = (seg.payload[p] & 15) as usize;
                    p += 1;
                    if tq >= quant.len() { quant.resize(tq + 1, None); }
                    let mut table = [0u16; 64];
                    for i in 0..64 {
                        if pq == 0 {
                            if p + i >= seg.payload.len() { return Err(internal_jpeg_error(51)); }
                            table[ZIGZAG[i]] = seg.payload[p + i] as u16;
                        } else {
                            let o = p + i * 2;
                            if o + 1 >= seg.payload.len() + 1 { return Err(internal_jpeg_error(51)); }
                            if o + 2 > seg.payload.len() { return Err(internal_jpeg_error(51)); }
                            table[ZIGZAG[i]] = u16::from_be_bytes([seg.payload[o], seg.payload[o + 1]]);
                        }
                    }
                    quant[tq] = Some(table);
                    p += if pq == 0 { 64 } else { 128 };
                }
            }
            0xDD => {
                if seg.payload.len() >= 2 {
                    restart_interval = u16::from_be_bytes([seg.payload[0], seg.payload[1]]) as usize;
                }
            }
            m if is_sof(m) => {
                sof_type = m;
                progressive = m == 0xC2 || m == 0xCA;
                if seg.payload.len() < 6 { return Err(internal_jpeg_error(51)); }
                precision = seg.payload[0];
                height = u16::from_be_bytes([seg.payload[1], seg.payload[2]]) as u32;
                width = u16::from_be_bytes([seg.payload[3], seg.payload[4]]) as u32;
                let n = seg.payload[5] as usize;
                components.clear();
                for i in 0..n {
                    let o = 6 + i * 3;
                    if o + 2 >= seg.payload.len() + 1 || o + 3 > seg.payload.len() { return Err(internal_jpeg_error(51)); }
                    components.push(Comp {
                        id: seg.payload[o],
                        h: (seg.payload[o + 1] >> 4) as usize,
                        v: (seg.payload[o + 1] & 15) as usize,
                        tq: seg.payload[o + 2] as usize,
                    });
                }
            }
