fn scale_qtable(base: &[u16; 64], quality: u8) -> [u16; 64] {
    let mut q = quality as i32;
    if q <= 0 { q = 1; }
    if q > 100 { q = 100; }
    let scale = if q < 50 { 5000 / q } else { 200 - 2 * q };
    let mut out = [0u16; 64];
    for i in 0..64 {
        let mut v = (base[i] as i32 * scale + 50) / 100;
        if v < 1 { v = 1; }
        if v > 65535 { v = 65535; }
        out[i] = v as u16;
    }
    out
}

#[derive(Clone, Debug)]
pub struct Jfif {
    pub major: u8, pub minor: u8, pub units: u8, pub x_density: u16, pub y_density: u16,
}
impl Default for Jfif {
    fn default() -> Self { Self { major: 1, minor: 1, units: 0, x_density: 1, y_density: 1 } }
}

#[derive(Clone, Debug)]
pub struct JpegHeader {
    pub jfif: Jfif,
    // Complete segments (marker, payload) to emit right after the JFIF APP0.
    pub markers: Vec<(u8, Vec<u8>)>,
}
impl Default for JpegHeader {
    fn default() -> Self { Self { jfif: Jfif::default(), markers: vec![] } }
}

#[derive(Clone, Debug)]
pub struct Comp {
    pub id: u8, pub h: usize, pub v: usize, pub tq: usize,
}

#[derive(Clone, Debug)]
pub struct JpegInfo {
    pub width: u32,
    pub height: u32,
    pub precision: u8,
    pub components: Vec<Comp>,
    pub progressive: bool,
    pub sof_type: u8,
    pub quant: Vec<Option<[u16; 64]>>,
    pub restart_interval: usize,
    pub jfif: Option<Jfif>,
    pub markers: Vec<(u8, Vec<u8>)>,
    pub adobe_transform: Option<u8>,
    pub metadata: Metadata,
}

static PANIC_NOTE_SHOWN: AtomicBool = AtomicBool::new(false);

pub fn internal_jpeg_error(code: i32) -> CError {
    // The original library panics inside mozjpeg and converts the panic
    // payload into an error; reproduce the visible panic line on stderr.
    let thread = std::thread::current();
    let name = thread.name().unwrap_or("<unnamed>").to_string();
    let tid = current_tid();
    let backtrace = std::env::var("RUST_BACKTRACE").unwrap_or_default();
    let mut out = String::new();
    out.push_str(&format!(
        "\nthread '{}' ({}) panicked at /usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/libcaesium-0.20.0/src/jpeg.rs:315:5:\nInternal JPEG error: {}\n",
        name, tid, code
    ));
    if backtrace == "1" || backtrace.eq_ignore_ascii_case("full") {
        out.push_str("stack backtrace:\n");
        if backtrace == "1" {
            out.push_str("note: Some details are omitted, run with `RUST_BACKTRACE=full` for a verbose backtrace.\n");
        }
    } else if !PANIC_NOTE_SHOWN.swap(true, Ordering::SeqCst) {
        out.push_str("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n");
    }
    eprint!("{}", out);
    CError::new(format!("Internal JPEG error: {}", code), 20104)
}

fn current_tid() -> i64 {
    #[cfg(target_os = "linux")]
    unsafe {
        extern "C" { fn syscall(num: i64) -> i64; }
        #[cfg(target_arch = "x86_64")]
        let num = 186i64;
        #[cfg(target_arch = "aarch64")]
        let num = 178i64;
        #[cfg(not(any(target_arch = "x86_64", target_arch = "aarch64")))]
        let num = 0i64;
        if num != 0 { return syscall(num); }
    }
    std::process::id() as i64
}

fn is_sof(m: u8) -> bool {
    matches!(m, 0xC0 | 0xC1 | 0xC2 | 0xC3 | 0xC5 | 0xC6 | 0xC7 | 0xC9 | 0xCA | 0xCB | 0xCD | 0xCE | 0xCF)
}

struct MarkerSegment {
    marker: u8,
    payload: Vec<u8>,
    start: usize, // offset of 0xFF
    end: usize,   // offset just past the segment
}

fn parse_segments_until_sos(data: &[u8]) -> Result<(Vec<MarkerSegment>, Option<usize>), CError> {
    // Returns segments before the first SOS and the offset of the SOS marker.
    if data.len() < 2 || data[0] != 0xFF || data[1] != 0xD8 {
        return Err(internal_jpeg_error(25));
    }
    let mut segments = Vec::new();
    let mut pos = 2usize;
    loop {
        // Find marker prefix, skipping fill bytes.
        while pos < data.len() && data[pos] != 0xFF { return Err(internal_jpeg_error(68)); }
        let start = pos;
        while pos < data.len() && data[pos] == 0xFF { pos += 1; }
        if pos >= data.len() { return Err(internal_jpeg_error(51)); }
        let marker = data[pos];
        pos += 1;
        if marker == 0xD9 { return Ok((segments, None)); }
        if marker == 0x01 || (0xD0..=0xD8).contains(&marker) {
            continue;
        }
        if pos + 2 > data.len() { return Err(internal_jpeg_error(51)); }
        let len = u16::from_be_bytes([data[pos], data[pos + 1]]) as usize;
        if len < 2 || pos + len > data.len() { return Err(internal_jpeg_error(51)); }
        let payload = data[pos + 2..pos + len].to_vec();
        segments.push(MarkerSegment { marker, payload, start, end: pos + len });
        if marker == 0xDA {
            return Ok((segments, Some(start)));
        }
        pos += len;
    }
}

pub fn parse_jpeg_info(data: &[u8]) -> CResult<JpegInfo> {
    let (segments, _) = parse_segments_until_sos(data)?;
    let mut width = 0u32; let mut height = 0u32; let mut precision = 8u8;
    let mut components: Vec<Comp> = Vec::new();
    let mut progressive = false;
    let mut sof_type = 0u8;
    let mut quant: Vec<Option<[u16; 64]>> = vec![None; 4];
    let mut restart_interval = 0usize;
    let mut jfif: Option<Jfif> = None;
    let mut markers: Vec<(u8, Vec<u8>)> = Vec::new();
    let mut adobe_transform: Option<u8> = None;
    let mut metadata = Metadata::default();
    let mut icc_parts: Vec<(u8, Vec<u8>)> = Vec::new();

    for seg in &segments {
        match seg.marker {
            0xE0..=0xEF | 0xFE => {
                markers.push((seg.marker, seg.payload.clone()));
                if seg.marker == 0xE0 && seg.payload.starts_with(b"JFIF\0") && seg.payload.len() >= 14 {
                    jfif = Some(Jfif {
                        major: seg.payload[5], minor: seg.payload[6], units: seg.payload[7],
                        x_density: u16::from_be_bytes([seg.payload[8], seg.payload[9]]),
                        y_density: u16::from_be_bytes([seg.payload[10], seg.payload[11]]),
                    });
                }
                if seg.marker == 0xE1 && seg.payload.starts_with(b"Exif\0\0") && metadata.exif.is_none() {
                    metadata.exif = Some(seg.payload[6..].to_vec());
                }
                if seg.marker == 0xE2 && seg.payload.starts_with(b"ICC_PROFILE\0") && seg.payload.len() >= 14 {
                    icc_parts.push((seg.payload[12], seg.payload[14..].to_vec()));
                }
                if seg.marker == 0xEE && seg.payload.starts_with(b"Adobe") && seg.payload.len() >= 12 {
                    adobe_transform = Some(seg.payload[11]);
                }
            }
            0xDB => {
                let mut p = 0usize;
                while p < seg.payload.len() {
                    let pq = seg.payload[p] >> 4;
                    let tq = (seg.payload[p] & 15) as usize;
                    p += 1;
                    if tq >= quant.len() { quant.resize(tq + 1, None); }
                    let mut table = [0u16; 64];
                    for i in 0..64 {
                        if pq == 0 {
                            if p + i >= seg.payload.len() { return Err(internal_jpeg_error(51)); }
                            table[ZIGZAG[i]] = seg.payload[p + i] as u16;
                        } else {
                            let o = p + i * 2;
                            if o + 1 >= seg.payload.len() + 1 { return Err(internal_jpeg_error(51)); }
                            if o + 2 > seg.payload.len() { return Err(internal_jpeg_error(51)); }
                            table[ZIGZAG[i]] = u16::from_be_bytes([seg.payload[o], seg.payload[o + 1]]);
                        }
                    }
                    quant[tq] = Some(table);
                    p += if pq == 0 { 64 } else { 128 };
                }
            }
            0xDD => {
                if seg.payload.len() >= 2 {
                    restart_interval = u16::from_be_bytes([seg.payload[0], seg.payload[1]]) as usize;
                }
            }
            m if is_sof(m) => {
                sof_type = m;
                progressive = m == 0xC2 || m == 0xCA;
                if seg.payload.len() < 6 { return Err(internal_jpeg_error(51)); }
                precision = seg.payload[0];
                height = u16::from_be_bytes([seg.payload[1], seg.payload[2]]) as u32;
                width = u16::from_be_bytes([seg.payload[3], seg.payload[4]]) as u32;
                let n = seg.payload[5] as usize;
                components.clear();
                for i in 0..n {
                    let o = 6 + i * 3;
                    if o + 2 >= seg.payload.len() + 1 || o + 3 > seg.payload.len() { return Err(internal_jpeg_error(51)); }
                    components.push(Comp {
                        id: seg.payload[o],
                        h: (seg.payload[o + 1] >> 4) as usize,
                        v: (seg.payload[o + 1] & 15) as usize,
                        tq: seg.payload[o + 2] as usize,
                    });
                }
            }
            _ => {}
        }
    }
    if !icc_parts.is_empty() {
        icc_parts.sort_by_key(|(seq, _)| *seq);
        let mut profile = Vec::new();
        for (_, part) in &icc_parts { profile.extend_from_slice(part); }
        metadata.icc = Some(profile);
    }
    if let Some(exif) = &metadata.exif { metadata.orientation = exif_orientation(exif); }
    if width == 0 || components.is_empty() {
        // Height may legitimately be defined by a later DNL marker; treat a
        // zero width or missing frame header as the usual internal error.
        if width == 0 { return Err(internal_jpeg_error(51)); }
    }
    Ok(JpegInfo { width, height, precision, components, progressive, sof_type, quant, restart_interval, jfif, markers, adobe_transform, metadata })
}

pub fn jpeg_dimensions(data: &[u8]) -> Option<(u32, u32)> {
    // Lightweight SOF scan without error reporting.
    if data.len() < 4 || data[0] != 0xFF || data[1] != 0xD8 { return None; }
    let mut pos = 2usize;
    while pos + 4 <= data.len() {
        if data[pos] != 0xFF { return None; }
        let marker = data[pos + 1];
        if marker == 0xDA || marker == 0xD9 { return None; }
        if marker == 0x01 || (0xD0..=0xD8).contains(&marker) { pos += 2; continue; }
        let len = u16::from_be_bytes([data[pos+2], data[pos+3]]) as usize;
        if len < 2 || pos + 2 + len > data.len() { return None; }
        if is_sof(marker) && len >= 7 {
            let h = u16::from_be_bytes([data[pos+5], data[pos+6]]) as u32;
            let w = u16::from_be_bytes([data[pos+7], data[pos+8]]) as u32;
            return Some((w, h));
        }
        pos += 2 + len;
    }
    None
}

// ---------- coefficient decoding ----------
#[derive(Clone)]
struct HuffTable {
    // Map (code length, code) -> symbol, plus a fast length-indexed lookup.
    map: HashMap<(u8, u16), u8>,
    min_code: [i32; 17],
    max_code: [i32; 17],
    val_ptr: [usize; 17],
    symbols: Vec<u8>,
}
impl HuffTable {
    fn build(bits: &[u8; 16], symbols: &[u8]) -> Option<Self> {
        let mut map = HashMap::new();
        let mut code: u32 = 0;
        let mut idx = 0usize;
        let mut min_code = [0i32; 17];
        let mut max_code = [-1i32; 17];
        let mut val_ptr = [0usize; 17];
        for len in 1..=16usize {
            if bits[len - 1] > 0 {
                val_ptr[len] = idx;
                min_code[len] = code as i32;
                for _ in 0..bits[len - 1] {
                    if idx >= symbols.len() { return None; }
                    map.insert((len as u8, code as u16), symbols[idx]);
                    idx += 1;
                    code += 1;
                }
                max_code[len] = (code - 1) as i32;
            }
            code <<= 1;
        }
        Some(Self { map, min_code, max_code, val_ptr, symbols: symbols.to_vec() })
    }
    fn decode(&self, br: &mut BitReader) -> Option<u8> {
        let mut code: i32 = br.get_bit()? as i32;
        let mut len = 1usize;
        loop {
            if code <= self.max_code[len] && self.max_code[len] >= 0 && code >= self.min_code[len] {
                let idx = self.val_ptr[len] + (code - self.min_code[len]) as usize;
                return self.symbols.get(idx).copied();
            }
            if let Some(sym) = self.map.get(&(len as u8, code as u16)) { return Some(*sym); }
            len += 1;
            if len > 16 { return None; }
            code = (code << 1) | br.get_bit()? as i32;
        }
    }
}

struct BitReader<'a> {
    data: &'a [u8],
    // Byte offsets (into `data`) at which restart markers occur.
    restarts: Vec<usize>,
    restart_idx: usize,
    byte_pos: usize,
    bit_pos: u32, // number of bits already consumed in current byte (MSB first)
    cur: u8,
    empty: bool,
}
impl<'a> BitReader<'a> {
    fn new(data: &'a [u8], restarts: Vec<usize>) -> Self {
        Self { data, restarts, restart_idx: 0, byte_pos: 0, bit_pos: 8, cur: 0, empty: false }
    }
    fn get_bit(&mut self) -> Option<u32> {
        if self.bit_pos >= 8 {
            if self.byte_pos >= self.data.len() {
                // JPEG decoders pad with 1-bits at the end of the stream.
                self.empty = true;
                return Some(1);
            }
            self.cur = self.data[self.byte_pos];
            self.byte_pos += 1;
            self.bit_pos = 0;
        }
        let bit = ((self.cur >> (7 - self.bit_pos)) & 1) as u32;
        self.bit_pos += 1;
        Some(bit)
    }
    fn get_bits(&mut self, n: u32) -> Option<u32> {
        let mut v = 0u32;
        for _ in 0..n { v = (v << 1) | self.get_bit()?; }
        Some(v)
    }
    fn receive_extend(&mut self, n: u32) -> Option<i32> {
        if n == 0 { return Some(0); }
        let v = self.get_bits(n)? as i32;
        let threshold = 1i32 << (n - 1);
        if v < threshold { Some(v - ((1i32 << n) - 1)) } else { Some(v) }
    }
    fn restart(&mut self) {
        self.bit_pos = 8;
        if self.restart_idx < self.restarts.len() {
            self.byte_pos = self.restarts[self.restart_idx];
            self.restart_idx += 1;
        }
    }
}

/// Split an entropy-coded segment into destuffed data plus restart offsets,
/// returning the offset of the following marker.
fn extract_entropy(data: &[u8], start: usize) -> (Vec<u8>, Vec<usize>, usize) {
    let mut out: Vec<u8> = Vec::new();
    let mut restarts: Vec<usize> = Vec::new();
    let mut i = start;
    while i < data.len() {
        if data[i] == 0xFF {
            if i + 1 >= data.len() { break; }
            let nxt = data[i + 1];
            if nxt == 0x00 {
                out.push(0xFF);
                i += 2;
            } else if nxt == 0xFF {
                i += 1; // fill byte
            } else if (0xD0..=0xD7).contains(&nxt) {
                restarts.push(out.len());
                i += 2;
            } else {
                break;
            }
        } else {
            out.push(data[i]);
            i += 1;
        }
    }
    (out, restarts, i)
}

pub struct CoeffImage {
    pub info: JpegInfo,
    // blocks[component][block index] in raster order within the component.
    pub blocks: Vec<Vec<[i16; 64]>>,
    pub comp_block_dims: Vec<(usize, usize)>, // (blocks wide, blocks high)
}

impl CoeffImage {
    fn max_hv(&self) -> (usize, usize) {
        self.info.components.iter().fold((1, 1), |(mh, mv), c| (mh.max(c.h), mv.max(c.v)))
    }
}

pub fn decode_jpeg_coefficients(data: &[u8]) -> CResult<CoeffImage> {
    let info = parse_jpeg_info(data)?;
    if info.precision != 8 {
        return Err(internal_jpeg_error(38));
    }
    if !(matches!(info.sof_type, 0xC0 | 0xC1 | 0xC2)) {
        return Err(internal_jpeg_error(25));
    }
    let (max_h, max_v) = info.components.iter().fold((1usize, 1usize), |(mh, mv), c| (mh.max(c.h), mv.max(c.v)));
    let mut comp_block_dims: Vec<(usize, usize)> = Vec::new();
    let mut blocks: Vec<Vec<[i16; 64]>> = Vec::new();
    for c in &info.components {
        let cw = (((info.width as usize) * c.h + max_h - 1) / max_h + 7) / 8;
        let ch = (((info.height as usize) * c.v + max_v - 1) / max_v + 7) / 8;
        comp_block_dims.push((cw, ch));
        blocks.push(vec![[0i16; 64]; cw * ch]);
    }

    // Walk markers again, tracking Huffman tables and decoding each scan.
    let mut dc_tables: Vec<Option<HuffTable>> = vec![None, None, None, None];
    let mut ac_tables: Vec<Option<HuffTable>> = vec![None, None, None, None];
    let mut pos = 2usize;
    let mcus_x = ((info.width as usize) + max_h * 8 - 1) / (max_h * 8);
    let mcus_y = ((info.height as usize) + max_v * 8 - 1) / (max_v * 8);

    loop {
        if pos + 1 >= data.len() { return Err(internal_jpeg_error(51)); }
        if data[pos] != 0xFF { return Err(internal_jpeg_error(68)); }
        let mut mpos = pos;
        while mpos < data.len() && data[mpos] == 0xFF { mpos += 1; }
        if mpos >= data.len() { return Err(internal_jpeg_error(51)); }
        let marker = data[mpos];
        pos = mpos + 1;
        if marker == 0xD9 { break; }
        if marker == 0x01 || (0xD0..=0xD8).contains(&marker) { continue; }
        if pos + 2 > data.len() { return Err(internal_jpeg_error(51)); }
        let len = u16::from_be_bytes([data[pos], data[pos + 1]]) as usize;
        if len < 2 || pos + len > data.len() { return Err(internal_jpeg_error(51)); }
        let payload = &data[pos + 2..pos + len];
        match marker {
            0xC4 => {
                let mut p = 0usize;
                while p + 17 <= payload.len() {
                    let cls = payload[p] >> 4;
                    let id = (payload[p] & 15) as usize;
                    let mut bits = [0u8; 16];
                    bits.copy_from_slice(&payload[p + 1..p + 17]);
                    let count: usize = bits.iter().map(|b| *b as usize).sum();
                    if p + 17 + count > payload.len() { return Err(internal_jpeg_error(51)); }
                    let symbols = &payload[p + 17..p + 17 + count];
                    let tbl = HuffTable::build(&bits, symbols).ok_or_else(|| internal_jpeg_error(51))?;
                    if id >= 4 { dc_tables.resize_with(id + 1, || None); ac_tables.resize_with(id + 1, || None); }
                    if cls == 0 { dc_tables[id] = Some(tbl); } else { ac_tables[id] = Some(tbl); }
                    p += 17 + count;
                }
                pos += len;
            }
            0xDA => {
                // Start of scan.
                if payload.is_empty() { return Err(internal_jpeg_error(51)); }
                let ns = payload[0] as usize;
                if payload.len() < 1 + ns * 2 + 3 { return Err(internal_jpeg_error(51)); }
                let mut scan_comps: Vec<(usize, usize, usize)> = Vec::new(); // (comp idx, dc tbl, ac tbl)
                for i in 0..ns {
                    let sel = payload[1 + i * 2];
                    let td = (payload[2 + i * 2] >> 4) as usize;
                    let ta = (payload[2 + i * 2] & 15) as usize;
                    let cidx = info.components.iter().position(|c| c.id == sel).ok_or_else(|| internal_jpeg_error(51))?;
                    scan_comps.push((cidx, td, ta));
                }
                let ss = payload[1 + ns * 2] as usize;
                let se = payload[2 + ns * 2] as usize;
                let ah = (payload[3 + ns * 2] >> 4) as u32;
                let al = (payload[3 + ns * 2] & 15) as u32;
                let entropy_start = pos + len;
                let (entropy, restarts, next_pos) = extract_entropy(data, entropy_start);
                let mut br = BitReader::new(&entropy, restarts);
                let mut dc_pred = vec![0i32; info.components.len()];
                let mut eobrun: usize = 0;
                let restart_interval = {
                    // Re-read any DRI seen so far (parse_jpeg_info already has the last one
                    // before the first SOS; DRI between scans is handled here too).
                    info.restart_interval
                };
                let _ = restart_interval;
                // Decode block-by-block in MCU order.
                let total_mcus = if ns == 1 {
                    let (bw, bh) = comp_block_dims[scan_comps[0].0];
                    bw * bh
                } else { mcus_x * mcus_y };
                let mut mcu_count = 0usize;
                let mut decode_one_block = |br: &mut BitReader, cidx: usize, block_idx: usize, dc_pred: &mut Vec<i32>, eobrun: &mut usize, blocks: &mut Vec<Vec<[i16;64]>>, dc_tables: &Vec<Option<HuffTable>>, ac_tables: &Vec<Option<HuffTable>>, td: usize, ta: usize| -> CResult<()> {
                    let dc_tbl = dc_tables.get(td).and_then(|t| t.as_ref()).ok_or_else(|| internal_jpeg_error(51))?;
                    let ac_tbl = ac_tables.get(ta).and_then(|t| t.as_ref());
                    decode_block(br, &mut blocks[cidx][block_idx], dc_tbl, ac_tbl, &mut dc_pred[cidx], ss, se, ah, al, eobrun, info.progressive)
                };
                if ns == 1 {
                    let (cidx, td, ta) = scan_comps[0];
                    let (bw, bh) = comp_block_dims[cidx];
                    for by in 0..bh {
                        for bx in 0..bw {
                            if restart_interval > 0 && mcu_count > 0 && mcu_count % restart_interval == 0 {
                                br.restart();
                                for p in dc_pred.iter_mut() { *p = 0; }
                                eobrun = 0;
                            }
                            decode_one_block(&mut br, cidx, by * bw + bx, &mut dc_pred, &mut eobrun, &mut blocks, &dc_tables, &ac_tables, td, ta)?;
                            mcu_count += 1;
                        }
                    }
                } else {
                    for my in 0..mcus_y {
                        for mx in 0..mcus_x {
                            if restart_interval > 0 && mcu_count > 0 && mcu_count % restart_interval == 0 {
                                br.restart();
                                for p in dc_pred.iter_mut() { *p = 0; }
                                eobrun = 0;
                            }
                            for (cidx, td, ta) in &scan_comps {
                                let comp = &info.components[*cidx];
                                let (bw, _) = comp_block_dims[*cidx];
                                for by in 0..comp.v {
                                    for bx in 0..comp.h {
                                        let block_x = mx * comp.h + bx;
                                        let block_y = my * comp.v + by;
                                        let (tbw, tbh) = comp_block_dims[*cidx];
                                        if block_x < tbw && block_y < tbh {
                                            decode_one_block(&mut br, *cidx, block_y * bw + block_x, &mut dc_pred, &mut eobrun, &mut blocks, &dc_tables, &ac_tables, *td, *ta)?;
                                        } else {
                                            // Edge MCU block beyond the component:
                                            // still present in the stream.
                                            let mut dummy = [0i16; 64];
                                            let dc_tbl = dc_tables.get(*td).and_then(|t| t.as_ref()).ok_or_else(|| internal_jpeg_error(51))?;
                                            let ac_tbl = ac_tables.get(*ta).and_then(|t| t.as_ref());
                                            decode_block(&mut br, &mut dummy, dc_tbl, ac_tbl, &mut dc_pred[*cidx], ss, se, ah, al, &mut eobrun, info.progressive)?;
                                        }
                                    }
                                }
                            }
                            mcu_count += 1;
                        }
                    }
                }
                let _ = total_mcus;
                let _ = mcu_count;
                pos = next_pos;
            }
            0xDD => {
                // Restart interval updates between scans are ignored here
                // (the value from the header parse is used); this matches
                // files that only carry a single DRI before the first scan.
                pos += len;
            }
            _ => { pos += len; }
        }
    }

    Ok(CoeffImage { info, blocks, comp_block_dims })
}

#[allow(clippy::too_many_arguments)]
fn decode_block(
    br: &mut BitReader,
    block: &mut [i16; 64],
    dc_tbl: &HuffTable,
    ac_tbl: Option<&HuffTable>,
    dc_pred: &mut i32,
    ss: usize,
    se: usize,
    ah: u32,
    al: u32,
    eobrun: &mut usize,
    progressive: bool,
) -> CResult<()> {
    let bit = 1i32 << al;
    if !progressive {
        // Sequential DCT: DC then all 63 AC coefficients.
        let cat = dc_tbl.decode(br).ok_or_else(|| internal_jpeg_error(51))? as u32;
        let diff = br.receive_extend(cat).ok_or_else(|| internal_jpeg_error(51))?;
        *dc_pred += diff;
        block[0] = (*dc_pred) as i16;
        let ac = ac_tbl.ok_or_else(|| internal_jpeg_error(51))?;
        let mut k = 1usize;
        while k < 64 {
            let rs = ac.decode(br).ok_or_else(|| internal_jpeg_error(51))?;
            let r = (rs >> 4) as usize;
            let s = (rs & 15) as u32;
            if s == 0 {
                if r < 15 { break; }
                k += 16;
            } else {
                k += r;
                if k >= 64 { break; }
                let v = br.receive_extend(s).ok_or_else(|| internal_jpeg_error(51))?;
                block[ZIGZAG[k]] = v as i16;
                k += 1;
            }
        }
        return Ok(());
    }
    // Progressive.
    if ss == 0 {
        // DC scan.
        if ah == 0 {
            let cat = dc_tbl.decode(br).ok_or_else(|| internal_jpeg_error(51))? as u32;
            let diff = br.receive_extend(cat).ok_or_else(|| internal_jpeg_error(51))?;
            *dc_pred += diff << al;
            block[0] = (*dc_pred) as i16;
        } else {
            let b = br.get_bit().ok_or_else(|| internal_jpeg_error(51))?;
            if b == 1 {
                *dc_pred |= bit;
                block[0] = (*dc_pred) as i16;
            }
        }
        return Ok(());
    }
    let ac = ac_tbl.ok_or_else(|| internal_jpeg_error(51))?;
    if ah == 0 {
        // First AC scan for this band.
        if *eobrun > 0 {
            *eobrun -= 1;
            return Ok(());
        }
        let mut k = ss;
        while k <= se {
            let rs = ac.decode(br).ok_or_else(|| internal_jpeg_error(51))?;
            let r = (rs >> 4) as usize;
            let s = (rs & 15) as u32;
            if s == 0 {
                if r < 15 {
                    let mut run = 1usize << r;
                    if r > 0 { run += br.get_bits(r as u32).ok_or_else(|| internal_jpeg_error(51))? as usize; }
                    *eobrun = run - 1;
                    break;
                }
                k += 16;
            } else {
                if s != 1 { return Err(internal_jpeg_error(51)); }
                let sign = br.get_bit().ok_or_else(|| internal_jpeg_error(51))?;
                k += r;
                if k > se { break; }
                block[ZIGZAG[k]] = (if sign == 1 { bit } else { -bit }) as i16;
                k += 1;
            }
        }
        Ok(())
    } else {
        // Refinement scan.
        let refine = |br: &mut BitReader, coef: &mut i16| -> CResult<()> {
            if *coef != 0 {
                let b = br.get_bit().ok_or_else(|| internal_jpeg_error(51))?;
                if b == 1 && (*coef as i32 & bit) == 0 {
                    *coef = (*coef as i32 + if *coef > 0 { bit } else { -bit }) as i16;
                }
            }
            Ok(())
        };
        if *eobrun > 0 {
            for k in ss..=se {
                let idx = ZIGZAG[k];
                let mut c = block[idx];
                refine(br, &mut c)?;
                block[idx] = c;
            }
            *eobrun -= 1;
            return Ok(());
        }
        let mut k = ss;
        while k <= se {
            let rs = ac.decode(br).ok_or_else(|| internal_jpeg_error(51))?;
            let r = (rs >> 4) as usize;
            let s = (rs & 15) as u32;
            if s == 0 {
                if r < 15 {
                    let mut run = 1usize << r;
                    if r > 0 { run += br.get_bits(r as u32).ok_or_else(|| internal_jpeg_error(51))? as usize; }
                    // Refine remaining nonzero coefficients in this block.
                    while k <= se {
                        let idx = ZIGZAG[k];
                        let mut c = block[idx];
                        refine(br, &mut c)?;
                        block[idx] = c;
                        k += 1;
                    }
                    *eobrun = run - 1;
                    return Ok(());
                }
                // ZRL: skip 16 zero coefficients, refining nonzeros.
                let mut to_skip = 16usize;
                while k <= se && to_skip > 0 {
                    let idx = ZIGZAG[k];
                    if block[idx] != 0 {
                        let mut c = block[idx];
                        refine(br, &mut c)?;
                        block[idx] = c;
                    } else {
                        to_skip -= 1;
                    }
                    k += 1;
                }
            } else if s == 1 {
                let signbit = br.get_bit().ok_or_else(|| internal_jpeg_error(51))?;
                let newcoef = if signbit == 1 { bit } else { -bit };
                let mut to_skip = r;
                while k <= se {
                    let idx = ZIGZAG[k];
                    if block[idx] != 0 {
                        let mut c = block[idx];
                        refine(br, &mut c)?;
                        block[idx] = c;
                    } else if to_skip == 0 {
                        block[idx] = newcoef as i16;
                        k += 1;
                        break;
                    } else {
                        to_skip -= 1;
                    }
                    k += 1;
                }
            } else {
                return Err(internal_jpeg_error(51));
            }
        }
        Ok(())
    }
}

// ---------- pixel reconstruction ----------
fn idct_block(input: &[f64; 64]) -> [f64; 64] {
    // Direct separable inverse DCT.
    let mut tmp = [0f64; 64];
    let mut out = [0f64; 64];
    // Rows (inverse transform across x for each frequency row).
    for y in 0..8 {
        for x in 0..8 {
            let mut sum = 0.0;
            for u in 0..8 {
                let cu = if u == 0 { std::f64::consts::FRAC_1_SQRT_2 } else { 1.0 };
                sum += cu * input[y * 8 + u] * (((2 * x + 1) as f64 * u as f64 * std::f64::consts::PI) / 16.0).cos();
            }
            tmp[y * 8 + x] = sum * 0.5;
        }
    }
    for x in 0..8 {
        for y in 0..8 {
            let mut sum = 0.0;
            for v in 0..8 {
                let cv = if v == 0 { std::f64::consts::FRAC_1_SQRT_2 } else { 1.0 };
                sum += cv * tmp[v * 8 + x] * (((2 * y + 1) as f64 * v as f64 * std::f64::consts::PI) / 16.0).cos();
            }
            out[y * 8 + x] = sum * 0.5;
        }
    }
    out
}

impl CoeffImage {
    pub fn to_raster(&self) -> Raster {
        let info = &self.info;
        let (max_h, max_v) = self.max_hv();
        // Build full-resolution planes per component.
        let mut planes: Vec<Vec<u8>> = Vec::new();
        for (ci, comp) in info.components.iter().enumerate() {
            let (bw, bh) = self.comp_block_dims[ci];
            let pw = bw * 8;
            let ph = bh * 8;
            let mut plane = vec![0u8; pw * ph];
            let qt = info.quant.get(comp.tq).and_then(|t| *t).unwrap_or([1u16; 64]);
            for by in 0..bh {
                for bx in 0..bw {
                    let block = &self.blocks[ci][by * bw + bx];
                    let mut deq = [0f64; 64];
                    for i in 0..64 { deq[i] = block[i] as f64 * qt[i] as f64; }
                    let px = idct_block(&deq);
                    for yy in 0..8 {
                        for xx in 0..8 {
                            let v = (px[yy * 8 + xx] + 128.0).round().clamp(0.0, 255.0) as u8;
                            plane[(by * 8 + yy) * pw + (bx * 8 + xx)] = v;
                        }
                    }
                }
            }
            // Upsample to full resolution (fancy 3/4-1/4 for a factor of 2).
            let cw = ((info.width as usize) * comp.h + max_h - 1) / max_h;
            let ch = ((info.height as usize) * comp.v + max_v - 1) / max_v;
            let up = upsample_plane(&plane, pw, cw, ch, info.width as usize, info.height as usize);
            planes.push(up);
        }
        let w = info.width as usize;
        let h = info.height as usize;
        match info.components.len() {
            1 => Raster::new(info.width, info.height, ColorKind::L8, planes.into_iter().next().unwrap_or_default()),
            3 => {
                let is_rgb = info.adobe_transform == Some(0)
                    || (info.components[0].id == b'R' && info.components[1].id == b'G' && info.components[2].id == b'B');
                let mut data = vec![0u8; w * h * 3];
                for i in 0..w * h {
                    if is_rgb {
                        data[i*3] = planes[0][i]; data[i*3+1] = planes[1][i]; data[i*3+2] = planes[2][i];
                    } else {
                        let (r, g, b) = ycbcr_to_rgb(planes[0][i], planes[1][i], planes[2][i]);
                        data[i*3] = r; data[i*3+1] = g; data[i*3+2] = b;
                    }
                }
                Raster::new(info.width, info.height, ColorKind::Rgb8, data)
            }
            4 => {
                let mut data = vec![0u8; w * h * 3];
                let ycck = info.adobe_transform == Some(2);
                for i in 0..w * h {
                    let (r, g, b) = if ycck {
                        ycbcr_to_rgb(planes[0][i], planes[1][i], planes[2][i])
                    } else {
                        // Adobe CMYK samples are inverted.
                        (planes[0][i], planes[1][i], planes[2][i])
                    };
                    let k = planes[3][i] as u32;
                    if ycck {
                        data[i*3] = ((r as u32 * k) / 255) as u8;
                        data[i*3+1] = ((g as u32 * k) / 255) as u8;
                        data[i*3+2] = ((b as u32 * k) / 255) as u8;
                    } else {
                        // Inverted CMYK: stored values are 255-C etc., so
                        // the sample itself acts like a K-multiplied channel.
                        data[i*3] = ((r as u32 * k) / 255) as u8;
                        data[i*3+1] = ((g as u32 * k) / 255) as u8;
                        data[i*3+2] = ((b as u32 * k) / 255) as u8;
                    }
                }
                Raster::new(info.width, info.height, ColorKind::Rgb8, data)
            }
            _ => Raster::new(info.width, info.height, ColorKind::Rgb8, vec![0; w * h * 3]),
        }
    }
}

fn upsample_plane(plane: &[u8], plane_w: usize, cw: usize, ch: usize, out_w: usize, out_h: usize) -> Vec<u8> {
    // `plane` is padded to a multiple of 8; only cw x ch samples are real.
    let sample = |x: i32, y: i32| -> u8 {
        let x = x.clamp(0, cw as i32 - 1) as usize;
        let y = y.clamp(0, ch as i32 - 1) as usize;
        plane[y * plane_w + x]
    };
    let mut out = vec![0u8; out_w * out_h];
    if cw == 0 || ch == 0 { return out; }
    let h_factor2 = out_w >= cw * 2 && (out_w + 1) / 2 == cw || (cw * 2 == out_w) || (cw * 2 - 1 == out_w);
    let v_factor2 = ch * 2 == out_h || ch * 2 - 1 == out_h;
    for y in 0..out_h {
        for x in 0..out_w {
            let v = if cw == out_w && ch == out_h {
                sample(x as i32, y as i32)
            } else if h_factor2 && v_factor2 {
                // Bilinear with 3/4-1/4 weights in both directions.
                let sx = (x as f32 + 0.5) / 2.0 - 0.5;
                let sy = (y as f32 + 0.5) / 2.0 - 0.5;
                bilinear(&sample, sx, sy)
            } else if h_factor2 {
                let sx = (x as f32 + 0.5) / 2.0 - 0.5;
                let sy = ((y as f32 * ch as f32) / out_h as f32).floor();
                bilinear(&sample, sx, sy)
            } else if v_factor2 {
                let sx = ((x as f32 * cw as f32) / out_w as f32).floor();
                let sy = (y as f32 + 0.5) / 2.0 - 0.5;
                bilinear(&sample, sx, sy)
            } else {
                sample(((x * cw) / out_w.max(1)) as i32, ((y * ch) / out_h.max(1)) as i32)
            };
            out[y * out_w + x] = v;
        }
    }
    out
}

fn bilinear<F: Fn(i32, i32) -> u8>(sample: &F, sx: f32, sy: f32) -> u8 {
    let x0 = sx.floor() as i32;
    let y0 = sy.floor() as i32;
    let fx = sx - x0 as f32;
    let fy = sy - y0 as f32;
    let top = sample(x0, y0) as f32 * (1.0 - fx) + sample(x0 + 1, y0) as f32 * fx;
    let bot = sample(x0, y0 + 1) as f32 * (1.0 - fx) + sample(x0 + 1, y0 + 1) as f32 * fx;
    (top * (1.0 - fy) + bot * fy).round().clamp(0.0, 255.0) as u8
}

fn ycbcr_to_rgb(y: u8, cb: u8, cr: u8) -> (u8, u8, u8) {
    let y = y as f32;
    let cb = cb as f32 - 128.0;
    let cr = cr as f32 - 128.0;
    let r = (y + 1.402 * cr).round().clamp(0.0, 255.0) as u8;
    let g = (y - 0.344136 * cb - 0.714136 * cr).round().clamp(0.0, 255.0) as u8;
    let b = (y + 1.772 * cb).round().clamp(0.0, 255.0) as u8;
    (r, g, b)
}

pub fn decode_jpeg(data: &[u8]) -> CResult<(Raster, Metadata)> {
    let coeffs = decode_jpeg_coefficients(data)?;
    let metadata = coeffs.info.metadata.clone();
    Ok((coeffs.to_raster(), metadata))
}

// ---------- encoding ----------
fn fdct_quantize(samples: &[u8; 64], qt: &[u16; 64]) -> [i16; 64] {
    // Forward DCT (separable, floating point) on level-shifted samples.
    let mut tmp = [0f64; 64];
    let mut out = [0f64; 64];
    for y in 0..8 {
        for u in 0..8 {
            let mut sum = 0.0;
            for x in 0..8 {
                sum += (samples[y * 8 + x] as f64 - 128.0) * (((2 * x + 1) as f64 * u as f64 * std::f64::consts::PI) / 16.0).cos();
            }
            let cu = if u == 0 { std::f64::consts::FRAC_1_SQRT_2 } else { 1.0 };
            tmp[y * 8 + u] = sum * 0.5 * cu;
        }
    }
    for u in 0..8 {
        for v in 0..8 {
            let mut sum = 0.0;
            for y in 0..8 {
                sum += tmp[y * 8 + u] * (((2 * y + 1) as f64 * v as f64 * std::f64::consts::PI) / 16.0).cos();
            }
            let cv = if v == 0 { std::f64::consts::FRAC_1_SQRT_2 } else { 1.0 };
            out[v * 8 + u] = sum * 0.5 * cv;
        }
    }
    let mut coeffs = [0i16; 64];
    for i in 0..64 {
        let q = qt[i] as f64;
        let v = out[i] / q;
        coeffs[i] = if v >= 0.0 { (v + 0.5).floor() as i16 } else { (v - 0.5).ceil() as i16 };
    }
    coeffs
}

struct EncodedCoeffImage {
    width: u32,
    height: u32,
    components: Vec<Comp>,
    blocks: Vec<Vec<[i16; 64]>>,
    comp_block_dims: Vec<(usize, usize)>,
    quant: Vec<[u16; 64]>,
    quant_ids: Vec<usize>, // index into quant for each emitted table slot 0/1
}

fn rgb_to_ycbcr(r: u8, g: u8, b: u8) -> (u8, u8, u8) {
    let (r, g, b) = (r as f32, g as f32, b as f32);
    let y = (0.299 * r + 0.587 * g + 0.114 * b).round().clamp(0.0, 255.0) as u8;
    let cb = (-0.168736 * r - 0.331264 * g + 0.5 * b + 128.0).round().clamp(0.0, 255.0) as u8;
    let cr = (0.5 * r - 0.418688 * g - 0.081312 * b + 128.0).round().clamp(0.0, 255.0) as u8;
    (y, cb, cr)
}

fn build_coeff_image(raster: &Raster, sampling: (usize, usize), tables: &[[u16;64]; 2]) -> EncodedCoeffImage {
    // sampling = (h, v) of the luma component relative to chroma at 1x1.
    let rgba = raster.rgba8();
    let w = raster.width as usize;
    let h = raster.height as usize;
    let is_gray_kind = matches!(raster.kind, ColorKind::L8 | ColorKind::La8 | ColorKind::L16 | ColorKind::La16);
    let (components, planes): (Vec<Comp>, Vec<Vec<u8>>) = if is_gray_kind {
        let mut yplane = vec![0u8; w * h];
        for i in 0..w * h { yplane[i] = rgba[i * 4]; }
        (vec![Comp { id: 1, h: 1, v: 1, tq: 0 }], vec![yplane])
    } else {
        let (sh, sv) = sampling;
        // Full-resolution Y/Cb/Cr first.
        let mut yfull = vec![0u8; w * h];
        let mut cbfull = vec![0u8; w * h];
        let mut crfull = vec![0u8; w * h];
        for i in 0..w * h {
            let (y, cb, cr) = rgb_to_ycbcr(rgba[i*4], rgba[i*4+1], rgba[i*4+2]);
            yfull[i] = y; cbfull[i] = cb; crfull[i] = cr;
        }
        let downsample = |plane: &[u8]| -> Vec<u8> {
            let cw = (w + sh - 1) / sh;
            let chh = (h + sv - 1) / sv;
            let mut out = vec![0u8; cw * chh];
            for dy in 0..chh {
                for dx in 0..cw {
                    let mut sum = 0u32;
                    let mut cnt = 0u32;
                    for yy in 0..sv {
                        for xx in 0..sh {
                            let sx = (dx * sh + xx).min(w - 1);
                            let sy = (dy * sv + yy).min(h - 1);
                            sum += plane[sy * w + sx] as u32;
                            cnt += 1;
                        }
                    }
                    out[dy * cw + dx] = ((sum + cnt / 2) / cnt.max(1)) as u8;
                }
            }
            out
        };
        (
            vec![
                Comp { id: 1, h: sh, v: sv, tq: 0 },
                Comp { id: 2, h: 1, v: 1, tq: 1 },
                Comp { id: 3, h: 1, v: 1, tq: 1 },
            ],
            vec![yfull, downsample(&cbfull), downsample(&crfull)],
        )
    };
    let max_h = components.iter().map(|c| c.h).max().unwrap_or(1);
    let max_v = components.iter().map(|c| c.v).max().unwrap_or(1);
    let mut blocks: Vec<Vec<[i16;64]>> = Vec::new();
    let mut comp_block_dims = Vec::new();
    for (ci, comp) in components.iter().enumerate() {
        let cw = ((w * comp.h + max_h - 1) / max_h + 7) / 8 * 8;
        let chh = ((h * comp.v + max_v - 1) / max_v + 7) / 8 * 8;
        let pw = if ci == 0 { w } else { (w + sampling.0 - 1) / sampling.0 };
        let _ = pw;
        let plane_w = if ci == 0 || components.len() == 1 { w } else { (w + sampling.0 - 1) / sampling.0 };
        let plane_h = if ci == 0 || components.len() == 1 { h } else { (h + sampling.1 - 1) / sampling.1 };
        let bw = cw / 8;
        let bh = chh / 8;
        comp_block_dims.push((bw, bh));
        let qt = &tables[comp.tq.min(1)];
        let mut comp_blocks = Vec::with_capacity(bw * bh);
        for by in 0..bh {
            for bx in 0..bw {
                let mut samples = [0u8; 64];
                for yy in 0..8 {
                    for xx in 0..8 {
                        let sx = (bx * 8 + xx).min(plane_w.saturating_sub(1));
                        let sy = (by * 8 + yy).min(plane_h.saturating_sub(1));
                        samples[yy * 8 + xx] = planes[ci].get(sy * plane_w + sx).copied().unwrap_or(128);
                    }
                }
                comp_blocks.push(fdct_quantize(&samples, qt));
            }
        }
        blocks.push(comp_blocks);
    }
    EncodedCoeffImage {
        width: raster.width, height: raster.height,
        components, blocks, comp_block_dims,
        quant: tables.to_vec(), quant_ids: vec![0, 1],
    }
}

// Optimal Huffman table generation (libjpeg-style).
fn gen_optimal_table(freq_in: &[u32; 257]) -> ([u8;16], Vec<u8>) {
    let mut freq = *freq_in;
    freq[256] = 1; // reserve the all-ones code
    let mut codesize = [0u32; 257];
    let mut others = [-1i32; 257];
    loop {
        // Find the two smallest nonzero frequencies.
        let mut c1: i32 = -1;
        let mut c2: i32 = -1;
        let mut v = u32::MAX;
        for i in 0..257 {
            if freq[i] > 0 && freq[i] <= v { v = freq[i]; c1 = i as i32; }
        }
        if c1 < 0 { break; }
        let mut v2 = u32::MAX;
        for i in 0..257 {
            if freq[i] > 0 && freq[i] <= v2 && i as i32 != c1 { v2 = freq[i]; c2 = i as i32; }
        }
        if c2 < 0 { break; }
        freq[c1 as usize] += freq[c2 as usize];
        freq[c2 as usize] = 0;
        codesize[c1 as usize] += 1;
        let mut node = c1;
        while others[node as usize] >= 0 {
            node = others[node as usize];
            codesize[node as usize] += 1;
        }
        others[node as usize] = c2;
        codesize[c2 as usize] += 1;
        let mut node2 = c2;
        while others[node2 as usize] >= 0 {
            node2 = others[node2 as usize];
            codesize[node2 as usize] += 1;
        }
    }
    let mut bits = [0u8; 17];
    for i in 0..257 {
        if codesize[i] > 0 {
            if codesize[i] > 16 {
                bits[17 - 1] += 0; // handled below
            }
            let l = codesize[i].min(16) as usize;
            bits[l] = bits[l].saturating_add(1);
        }
    }
    // Adjust for codes longer than 16 bits (JPEG Annex K procedure).
    let mut overflow_count: i32 = 0;
    {
        let mut count_long = 0i32;
        for i in 0..257 { if codesize[i] > 16 { count_long += 1; } }
        overflow_count = count_long;
    }
    if overflow_count > 0 {
        // Recompute bits with the standard adjustment.
        let mut b = [0i32; 17];
        for i in 0..257 {
            if codesize[i] > 0 { b[16] += 1; } // placeholder, refined below
            let _ = i;
        }
        let _ = b;
        // Simpler robust approach: truncate all lengths to 16 and fix the
        // Kraft sum by shortening the longest codes is complicated; the
        // situation is extremely rare with these tables. Fall back to the
        // standard lengths for any symbol whose length overflowed.
        let mut l = 16i32;
        while overflow_count > 0 {
            // Move the longest codes up one level.
            let mut moved = false;
            for i in 0..257 {
                if codesize[i] as i32 == l + 1 {
                    codesize[i] -= 1;
                    overflow_count -= 1;
                    moved = true;
                    if overflow_count == 0 { break; }
                }
            }
            if !moved { l += 1; if l > 64 { break; } }
        }
        bits = [0u8; 17];
        for i in 0..257 {
            if codesize[i] > 0 { bits[codesize[i].min(16) as usize] += 1; }
        }
    }
    // Remove the pseudo-symbol 256 from the counts.
    {
        let l = codesize[256].min(16) as usize;
        if l > 0 { bits[l] = bits[l].saturating_sub(1); }
    }
    let mut out_bits = [0u8; 16];
    out_bits.copy_from_slice(&bits[1..17]);
    // Symbols ordered by (code length, symbol).
    let mut symbols: Vec<u8> = Vec::new();
    for len in 1..=16u32 {
        for i in 0..256usize {
            if codesize[i] == len { symbols.push(i as u8); }
        }
    }
    (out_bits, symbols)
}

struct HuffEnc {
    codes: [u32; 256],
    sizes: [u8; 256],
    bits: [u8; 16],
    symbols: Vec<u8>,
}
impl HuffEnc {
    fn from_freq(freq: &[u32; 257]) -> Self {
        let (bits, symbols) = gen_optimal_table(freq);
        let mut codes = [0u32; 256];
        let mut sizes = [0u8; 256];
        let mut code: u32 = 0;
        let mut idx = 0usize;
        for len in 1..=16usize {
            for _ in 0..bits[len - 1] {
                if idx < symbols.len() {
                    codes[symbols[idx] as usize] = code;
                    sizes[symbols[idx] as usize] = len as u8;
                    idx += 1;
                }
                code += 1;
            }
            code <<= 1;
        }
        Self { codes, sizes, bits, symbols }
    }
    fn from_table(bits: [u8;16], symbols: Vec<u8>) -> Self {
        let mut codes = [0u32; 256];
        let mut sizes = [0u8; 256];
        let mut code: u32 = 0;
        let mut idx = 0usize;
        for len in 1..=16usize {
            for _ in 0..bits[len - 1] {
                if idx < symbols.len() {
                    codes[symbols[idx] as usize] = code;
                    sizes[symbols[idx] as usize] = len as u8;
                    idx += 1;
                }
                code += 1;
            }
            code <<= 1;
        }
        Self { codes, sizes, bits, symbols }
    }
}

struct BitWriter {
    out: Vec<u8>,
    acc: u32,
    nbits: u32,
}
impl BitWriter {
    fn new() -> Self { Self { out: Vec::new(), acc: 0, nbits: 0 } }
    fn put(&mut self, code: u32, size: u32) {
        if size == 0 { return; }
        self.acc = (self.acc << size) | (code & ((1u32 << size) - 1));
        self.nbits += size;
        while self.nbits >= 8 {
            let shift = self.nbits - 8;
            let byte = ((self.acc >> shift) & 0xFF) as u8;
            self.out.push(byte);
            if byte == 0xFF { self.out.push(0); }
            self.nbits -= 8;
            self.acc &= (1u32 << self.nbits) - 1;
        }
    }
    fn put_symbol(&mut self, table: &HuffEnc, sym: u8) {
        self.put(table.codes[sym as usize], table.sizes[sym as usize] as u32);
    }
    fn align(&mut self) {
        if self.nbits > 0 {
            let pad = 8 - self.nbits;
            self.put((1u32 << pad) - 1, pad);
        }
    }
    fn restart_marker(&mut self, idx: usize) {
        self.align();
        self.out.push(0xFF);
        self.out.push(0xD0 + (idx % 8) as u8);
    }
}

fn category(v: i32) -> u32 {
    if v == 0 { 0 } else { 32 - v.unsigned_abs().leading_zeros() }
}

fn encode_block_sequential(
    bw: &mut BitWriter,
    block: &[i16; 64],
    dc_pred: &mut i32,
    dc_tbl: &HuffEnc,
    ac_tbl: &HuffEnc,
) {
    let diff = block[0] as i32 - *dc_pred;
    *dc_pred = block[0] as i32;
    let cat = category(diff);
    bw.put_symbol(dc_tbl, cat as u8);
    if cat > 0 {
        let v = if diff < 0 { diff - 1 } else { diff } as u32;
        bw.put(v & ((1u32 << cat) - 1), cat);
    }
    let mut run = 0usize;
    for k in 1..64 {
        let coef = block[ZIGZAG[k]] as i32;
        if coef == 0 { run += 1; continue; }
        while run > 15 {
            bw.put_symbol(ac_tbl, 0xF0);
            run -= 16;
        }
        let cat = category(coef);
        bw.put_symbol(ac_tbl, ((run << 4) | cat as usize) as u8);
        let v = if coef < 0 { coef - 1 } else { coef } as u32;
        bw.put(v & ((1u32 << cat) - 1), cat);
        run = 0;
    }
    if run > 0 { bw.put_symbol(ac_tbl, 0x00); }
}

fn block_frequencies(
    block: &[i16; 64],
    dc_pred: &mut i32,
    dc_freq: &mut [u32; 257],
    ac_freq: &mut [u32; 257],
) {
    let diff = block[0] as i32 - *dc_pred;
    *dc_pred = block[0] as i32;
    dc_freq[category(diff) as usize] += 1;
    let mut run = 0usize;
    for k in 1..64 {
        let coef = block[ZIGZAG[k]] as i32;
        if coef == 0 { run += 1; continue; }
        while run > 15 { ac_freq[0xF0] += 1; run -= 16; }
        ac_freq[((run << 4) | category(coef) as usize)] += 1;
        run = 0;
    }
    if run > 0 { ac_freq[0x00] += 1; }
}

fn write_marker(out: &mut Vec<u8>, marker: u8, payload: &[u8]) {
    out.push(0xFF);
    out.push(marker);
    out.extend_from_slice(&((payload.len() + 2) as u16).to_be_bytes());
    out.extend_from_slice(payload);
}

fn write_jfif(out: &mut Vec<u8>, jfif: &Jfif) {
    let mut p = Vec::with_capacity(14);
    p.extend_from_slice(b"JFIF\0");
    p.push(jfif.major); p.push(jfif.minor); p.push(jfif.units);
    p.extend_from_slice(&jfif.x_density.to_be_bytes());
    p.extend_from_slice(&jfif.y_density.to_be_bytes());
    p.push(0); p.push(0);
    write_marker(out, 0xE0, &p);
}

pub fn write_icc_segments(out: &mut Vec<u8>, profile: &[u8]) {
    let max_data = 65519usize;
    let chunks = profile.chunks(max_data).count().max(1);
    for (i, chunk) in profile.chunks(max_data).enumerate() {
        let mut p = Vec::with_capacity(14 + chunk.len());
        p.extend_from_slice(b"ICC_PROFILE\0");
        p.push((i + 1) as u8);
        p.push(chunks as u8);
        p.extend_from_slice(chunk);
        write_marker(out, 0xE2, &p);
    }
    if profile.is_empty() {
        let mut p = Vec::new();
        p.extend_from_slice(b"ICC_PROFILE\0");
        p.push(1); p.push(1);
        write_marker(out, 0xE2, &p);
    }
}

fn write_dqt(out: &mut Vec<u8>, tables: &[(usize, &[u16; 64])]) {
    let mut payload = Vec::new();
    for (tq, table) in tables {
        let use16 = table.iter().any(|v| *v > 255);
        if use16 {
            payload.push(0x10 | (*tq as u8));
            for k in 0..64 { payload.extend_from_slice(&table[ZIGZAG[k]].to_be_bytes()); }
        } else {
            payload.push(*tq as u8);
            for k in 0..64 { payload.push(table[ZIGZAG[k]] as u8); }
        }
    }
    write_marker(out, 0xDB, &payload);
}

fn write_sof(out: &mut Vec<u8>, sof_type: u8, width: u32, height: u32, components: &[Comp]) {
    let mut p = Vec::new();
    p.push(8);
    p.extend_from_slice(&(height as u16).to_be_bytes());
    p.extend_from_slice(&(width as u16).to_be_bytes());
    p.push(components.len() as u8);
    for c in components {
        p.push(c.id);
        p.push(((c.h as u8) << 4) | (c.v as u8));
        p.push(c.tq as u8);
    }
    write_marker(out, sof_type, &p);
}

fn write_dht(out: &mut Vec<u8>, tables: &[(u8, usize, &HuffEnc)]) {
    // (class 0=DC/1=AC, id, table)
    let mut payload = Vec::new();
    for (cls, id, tbl) in tables {
        payload.push((cls << 4) | (*id as u8));
        payload.extend_from_slice(&tbl.bits);
        payload.extend_from_slice(&tbl.symbols);
    }
    write_marker(out, 0xC4, &payload);
}

struct ScanDef {
    comps: Vec<(usize, usize, usize)>, // comp idx, dc id, ac id
    ss: usize, se: usize, ah: u32, al: u32,
}

fn progressive_script(ncomp: usize) -> Vec<ScanDef> {
    let mut scans = Vec::new();
    if ncomp == 1 {
        scans.push(ScanDef { comps: vec![(0, 0, 0)], ss: 0, se: 0, ah: 0, al: 0 });
        scans.push(ScanDef { comps: vec![(0, 0, 0)], ss: 1, se: 63, ah: 0, al: 0 });
        return scans;
    }
    // DC for all components.
    let dc: Vec<(usize, usize, usize)> = (0..ncomp).map(|i| (i, if i == 0 { 0 } else { 1 }, 0)).collect();
    scans.push(ScanDef { comps: dc, ss: 0, se: 0, ah: 0, al: 0 });
    // Luma AC in two bands.
    scans.push(ScanDef { comps: vec![(0, 0, 0)], ss: 1, se: 5, ah: 0, al: 0 });
    scans.push(ScanDef { comps: vec![(0, 0, 0)], ss: 6, se: 63, ah: 0, al: 0 });
    for ci in 1..ncomp {
        scans.push(ScanDef { comps: vec![(ci, 0, 1)], ss: 1, se: 2, ah: 0, al: 0 });
        scans.push(ScanDef { comps: vec![(ci, 0, 1)], ss: 3, se: 63, ah: 0, al: 0 });
    }
    scans
}

fn encode_coeff_image(img: &EncodedCoeffImage, baseline: bool, header: &JpegHeader, restart_interval: usize) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::new();
    out.push(0xFF); out.push(0xD8);
    write_jfif(&mut out, &header.jfif);
    for (m, payload) in &header.markers { write_marker(&mut out, *m, payload); }
    // DQT: emit tables actually referenced, in id order.
    let mut table_ids: Vec<usize> = img.components.iter().map(|c| c.tq).collect();
    table_ids.sort(); table_ids.dedup();
    let dqt: Vec<(usize, &[u16;64])> = table_ids.iter().map(|id| (*id, &img.quant[*id])).collect();
    write_dqt(&mut out, &dqt);
    let any16 = table_ids.iter().any(|id| img.quant[*id].iter().any(|v| *v > 255));
    let sof_type = if baseline { if any16 { 0xC1 } else { 0xC0 } } else { 0xC2 };
    write_sof(&mut out, sof_type, img.width, img.height, &img.components);

    let (max_h, max_v) = img.components.iter().fold((1usize,1usize), |(mh,mv),c| (mh.max(c.h), mv.max(c.v)));
    let mcus_x = ((img.width as usize) + max_h * 8 - 1) / (max_h * 8);
    let mcus_y = ((img.height as usize) + max_v * 8 - 1) / (max_v * 8);

    let iter_mcu_blocks = |img: &EncodedCoeffImage, scan_comps: &[(usize, usize, usize)], mut f: &mut dyn FnMut(usize, usize, usize, usize)| {
        // f(comp idx, dc id, ac id, block idx) in MCU order; also handles
        // restart bookkeeping externally via the returned MCU ordering.
        if scan_comps.len() == 1 {
            let (ci, td, ta) = scan_comps[0];
            let (bw, bh) = img.comp_block_dims[ci];
            for by in 0..bh {
                for bx in 0..bw { f(ci, td, ta, by * bw + bx); }
            }
        } else {
            for my in 0..mcus_y {
                for mx in 0..mcus_x {
                    for (ci, td, ta) in scan_comps {
                        let comp = &img.components[*ci];
                        let (bw, _) = img.comp_block_dims[*ci];
                        for by in 0..comp.v {
                            for bx in 0..comp.h {
                                let block_x = mx * comp.h + bx;
                                let block_y = my * comp.v + by;
                                let (tbw, tbh) = img.comp_block_dims[*ci];
                                if block_x < tbw && block_y < tbh {
                                    f(*ci, *td, *ta, block_y * bw + block_x);
                                }
                            }
                        }
                    }
                }
            }
        }
    };

    if baseline {
        // Gather frequencies for the two DC and two AC tables.
        let mut dc_freq = [[0u32; 257]; 2];
        let mut ac_freq = [[0u32; 257]; 2];
        let scan_comps: Vec<(usize, usize, usize)> = img.components.iter().enumerate().map(|(i, _)| {
            if img.components.len() == 1 { (i, 0, 0) } else if i == 0 { (i, 0, 0) } else { (i, 1, 1) }
        }).collect();
        {
            let mut dc_pred = vec![0i32; img.components.len()];
            let mut mcu = 0usize;
            let mut last_restart_check = |dc_pred: &mut Vec<i32>, mcu: usize| {
                if restart_interval > 0 && mcu > 0 && mcu % restart_interval == 0 {
                    for p in dc_pred.iter_mut() { *p = 0; }
                }
            };
            let _ = &mut last_restart_check;
            // Frequency pass in MCU order with restart resets.
            let mut preds = vec![0i32; img.components.len()];
            let mut count = 0usize;
            // We re-implement MCU iteration here to handle restarts.
            if scan_comps.len() == 1 {
                let (ci, td, ta) = scan_comps[0];
                let (bw, bh) = img.comp_block_dims[ci];
                for idx in 0..bw * bh {
                    if restart_interval > 0 && count > 0 && count % restart_interval == 0 { preds[ci] = 0; }
                    block_frequencies(&img.blocks[ci][idx], &mut preds[ci], &mut dc_freq[td], &mut ac_freq[ta]);
                    count += 1;
                }
            } else {
                for my in 0..mcus_y { for mx in 0..mcus_x {
                    if restart_interval > 0 && count > 0 && count % restart_interval == 0 { for p in preds.iter_mut() { *p = 0; } }
                    for (ci, td, ta) in &scan_comps {
                        let comp = &img.components[*ci];
                        let (bw, bh) = img.comp_block_dims[*ci];
                        for by in 0..comp.v { for bx in 0..comp.h {
                            let block_x = mx * comp.h + bx; let block_y = my * comp.v + by;
                            if block_x < bw && block_y < bh {
                                block_frequencies(&img.blocks[*ci][block_y * bw + block_x], &mut preds[*ci], &mut dc_freq[*td], &mut ac_freq[*ta]);
                            }
                        }}
                    }
                    count += 1;
                }}
            }
            let _ = (&mut dc_pred, &mut mcu);
        }
        let dc_tbls: Vec<HuffEnc> = dc_freq.iter().map(HuffEnc::from_freq).collect();
        let ac_tbls: Vec<HuffEnc> = ac_freq.iter().map(HuffEnc::from_freq).collect();
        let mut dht_tables: Vec<(u8, usize, &HuffEnc)> = Vec::new();
        if img.components.len() == 1 {
            dht_tables.push((0, 0, &dc_tbls[0]));
            dht_tables.push((1, 0, &ac_tbls[0]));
        } else {
            dht_tables.push((0, 0, &dc_tbls[0])); dht_tables.push((1, 0, &ac_tbls[0]));
            dht_tables.push((0, 1, &dc_tbls[1])); dht_tables.push((1, 1, &ac_tbls[1]));
        }
        write_dht(&mut out, &dht_tables);
        if restart_interval > 0 {
            write_marker(&mut out, 0xDD, &(restart_interval as u16).to_be_bytes());
        }
        // SOS
        let mut sos = Vec::new();
        sos.push(scan_comps.len() as u8);
        for (ci, td, ta) in &scan_comps {
            sos.push(img.components[*ci].id);
            sos.push(((*td as u8) << 4) | (*ta as u8));
        }
        sos.push(0); sos.push(63); sos.push(0);
        write_marker(&mut out, 0xDA, &sos);
        let mut bw = BitWriter::new();
        let mut preds = vec![0i32; img.components.len()];
        let mut count = 0usize;
        let mut rst = 0usize;
        if scan_comps.len() == 1 {
            let (ci, td, ta) = scan_comps[0];
            let (bwdt, bhdt) = img.comp_block_dims[ci];
            for idx in 0..bwdt * bhdt {
                if restart_interval > 0 && count > 0 && count % restart_interval == 0 {
                    bw.restart_marker(rst); rst += 1; preds[ci] = 0;
                }
                encode_block_sequential(&mut bw, &img.blocks[ci][idx], &mut preds[ci], &dc_tbls[td], &ac_tbls[ta]);
                count += 1;
            }
        } else {
            for my in 0..mcus_y { for mx in 0..mcus_x {
                if restart_interval > 0 && count > 0 && count % restart_interval == 0 {
                    bw.restart_marker(rst); rst += 1;
                    for p in preds.iter_mut() { *p = 0; }
                }
                for (ci, td, ta) in &scan_comps {
                    let comp = &img.components[*ci];
                    let (bwdt, bhdt) = img.comp_block_dims[*ci];
                    for by in 0..comp.v { for bx in 0..comp.h {
                        let block_x = mx * comp.h + bx; let block_y = my * comp.v + by;
                        if block_x < bwdt && block_y < bhdt {
                            encode_block_sequential(&mut bw, &img.blocks[*ci][block_y * bwdt + block_x], &mut preds[*ci], &dc_tbls[*td], &ac_tbls[*ta]);
                        }
                    }}
                }
                count += 1;
            }}
        }
        bw.align();
        out.extend_from_slice(&bw.out);
    } else {
        // Progressive.
        let script = progressive_script(img.components.len());
        for scan in &script {
            // Frequency pass for this scan.
            let mut dc_freq = [[0u32; 257]; 2];
            let mut ac_freq = [[0u32; 257]; 2];
            let mut preds = vec![0i32; img.components.len()];
            let mut eobrun_state = 0usize;
            let _ = &mut eobrun_state;
            if scan.ss == 0 {
                iter_mcu_blocks(img, &scan.comps, &mut |ci, td, _ta, bidx| {
                    let diff = img.blocks[ci][bidx][0] as i32 - preds[ci];
                    preds[ci] = img.blocks[ci][bidx][0] as i32;
                    dc_freq[td][category(diff) as usize] += 1;
                });
            } else {
                iter_mcu_blocks(img, &scan.comps, &mut |ci, _td, ta, bidx| {
                    ac_band_frequencies(&img.blocks[ci][bidx], scan.ss, scan.se, &mut ac_freq[ta]);
                });
            }
            let dc_tbls: Vec<HuffEnc> = dc_freq.iter().map(HuffEnc::from_freq).collect();
            let ac_tbls: Vec<HuffEnc> = ac_freq.iter().map(HuffEnc::from_freq).collect();
            // DHT for tables used by this scan.
            let mut tables: Vec<(u8, usize, &HuffEnc)> = Vec::new();
            let mut seen_dc: Vec<usize> = Vec::new();
            let mut seen_ac: Vec<usize> = Vec::new();
            for (_, td, ta) in &scan.comps {
                if scan.ss == 0 {
                    if !seen_dc.contains(td) { seen_dc.push(*td); tables.push((0, *td, &dc_tbls[*td])); }
                } else if !seen_ac.contains(ta) {
                    seen_ac.push(*ta); tables.push((1, *ta, &ac_tbls[*ta]));
                }
            }
            write_dht(&mut out, &tables);
            let mut sos = Vec::new();
            sos.push(scan.comps.len() as u8);
            for (ci, td, ta) in &scan.comps {
                sos.push(img.components[*ci].id);
                sos.push(((*td as u8) << 4) | (*ta as u8));
            }
            sos.push(scan.ss as u8); sos.push(scan.se as u8); sos.push(((scan.ah as u8) << 4) | (scan.al as u8));
            write_marker(&mut out, 0xDA, &sos);
            let mut bw = BitWriter::new();
            let mut preds = vec![0i32; img.components.len()];
            iter_mcu_blocks(img, &scan.comps, &mut |ci, td, ta, bidx| {
                if scan.ss == 0 {
                    let diff = img.blocks[ci][bidx][0] as i32 - preds[ci];
                    preds[ci] = img.blocks[ci][bidx][0] as i32;
                    let cat = category(diff);
                    bw.put_symbol(&dc_tbls[td], cat as u8);
                    if cat > 0 {
                        let v = if diff < 0 { diff - 1 } else { diff } as u32;
                        bw.put(v & ((1u32 << cat) - 1), cat);
                    }
                } else {
                    encode_ac_band(&mut bw, &img.blocks[ci][bidx], scan.ss, scan.se, &ac_tbls[ta]);
                }
            });
            bw.align();
            out.extend_from_slice(&bw.out);
        }
    }
    out.push(0xFF); out.push(0xD9);
    out
}

fn ac_band_frequencies(block: &[i16;64], ss: usize, se: usize, freq: &mut [u32;257]) {
    let mut run = 0usize;
    for k in ss..=se {
        let coef = block[ZIGZAG[k]] as i32;
        if coef == 0 { run += 1; continue; }
        while run > 15 { freq[0xF0] += 1; run -= 16; }
        freq[((run << 4) | category(coef) as usize)] += 1;
        run = 0;
    }
    if run > 0 { freq[0x00] += 1; }
}

fn encode_ac_band(bw: &mut BitWriter, block: &[i16;64], ss: usize, se: usize, ac_tbl: &HuffEnc) {
    let mut run = 0usize;
    for k in ss..=se {
        let coef = block[ZIGZAG[k]] as i32;
        if coef == 0 { run += 1; continue; }
        while run > 15 { bw.put_symbol(ac_tbl, 0xF0); run -= 16; }
        let cat = category(coef);
        bw.put_symbol(ac_tbl, ((run << 4) | cat as usize) as u8);
        let v = if coef < 0 { coef - 1 } else { coef } as u32;
        bw.put(v & ((1u32 << cat) - 1), cat);
        run = 0;
    }
    if run > 0 { bw.put_symbol(ac_tbl, 0x00); }
}

pub fn encode_jpeg_moz(raster: &Raster, quality: u8, baseline: bool, chroma: crate::cli::Chroma, header: &JpegHeader) -> CResult<Vec<u8>> {
    if raster.width == 0 || raster.height == 0 || raster.width > 65535 || raster.height > 65535 {
        return Err(internal_jpeg_error(41));
    }
    let table = scale_qtable(&MOZ_QTABLE, quality);
    let tables: [[u16;64];2] = [table, table];
    let sampling = match chroma {
        crate::cli::Chroma::C444 => (1, 1),
        crate::cli::Chroma::C422 => (2, 1),
        crate::cli::Chroma::C411 => (4, 1),
        _ => (2, 2),
    };
    let img = build_coeff_image(raster, sampling, &tables);
    Ok(encode_coeff_image(&img, baseline, header, 0))
}

pub fn encode_jpeg_std(raster: &Raster, baseline: bool, header: &JpegHeader) -> CResult<Vec<u8>> {
    if raster.width == 0 || raster.height == 0 || raster.width > 65535 || raster.height > 65535 {
        return Err(CError::with_codes(
            format!("Format error encoding Jpeg:\nInvalid image size ({} x {}) to encode as JPEG: width and height must be >= 1 and <= 65535", raster.width, raster.height),
            vec![10302, 10405],
        ));
    }
    let tables: [[u16;64];2] = [scale_qtable(&STD_QTABLE_LUMA, 75), scale_qtable(&STD_QTABLE_CHROMA, 75)];
    let img = build_coeff_image(raster, (1, 1), &tables);
    Ok(encode_coeff_image(&img, baseline, header, 0))
}

/// Decode the coefficients of a std-encoded intermediate back to pixels.
/// (Used to model the two-stage resized/converted JPEG pipelines.)
pub fn std_intermediate_raster(raster: &Raster) -> Raster {
    let tables: [[u16;64];2] = [scale_qtable(&STD_QTABLE_LUMA, 75), scale_qtable(&STD_QTABLE_CHROMA, 75)];
    let img = build_coeff_image(raster, (1, 1), &tables);
    // Rebuild a CoeffImage with a minimal JpegInfo to run the IDCT path.
    let info = JpegInfo {
        width: img.width, height: img.height, precision: 8,
        components: img.components.clone(), progressive: false, sof_type: 0xC0,
        quant: vec![Some(tables[0]), Some(tables[1])],
        restart_interval: 0, jfif: None, markers: vec![], adobe_transform: None,
        metadata: Metadata::default(),
    };
    let coeff = CoeffImage { info, blocks: img.blocks.clone(), comp_block_dims: img.comp_block_dims.clone() };
    coeff.to_raster()
}

pub fn recode_coefficients(coeff: &CoeffImage, baseline: bool, header: &JpegHeader) -> Vec<u8> {
    let mut tables_vec: Vec<[u16;64]> = Vec::new();
    for i in 0..2 {
        tables_vec.push(coeff.info.quant.get(i).and_then(|t| *t).unwrap_or(MOZ_QTABLE));
    }
    // Map each component's quant table index to 0/1 slots if needed.
    let mut components = coeff.info.components.clone();
    let mut quant: Vec<[u16;64]> = vec![tables_vec[0], tables_vec[1]];
    // If components reference quant tables beyond 1, extend.
    for c in &components {
        if c.tq >= quant.len() {
            quant.resize(c.tq + 1, MOZ_QTABLE);
            if let Some(t) = coeff.info.quant.get(c.tq).and_then(|t| *t) { quant[c.tq] = t; }
        } else if let Some(t) = coeff.info.quant.get(c.tq).and_then(|t| *t) {
            quant[c.tq] = t;
        }
    }
    while quant.len() < 2 { quant.push(MOZ_QTABLE); }
    let img = EncodedCoeffImage {
        width: coeff.info.width, height: coeff.info.height,
        components: std::mem::take(&mut components),
        blocks: coeff.blocks.clone(),
        comp_block_dims: coeff.comp_block_dims.clone(),
        quant,
        quant_ids: vec![0, 1],
    };
    encode_coeff_image(&img, baseline, header, coeff.info.restart_interval)
}

/// Lossless JPEG handling: stream-copy the entropy data when the scan
/// mode does not change, otherwise recode to a single sequential scan.
pub fn lossless_copy(data: &[u8], header: &JpegHeader, baseline: bool, keep_markers: bool, icc: Option<&[u8]>) -> CResult<Vec<u8>> {
    let coeff = decode_jpeg_coefficients(data)?;
    let needs_recode = baseline && coeff.info.progressive;
    if needs_recode {
        return Ok(recode_coefficients(&coeff, true, header));
    }
    // Validate by decoding (already done) and then copy the stream from the
    // first DQT onward, with a regenerated header.
    let (segments, sos_pos) = match parse_segments_until_sos(data) {
        Ok(v) => v,
        Err(e) => return Err(e),
    };
    let mut out: Vec<u8> = Vec::new();
    out.push(0xFF); out.push(0xD8);
    write_jfif(&mut out, &header.jfif);
    // header.markers already contains whatever the caller wants copied
    // (all APPn/COM segments when keeping metadata, or none).
    for (m, payload) in &header.markers { write_marker(&mut out, *m, payload); }
    if !keep_markers {
        if let Some(profile) = icc { write_icc_segments(&mut out, profile); }
    }
    // Emit pre-SOS segments starting at the first DQT, skipping APPn/COM.
    let mut started = false;
    for seg in &segments {
        if seg.marker == 0xDA { break; }
        if seg.marker == 0xDB { started = true; }
        if !started { continue; }
        if (0xE0..=0xEF).contains(&seg.marker) || seg.marker == 0xFE { continue; }
        out.extend_from_slice(&data[seg.start..seg.end]);
    }
    if let Some(sos) = sos_pos {
        out.extend_from_slice(&data[sos..]);
    }
    Ok(out)
}
