fn scale_qtable(base: &[u16; 64], quality: u8) -> [u16; 64] {
    let mut q = quality as i32;
    if q <= 0 { q = 1; }
    if q > 100 { q = 100; }
    let scale = if q < 50 { 5000 / q } else { 200 - 2 * q };
    let mut out = [0u16; 64];
    for i in 0..64 {
        let mut v = (base[i] as i32 * scale + 50) / 100;
        if v < 1 { v = 1; }
        if v > 65535 { v = 65535; }
        out[i] = v as u16;
    }
    out
}

