#[derive(Clone)]
pub struct Collected {
    pub path: PathBuf,
    pub format: InputFormat,
}

fn detect_format(path: &Path) -> Option<InputFormat> {
    let mut f = fs::File::open(path).ok()?;
    let mut buf = [0u8; 16];
    f.read_exact(&mut buf).ok()?;
    if &buf[0..4] == b"\x89PNG" { return Some(InputFormat::Png); }
    if &buf[0..3] == b"\xFF\xD8\xFF" { return Some(InputFormat::Jpeg); }
    if &buf[0..3] == b"GIF" { return Some(InputFormat::Gif); }
    if &buf[8..12] == b"WEBP" { return Some(InputFormat::Webp); }
    None
}

pub fn detect_format_bytes(data: &[u8]) -> Option<InputFormat> {
    if data.len() < 16 { return None; }
    if &data[0..4] == b"\x89PNG" { return Some(InputFormat::Png); }
    if data[0] == 0xFF && data[1] == 0xD8 && data[2] == 0xFF { return Some(InputFormat::Jpeg); }
    if &data[0..3] == b"GIF" { return Some(InputFormat::Gif); }
    if &data[8..12] == b"WEBP" { return Some(InputFormat::Webp); }
    None
}

fn collect_dir(dir: &Path, recursive: bool, out: &mut Vec<Collected>) {
    let entries = match fs::read_dir(dir) { Ok(e) => e, Err(_) => return };
    for entry in entries {
        let entry = match entry { Ok(e) => e, Err(_) => continue };
        let ft = match entry.file_type() { Ok(t) => t, Err(_) => continue };
        let path = entry.path();
        if ft.is_dir() {
            if recursive { collect_dir(&path, recursive, out); }
        } else if path.is_file() {
            if let Some(fmt) = detect_format(&path) {
                out.push(Collected { path, format: fmt });
            }
        }
    }
}

pub fn collect_files(inputs: &[String], recursive: bool) -> Vec<Collected> {
    let mut out = Vec::new();
    for input in inputs {
        let path = PathBuf::from(input);
        if path.is_file() {
            if let Some(fmt) = detect_format(&path) {
                out.push(Collected { path, format: fmt });
            }
        } else if path.is_dir() {
            collect_dir(&path, recursive, &mut out);
        }
    }
    out
}

pub fn compute_base_path(files: &[Collected]) -> Option<PathBuf> {
    if files.is_empty() { return None; }
    let mut common: Vec<Component> = Vec::new();
    for (i, f) in files.iter().enumerate() {
        let abs = std::path::absolute(&f.path).ok()?;
        let parent = abs.parent()?;
        let comps: Vec<Component> = parent.components().collect();
        if i == 0 {
            common = comps;
        } else {
            let mut n = 0usize;
            while n < common.len() && n < comps.len() && common[n] == comps[n] { n += 1; }
            common.truncate(n);
            if common.is_empty() { return None; }
        }
    }
    if common.is_empty() { return None; }
    let mut p = PathBuf::new();
    for c in common { p.push(c); }
    Some(p)
}

fn output_filename(input: &Path, args: &Args) -> String {
    let stem = input.file_stem().map(|s| s.to_string_lossy().into_owned()).unwrap_or_default();
    let suffix = args.suffix.as_deref().unwrap_or("");
    let ext: String = match args.format {
        OutputFormat::Original => input.extension().map(|s| s.to_string_lossy().into_owned()).unwrap_or_default(),
        OutputFormat::Jpeg => "jpg".to_string(),
        OutputFormat::Png => "png".to_string(),
        OutputFormat::Gif => "gif".to_string(),
        OutputFormat::Webp => "webp".to_string(),
        OutputFormat::Tiff => "tiff".to_string(),
    };
    if ext.is_empty() { format!("{}{}", stem, suffix) } else { format!("{}{}.{}", stem, suffix, ext) }
}

fn setup_output_path(input: &Path, args: &Args, base_path: &Path) -> Result<PathBuf, ()> {
    let filename = output_filename(input, args);
    if args.keep_structure {
        let parent = input.parent().ok_or(())?;
        let abs_parent = std::path::absolute(parent).map_err(|_| ())?;
        let rel_parent = abs_parent.strip_prefix(base_path).map_err(|_| ())?;
        let out_dir = if args.same_folder_as_input {
            abs_parent.clone()
        } else {
            args.output.clone().unwrap_or_default().join(rel_parent)
        };
        if !args.dry_run {
            fs::create_dir_all(&out_dir).map_err(|_| ())?;
        }
        Ok(out_dir.join(filename))
    } else if args.same_folder_as_input {
        let parent = input.parent().unwrap_or(Path::new(""));
        Ok(parent.join(filename))
    } else {
        let out_dir = args.output.clone().unwrap_or_default();
        if !args.dry_run && !out_dir.exists() {
            fs::create_dir_all(&out_dir).map_err(|_| ())?;
        }
        Ok(out_dir.join(filename))
    }
}

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Status { Success, Skipped, Error }

#[derive(Clone)]
pub struct FileResult {
    pub input: PathBuf,
    pub output: PathBuf,
    pub original_size: u64,
    pub output_size: u64,
    pub status: Status,
    pub message: Option<String>,
}

#[derive(Clone, Copy, PartialEq)]
pub enum Mode { Quality(u8), Lossless, MaxSize(u64) }

fn mode_of(args: &Args) -> Mode {
    if let Some(q) = args.quality { Mode::Quality(q) }
    else if args.lossless { Mode::Lossless }
    else { Mode::MaxSize(args.max_size.unwrap_or(0)) }
}

fn resize_requested(args: &Args) -> bool {
    args.width.map(|v| v > 0).unwrap_or(false)
        || args.height.map(|v| v > 0).unwrap_or(false)
        || args.long_edge.map(|v| v > 0).unwrap_or(false)
        || args.short_edge.map(|v| v > 0).unwrap_or(false)
}

/// Translate long/short-edge options into a single width/height request.
fn translate_edge_request(args: &Args, basis_w: u32, basis_h: u32) -> (Option<u32>, Option<u32>) {
    if let Some(l) = args.long_edge {
        if l > 0 {
            if basis_w >= basis_h { return (Some(l), None); } else { return (None, Some(l)); }
        }
    }
    if let Some(s) = args.short_edge {
        if s > 0 {
            if basis_w <= basis_h { return (Some(s), None); } else { return (None, Some(s)); }
        }
    }
    (args.width.filter(|v| *v > 0), args.height.filter(|v| *v > 0))
}

fn compute_target_dims(actual_w: u32, actual_h: u32, req_w: Option<u32>, req_h: Option<u32>) -> (u32, u32) {
    match (req_w, req_h) {
        (Some(w), Some(h)) => (w, h),
        (Some(w), None) => {
            let h = (actual_h as f64 * w as f64 / actual_w as f64).round() as u32;
            (w, h)
        }
        (None, Some(h)) => {
            let w = (actual_w as f64 * h as f64 / actual_h as f64).round() as u32;
            (w, h)
        }
        (None, None) => (actual_w, actual_h),
    }
}

fn no_upscale_cancels(args: &Args, req_w: Option<u32>, req_h: Option<u32>, cmp_w: u32, cmp_h: u32) -> bool {
    if !args.no_upscale { return false; }
    if let Some(w) = req_w { if w >= cmp_w { return true; } }
    if let Some(h) = req_h { if h >= cmp_h { return true; } }
    false
}

fn set_file_times(path: &Path, atime: SystemTime, mtime: SystemTime) {
    // utimensat via libc-style FFI to the C library.
    #[cfg(unix)]
    unsafe {
        use std::ffi::CString;
        use std::os::raw::{c_char, c_int, c_long};
        #[repr(C)]
        struct TimeSpec { tv_sec: i64, tv_nsec: c_long }
        extern "C" { fn utimensat(dirfd: c_int, pathname: *const c_char, times: *const TimeSpec, flags: c_int) -> c_int; }
        let to_ts = |t: SystemTime| -> TimeSpec {
            match t.duration_since(SystemTime::UNIX_EPOCH) {
                Ok(d) => TimeSpec { tv_sec: d.as_secs() as i64, tv_nsec: d.subsec_nanos() as c_long },
                Err(e) => {
                    let d = e.duration();
                    if d.subsec_nanos() == 0 {
                        TimeSpec { tv_sec: -(d.as_secs() as i64), tv_nsec: 0 }
                    } else {
                        TimeSpec { tv_sec: -(d.as_secs() as i64) - 1, tv_nsec: (1_000_000_000 - d.subsec_nanos()) as c_long }
                    }
                }
            }
        };
        if let Ok(cpath) = CString::new(path.as_os_str().to_string_lossy().as_bytes()) {
            let times = [to_ts(atime), to_ts(mtime)];
            let _ = utimensat(-100, cpath.as_ptr(), times.as_ptr(), 0);
        }
    }
}

// ---------- JPEG header construction ----------
fn jpeg_header_direct(info: &jpeg::JpegInfo, args: &Args, lossless: bool) -> JpegHeader {
    // Same-format, no resize.
    let jfif = if lossless {
        info.jfif.clone().unwrap_or_default()
    } else {
        Jfif::default()
    };
    let markers = if args.exif { info.markers.clone() } else { vec![] };
    JpegHeader { jfif, markers }
}

fn jpeg_header_via_std(args: &Args, metadata: &Metadata, source_is_jpeg: bool, lossless: bool) -> JpegHeader {
    // Header as produced after a std-encoder intermediate stage.
    let jfif = if lossless {
        Jfif { major: 1, minor: 2, units: 0, x_density: 1, y_density: 1 }
    } else {
        Jfif::default()
    };
    let mut markers: Vec<(u8, Vec<u8>)> = Vec::new();
    if args.exif {
        // The intermediate's own APP0 is copied as a marker.
        let mut app0 = Vec::new();
        app0.extend_from_slice(b"JFIF\0");
        app0.push(1); app0.push(2); app0.push(0);
        app0.extend_from_slice(&1u16.to_be_bytes());
        app0.extend_from_slice(&1u16.to_be_bytes());
        app0.push(0); app0.push(0);
        markers.push((0xE0, app0));
        if let Some(exif) = &metadata.exif {
            let mut p = b"Exif\0\0".to_vec();
            p.extend_from_slice(exif);
            markers.push((0xE1, p));
        }
        if let Some(icc) = &metadata.icc {
            // A single APP2 segment for typical profile sizes.
            let mut tmp: Vec<u8> = Vec::new();
            jpeg::write_icc_segments(&mut tmp, icc);
            // Convert the emitted segments back into (marker, payload) pairs.
            let mut pos = 0usize;
            while pos + 4 <= tmp.len() {
                let len = u16::from_be_bytes([tmp[pos+2], tmp[pos+3]]) as usize;
                markers.push((0xE2, tmp[pos+4..pos+2+len].to_vec()));
                pos += 2 + len;
            }
        }
    } else if source_is_jpeg {
        // ICC is carried through the intermediate for JPEG sources even
        // without -e (handled by the caller via icc arguments instead).
    }
    JpegHeader { jfif, markers }
}

fn icc_to_keep(args: &Args, metadata: &Metadata, source_is_jpeg: bool, via_std: bool) -> Option<Vec<u8>> {
    // Returns Some(profile) when an APP2 ICC segment should be written by
    // the encoder itself (i.e. not via copied markers).
    if args.exif { return None; } // included in copied markers
    if args.strip_icc { return None; }
    if via_std && !source_is_jpeg { return None; }
    metadata.icc.clone()
}

// ---------- compression dispatch ----------
struct Ctx<'a> {
    args: &'a Args,
    mode: Mode,
    target: OutputFormat,
    is_conversion: bool,
}

fn decode_source_static(format: InputFormat, data: &[u8], flavor_code: u32) -> CResult<(Raster, Metadata)> {
    match format {
        InputFormat::Png => {
            let png = png::parse_png(data).map_err(|e| e.to_cerror(Flavor::Image(flavor_code)))?;
            Ok((png.to_raster(), png.metadata.clone()))
        }
        InputFormat::Jpeg => {
            let _guard = jpeg::set_jpeg_image_error_mode(flavor_code);
            jpeg::decode_jpeg(data)
        }
        InputFormat::Gif => {
            let gif = parse_gif(data).map_err(|mut e| {
                // Conversion / resize decoding reports gif errors in the
                // image-crate style.
                if e.message == "Found no usable frames to encode" {
                    e = CError::new("Format error decoding Gif: Unexpected End of File", flavor_code);
                } else if e.codes == vec![20404] {
                    e = CError::new(format!("Format error decoding Gif: {}", e.message), flavor_code);
                }
                e
            })?;
            Ok((gif.first_frame_raster(), Metadata::default()))
        }
        InputFormat::Webp => {
            webp::decode_webp(data).map_err(|e| {
                if e.codes == vec![20304] {
                    CError::new("failed to fill whole buffer", flavor_code)
                } else { e }
            })
        }
    }
}

fn apply_resize_generic(raster: &Raster, args: &Args, basis_w: u32, basis_h: u32, cmp_w: u32, cmp_h: u32) -> Option<(Raster, bool)> {
    // Returns Some((resized, resized_flag)) when a resize was requested.
    if !resize_requested(args) { return None; }
    let (req_w, req_h) = translate_edge_request(args, basis_w, basis_h);
    if no_upscale_cancels(args, req_w, req_h, cmp_w, cmp_h) {
        return Some((raster.clone(), false));
    }
    let (tw, th) = compute_target_dims(raster.width, raster.height, req_w, req_h);
    Some((raster.resize(tw.max(1), th.max(1)), true))
}

fn check_zero_dims(tw: u32, th: u32) -> CResult<()> {
    if tw == 0 { return Err(CError::new("Zero width not allowed", 10302)); }
    if th == 0 { return Err(CError::new("Zero height not allowed", 10302)); }
    Ok(())
}

fn encode_target(
    ctx: &Ctx,
    raster: &Raster,
    source_format: InputFormat,
    metadata: &Metadata,
    quality: Option<u8>, // None = lossless
    jpeg_header: &JpegHeader,
    jpeg_icc: Option<&[u8]>,
) -> CResult<Vec<u8>> {
    let args = ctx.args;
    match ctx.target {
        OutputFormat::Jpeg => {
            // Insert an ICC segment after the JFIF APP0 when applicable.
            let mut header = jpeg_header.clone();
            if let Some(profile) = jpeg_icc {
                let mut tmp: Vec<u8> = Vec::new();
                jpeg::write_icc_segments(&mut tmp, profile);
                let mut pos = 0usize;
                let mut segs: Vec<(u8, Vec<u8>)> = Vec::new();
                while pos + 4 <= tmp.len() {
                    let len = u16::from_be_bytes([tmp[pos+2], tmp[pos+3]]) as usize;
                    segs.push((0xE2, tmp[pos+4..pos+2+len].to_vec()));
                    pos += 2 + len;
                }
                segs.extend(header.markers.iter().cloned());
                header.markers = segs;
            }
            match quality {
                Some(q) => jpeg::encode_jpeg_moz(raster, q, args.jpeg_baseline, args.jpeg_chroma_subsampling, &header),
                None => jpeg::encode_jpeg_std(raster, args.jpeg_baseline, &header),
            }
        }
        OutputFormat::Png => {
            let _ = source_format;
            match quality {
                Some(q) => Ok(png::compress_png_lossy(raster, q, args.png_opt_level, args.zopfli, metadata, args.exif)),
                None => {
                    let bytes = png::encode_png_generic(raster, metadata, args.exif);
                    match png::parse_png(&bytes) {
                        Ok(parsed) => Ok(png::optimize_png(&parsed, args.png_opt_level, args.zopfli)),
                        Err(_) => Ok(bytes),
                    }
                }
            }
        }
        OutputFormat::Webp => webp::encode_webp(raster, quality, metadata, args.exif),
        OutputFormat::Gif => {
            if !matches!(raster.kind, ColorKind::Rgb8 | ColorKind::Rgba8) {
                return Err(CError::new(format!("The encoder or decoder for Gif does not support the color type `{}`", raster.kind.name()), 10404));
            }
            let q = quality.unwrap_or(100);
            // GIF output never upscales: clamp each dimension.
            let frames = vec![GifFrameSpec { rgba: raster.rgba8(), delay_cs: 2 }];
            Ok(encode_gif(raster.width, raster.height, &frames, None, q))
        }
        OutputFormat::Tiff => {
            let best = matches!(ctx.mode, Mode::MaxSize(_));
            encode_tiff(raster, best)
        }
        OutputFormat::Original => unreachable!(),
    }
}

fn compress_to_size<F: FnMut(u8) -> CResult<Vec<u8>>>(mut encode: F, max: u64) -> CResult<Vec<u8>> {
    let mut cache: std::collections::HashMap<u8, Vec<u8>> = std::collections::HashMap::new();
    let mut try_q = |q: u8, cache: &mut std::collections::HashMap<u8, Vec<u8>>, encode: &mut F| -> CResult<Vec<u8>> {
        if let Some(v) = cache.get(&q) { return Ok(v.clone()); }
        let v = encode(q)?;
        cache.insert(q, v.clone());
        Ok(v)
    };
    let top = try_q(100, &mut cache, &mut encode)?;
    if (top.len() as u64) <= max { return Ok(top); }
    let bottom = try_q(1, &mut cache, &mut encode)?;
    if (bottom.len() as u64) > max {
        // Smallest possible result (quality 1, as in the original).
        return Ok(bottom);
    }
    let mut lo = 1u8;
    let mut hi = 100u8;
    let mut best = bottom;
    while lo <= hi {
        let mid = lo + (hi - lo) / 2;
        let v = try_q(mid, &mut cache, &mut encode)?;
        if (v.len() as u64) <= max {
            best = v;
            lo = mid.saturating_add(1);
            if mid == 100 { break; }
        } else {
            if mid == 0 { break; }
            hi = mid - 1;
        }
    }
    Ok(best)
}

fn compress_dispatch(collected: &Collected, data: &[u8], args: &Args) -> CResult<Vec<u8>> {
    let mode = mode_of(args);
    let target = if args.format == OutputFormat::Original { collected.format.to_output() } else { args.format };
    let is_conversion = args.format != OutputFormat::Original;
    let ctx = Ctx { args, mode, target, is_conversion };

    if is_conversion && target == collected.format.to_output() {
        return Err(CError::new("Cannot convert to the same format", 10407));
    }

    // Lightweight dimensions for parameter building (resize handling).
    let dims = basic_dimensions(collected.format, data);

    if is_conversion {
        return compress_conversion(&ctx, collected, data, dims);
    }

    // Same-format paths.
    match collected.format {
        InputFormat::Png => compress_png_same(&ctx, data, dims),
        InputFormat::Jpeg => compress_jpeg_same(&ctx, data, dims),
        InputFormat::Webp => compress_webp_same(&ctx, data, dims),
        InputFormat::Gif => compress_gif_same(&ctx, data, dims),
    }
}

fn basic_dimensions(format: InputFormat, data: &[u8]) -> Option<(u32, u32)> {
    match format {
        InputFormat::Png => png::png_dimensions(data),
        InputFormat::Jpeg => jpeg::jpeg_dimensions(data),
        InputFormat::Webp => webp::webp_dimensions(data),
        InputFormat::Gif => {
            if data.len() >= 10 {
                Some((u16::from_le_bytes([data[6], data[7]]) as u32, u16::from_le_bytes([data[8], data[9]]) as u32))
            } else { None }
        }
    }
}

fn build_params_error() -> CError {
    // Rendered without the usual "Error compressing file:" prefix by using
    // a marker in the message that process_file converts. We instead return
    // a CError with a dedicated code and translate in process_file.
    CError::new("Error building compression parameters: failed to fill whole buffer", u32::MAX)
}

/// Check whether a JPEG/WebP header is too truncated for image_dimensions.
fn header_truncated(format: InputFormat, data: &[u8]) -> bool {
    match format {
        InputFormat::Jpeg => {
            // Walk segments; if a segment runs past the end before an SOF
            // is found, image_dimensions fails with a short read.
            if data.len() < 4 { return true; }
            let mut pos = 2usize;
            loop {
                if pos + 4 > data.len() { return true; }
                if data[pos] != 0xFF { return false; }
                let marker = data[pos + 1];
                if marker == 0xDA { return false; }
                if marker == 0x01 || (0xD0..=0xD9).contains(&marker) { pos += 2; continue; }
                let len = u16::from_be_bytes([data[pos+2], data[pos+3]]) as usize;
                if len < 2 || pos + 2 + len > data.len() { return true; }
                if (0xC0..=0xCF).contains(&marker) && !matches!(marker, 0xC4 | 0xC8 | 0xCC) { return false; }
                pos += 2 + len;
            }
        }
        InputFormat::Webp => {
            // Need a complete VP8/VP8L/VP8X chunk header.
            if data.len() < 20 { return true; }
            let len = u32::from_le_bytes([data[16], data[17], data[18], data[19]]) as usize;
            // The dimension fields live within the first chunk's header.
            match &data[12..16] {
                b"VP8 " => data.len() < 30,
                b"VP8L" => data.len() < 25,
                b"VP8X" => data.len() < 30,
                _ => 20 + len > data.len(),
            }
        }
        _ => false,
    }
}

fn compress_conversion(ctx: &Ctx, collected: &Collected, data: &[u8], _dims: Option<(u32,u32)>) -> CResult<Vec<u8>> {
    let args = ctx.args;
    let (mut raster, metadata) = decode_source_static(collected.format, data, 10403)?;
    // Orientation is physically applied for JPEG inputs when keeping EXIF.
    if collected.format == InputFormat::Jpeg && args.exif {
        if let Some(orient) = metadata.orientation {
            raster = raster.apply_orientation(orient);
        }
    }
    // Resize based on the (possibly rotated) raster.
    let mut via_std = false;
    if resize_requested(args) {
        let (req_w, req_h) = translate_edge_request(args, raster.width, raster.height);
        if !no_upscale_cancels(args, req_w, req_h, raster.width, raster.height) {
            let (tw, th) = compute_target_dims(raster.width, raster.height, req_w, req_h);
            check_zero_dims(tw, th)?;
            raster = raster.resize(tw.max(1), th.max(1));
            via_std = false;
        }
    }
    let _ = via_std;
    // GIF output ignores upscaling beyond the source size of the *frame*:
    // handled inside encode by the general path being fed an already-clamped
    // raster in compress_gif conversion in the original. We approximate by
    // clamping the raster when the target is GIF and a resize upscaled it.
    // (The raster here has already been resized, so nothing more to do.)

    let quality: Option<u8> = match ctx.mode { Mode::Quality(q) => Some(q), Mode::Lossless => None, Mode::MaxSize(_) => Some(80) };
    let header = jpeg_header_via_std(args, &metadata, collected.format == InputFormat::Jpeg, quality.is_none());
    let icc = if ctx.target == OutputFormat::Jpeg { icc_to_keep(args, &metadata, collected.format == InputFormat::Jpeg, true) } else { None };

    // For JPEG output the pixels go through a std-encoder intermediate.
    let effective_raster;
    let raster_ref: &Raster = if ctx.target == OutputFormat::Jpeg {
        effective_raster = jpeg::std_intermediate_raster(&raster);
        &effective_raster
    } else {
        &raster
    };

    match ctx.mode {
        Mode::MaxSize(max) => {
            if ctx.target == OutputFormat::Tiff {
                return encode_target(ctx, raster_ref, collected.format, &metadata, Some(100), &header, icc.as_deref());
            }
            let header_c = header.clone();
            let icc_c = icc.clone();
            compress_to_size(|q| {
                encode_target(ctx, raster_ref, collected.format, &metadata, Some(q), &header_c, icc_c.as_deref())
            }, max)
        }
        _ => encode_target(ctx, raster_ref, collected.format, &metadata, quality, &header, icc.as_deref()),
    }
}

fn compress_png_same(ctx: &Ctx, data: &[u8], _dims: Option<(u32,u32)>) -> CResult<Vec<u8>> {
    let args = ctx.args;
    if resize_requested(args) {
        // Dimension based cancellation happens before a full decode.
        let png_probe = png::parse_png(data);
        let png = match png_probe {
            Ok(p) => p,
            Err(e) => return Err(e.to_cerror(Flavor::Image(10301))),
        };
        let raster = png.to_raster();
        let (req_w, req_h) = translate_edge_request(args, raster.width, raster.height);
        if !no_upscale_cancels(args, req_w, req_h, raster.width, raster.height) {
            let (tw, th) = compute_target_dims(raster.width, raster.height, req_w, req_h);
            check_zero_dims(tw, th)?;
            let resized = raster.resize(tw.max(1), th.max(1));
            return match ctx.mode {
                Mode::Quality(q) => Ok(png::compress_png_lossy(&resized, q, args.png_opt_level, args.zopfli, &Metadata::default(), false)),
                Mode::Lossless => {
                    let bytes = png::encode_png_generic(&resized, &Metadata::default(), false);
                    match png::parse_png(&bytes) {
                        Ok(parsed) => Ok(png::optimize_png(&parsed, args.png_opt_level, args.zopfli)),
                        Err(_) => Ok(bytes),
                    }
                }
                Mode::MaxSize(max) => compress_to_size(|q| Ok(png::compress_png_lossy(&resized, q, args.png_opt_level, args.zopfli, &Metadata::default(), false)), max),
            };
        }
        // Cancelled: fall through to the no-resize path using `png`.
        return compress_png_no_resize(ctx, data, Some(png));
    }
    compress_png_no_resize(ctx, data, None)
}

fn compress_png_no_resize(ctx: &Ctx, data: &[u8], pre_parsed: Option<PngImage>) -> CResult<Vec<u8>> {
    let args = ctx.args;
    match ctx.mode {
        Mode::Lossless => {
            let png = match pre_parsed {
                Some(p) => p,
                None => png::parse_png(data).map_err(|e| e.to_cerror(Flavor::Oxipng))?,
            };
            Ok(png::optimize_png(&png, args.png_opt_level, args.zopfli))
        }
        Mode::Quality(q) => {
            let png = match pre_parsed {
                Some(p) => p,
                None => png::parse_png(data).map_err(|e| e.to_cerror(Flavor::Zune))?,
            };
            let raster = png.to_raster();
            Ok(png::compress_png_lossy(&raster, q, args.png_opt_level, args.zopfli, &Metadata::default(), false))
        }
        Mode::MaxSize(max) => {
            let png = match pre_parsed {
                Some(p) => p,
                None => png::parse_png(data).map_err(|e| e.to_cerror(Flavor::Zune))?,
            };
            let raster = png.to_raster();
            compress_to_size(|q| Ok(png::compress_png_lossy(&raster, q, args.png_opt_level, args.zopfli, &Metadata::default(), false)), max)
        }
    }
}

fn compress_jpeg_same(ctx: &Ctx, data: &[u8], _dims: Option<(u32,u32)>) -> CResult<Vec<u8>> {
    let args = ctx.args;
    if resize_requested(args) {
        if header_truncated(InputFormat::Jpeg, data) {
            return Err(build_params_error());
        }
        let info = jpeg::parse_jpeg_info(data)?;
        let (stored_w, stored_h) = (info.width, info.height);
        let rotated = matches!(info.metadata.orientation, Some(5..=8));
        let (basis_w, basis_h) = if args.exif && rotated { (stored_h, stored_w) } else { (stored_w, stored_h) };
        let (req_w, req_h) = translate_edge_request(args, basis_w, basis_h);
        let is_edge = args.long_edge.map(|v| v > 0).unwrap_or(false) || args.short_edge.map(|v| v > 0).unwrap_or(false);
        let (cmp_w, cmp_h) = if is_edge { (basis_w, basis_h) } else { (stored_w, stored_h) };
        if !no_upscale_cancels(args, req_w, req_h, cmp_w, cmp_h) {
            // Swap the request when the stored image is rotated.
            let (mut eff_w, mut eff_h) = (req_w, req_h);
            if rotated { std::mem::swap(&mut eff_w, &mut eff_h); }
            let (tw, th) = compute_target_dims(stored_w, stored_h, eff_w, eff_h);
            check_zero_dims(tw, th)?;
            let (raster, _meta) = {
                let _g = jpeg::set_jpeg_image_error_mode(10301);
                jpeg::decode_jpeg(data)?
            };
            let resized = raster.resize(tw.max(1), th.max(1));
            let metadata = &info.metadata;
            return match ctx.mode {
                Mode::Lossless => {
                    let header = jpeg_header_via_std(args, metadata, true, true);
                    let mut header = header;
                    if !args.exif && !args.strip_icc {
                        if let Some(icc) = &metadata.icc {
                            prepend_icc(&mut header, icc);
                        }
                    }
                    jpeg::encode_jpeg_std(&resized, args.jpeg_baseline, &header)
                }
                Mode::Quality(q) => {
                    let intermediate = jpeg::std_intermediate_raster(&resized);
                    let header = {
                        let mut hd = jpeg_header_via_std(args, metadata, true, false);
                        if !args.exif && !args.strip_icc {
                            if let Some(icc) = &metadata.icc { prepend_icc(&mut hd, icc); }
                        }
                        hd
                    };
                    jpeg::encode_jpeg_moz(&intermediate, q, args.jpeg_baseline, args.jpeg_chroma_subsampling, &header)
                }
                Mode::MaxSize(max) => {
                    let intermediate = jpeg::std_intermediate_raster(&resized);
                    let header = {
                        let mut hd = jpeg_header_via_std(args, metadata, true, false);
                        if !args.exif && !args.strip_icc {
                            if let Some(icc) = &metadata.icc { prepend_icc(&mut hd, icc); }
                        }
                        hd
                    };
                    compress_to_size(|q| jpeg::encode_jpeg_moz(&intermediate, q, args.jpeg_baseline, args.jpeg_chroma_subsampling, &header), max)
                }
            };
        }
    }
    // No resize (or cancelled).
    match ctx.mode {
        Mode::Lossless => {
            let info = jpeg::parse_jpeg_info(data)?;
            let header = jpeg_header_direct(&info, args, true);
            let icc = if !args.exif && !args.strip_icc { info.metadata.icc.clone() } else { None };
            jpeg::lossless_copy(data, &header, args.jpeg_baseline, args.exif, icc.as_deref())
        }
        Mode::Quality(q) => {
            let coeff = jpeg::decode_jpeg_coefficients(data)?;
            let header = jpeg_header_direct(&coeff.info, args, false);
            let mut header = header;
            if !args.exif && !args.strip_icc {
                if let Some(icc) = &coeff.info.metadata.icc { prepend_icc(&mut header, icc); }
            }
            let raster = coeff.to_raster();
            jpeg::encode_jpeg_moz(&raster, q, args.jpeg_baseline, args.jpeg_chroma_subsampling, &header)
        }
        Mode::MaxSize(max) => {
            let coeff = jpeg::decode_jpeg_coefficients(data)?;
            let header = {
                let mut hd = jpeg_header_direct(&coeff.info, args, false);
                if !args.exif && !args.strip_icc {
                    if let Some(icc) = &coeff.info.metadata.icc { prepend_icc(&mut hd, icc); }
                }
                hd
            };
            let raster = coeff.to_raster();
            compress_to_size(|q| jpeg::encode_jpeg_moz(&raster, q, args.jpeg_baseline, args.jpeg_chroma_subsampling, &header), max)
        }
    }
}

fn prepend_icc(header: &mut JpegHeader, profile: &[u8]) {
    let mut tmp: Vec<u8> = Vec::new();
    jpeg::write_icc_segments(&mut tmp, profile);
    let mut segs: Vec<(u8, Vec<u8>)> = Vec::new();
    let mut pos = 0usize;
    while pos + 4 <= tmp.len() {
        let len = u16::from_be_bytes([tmp[pos+2], tmp[pos+3]]) as usize;
        segs.push((0xE2, tmp[pos+4..pos+2+len].to_vec()));
        pos += 2 + len;
    }
    segs.extend(header.markers.iter().cloned());
    header.markers = segs;
}

fn compress_webp_same(ctx: &Ctx, data: &[u8], _dims: Option<(u32,u32)>) -> CResult<Vec<u8>> {
    let args = ctx.args;
    if resize_requested(args) && header_truncated(InputFormat::Webp, data) {
        return Err(build_params_error());
    }
    let (raster, metadata) = webp::decode_webp(data)?;
    let mut raster = raster;
    if resize_requested(args) {
        let (req_w, req_h) = translate_edge_request(args, raster.width, raster.height);
        if !no_upscale_cancels(args, req_w, req_h, raster.width, raster.height) {
            let (tw, th) = compute_target_dims(raster.width, raster.height, req_w, req_h);
            check_zero_dims(tw, th)?;
            raster = raster.resize(tw.max(1), th.max(1));
        }
    }
    match ctx.mode {
        Mode::Quality(q) => webp::encode_webp(&raster, Some(q), &metadata, args.exif),
        Mode::Lossless => webp::encode_webp(&raster, None, &metadata, args.exif),
        Mode::MaxSize(max) => compress_to_size(|q| webp::encode_webp(&raster, Some(q), &metadata, args.exif), max),
    }
}

fn compress_gif_same(ctx: &Ctx, data: &[u8], _dims: Option<(u32,u32)>) -> CResult<Vec<u8>> {
    let args = ctx.args;
    let gif: GifInfo = parse_gif(data)?;
    let quality = match ctx.mode { Mode::Quality(q) => q, Mode::Lossless => 100, Mode::MaxSize(_) => 80 };
    let build_frames = |gif: &GifInfo, args: &Args| -> Vec<GifFrameSpec> {
        let delays: Vec<u16> = gif.frames.iter().map(|f| f.delay_cs).collect();
        let out_delays = transform_delays(&delays);
        gif.frames.iter().enumerate().map(|(i, f)| {
            let raster = Raster::new(gif.width, gif.height, ColorKind::Rgba8, f.rgba.clone());
            let raster = apply_gif_resize(&raster, args, gif.width, gif.height);
            GifFrameSpec { rgba: raster.rgba8(), delay_cs: out_delays.get(i).copied().unwrap_or(f.delay_cs) }
        }).collect()
    };
    let (out_w, out_h) = gif_output_dims(&gif, args);
    match ctx.mode {
        Mode::MaxSize(max) => {
            let frames = build_frames(&gif, args);
            compress_to_size(|q| Ok(encode_gif(out_w, out_h, &frames, gif.loop_count, q)), max)
        }
        _ => {
            let frames = build_frames(&gif, args);
            Ok(encode_gif(out_w, out_h, &frames, gif.loop_count, quality))
        }
    }
}

fn gif_output_dims(gif: &GifInfo, args: &Args) -> (u32, u32) {
    if !resize_requested(args) { return (gif.width, gif.height); }
    let (req_w, req_h) = translate_edge_request(args, gif.width, gif.height);
    if no_upscale_cancels(args, req_w, req_h, gif.width, gif.height) {
        return (gif.width, gif.height);
    }
    let (mut tw, mut th) = compute_target_dims(gif.width, gif.height, req_w, req_h);
    tw = tw.min(gif.width).max(1);
    th = th.min(gif.height).max(1);
    (tw, th)
}

fn apply_gif_resize(raster: &Raster, args: &Args, orig_w: u32, orig_h: u32) -> Raster {
    if !resize_requested(args) { return raster.clone(); }
    let (req_w, req_h) = translate_edge_request(args, orig_w, orig_h);
    if no_upscale_cancels(args, req_w, req_h, orig_w, orig_h) { return raster.clone(); }
    let (mut tw, mut th) = compute_target_dims(orig_w, orig_h, req_w, req_h);
    tw = tw.min(orig_w).max(1);
    th = th.min(orig_h).max(1);
    raster.resize(tw, th)
}

// ---------- per-file processing ----------
fn process_file(collected: &Collected, args: &Args, base_path: &Path) -> FileResult {
    let input = collected.path.clone();
    let original_size = fs::metadata(&input).map(|m| m.len()).unwrap_or(0);
    let output_path = match setup_output_path(&input, args, base_path) {
        Ok(p) => p,
        Err(_) => {
            return FileResult {
                input, output: PathBuf::new(), original_size, output_size: 0,
                status: Status::Error, message: Some("Error setting up output path".to_string()),
            };
        }
    };
    if args.overwrite == OverwritePolicy::Never && output_path.exists() {
        return FileResult {
            input, output: output_path, original_size, output_size: original_size,
            status: Status::Skipped,
            message: Some("File already exists, skipped due overwrite policy".to_string()),
        };
    }
    if args.dry_run {
        return FileResult {
            input, output: output_path, original_size, output_size: original_size,
            status: Status::Success, message: None,
        };
    }
    let data = match fs::read(&input) {
        Ok(d) => d,
        Err(e) => {
            return FileResult {
                input, output: output_path, original_size, output_size: 0,
                status: Status::Error,
                message: Some(format!("Error compressing file: {}", e)),
            };
        }
    };
    let original_size = data.len() as u64;
    let compressed = match compress_dispatch(collected, &data, args) {
        Ok(v) => v,
        Err(e) => {
            let message = if e.codes.contains(&u32::MAX) {
                e.message.clone()
            } else {
                format!("Error compressing file: {}", e.render())
            };
            return FileResult {
                input, output: output_path, original_size, output_size: 0,
                status: Status::Error, message: Some(message),
            };
        }
    };
    // Minimum savings check.
    if let Some(min) = &args.min_savings {
        let savings = original_size.saturating_sub(compressed.len() as u64);
        let skip_message = match min {
            MinSavings::Percent(pct) => {
                let sp = if original_size == 0 { 0.0 } else { savings as f64 / original_size as f64 * 100.0 };
                if sp <= *pct {
                    Some(format!("Insufficient savings: {:.2}% < {:.2}%, skipped", sp, pct))
                } else { None }
            }
            MinSavings::Absolute(threshold) => {
                if savings <= *threshold {
                    Some(format!("Insufficient savings: {} < {}, skipped", format_size(savings), format_size(*threshold)))
                } else { None }
            }
        };
        if let Some(message) = skip_message {
            return FileResult {
                input, output: output_path, original_size, output_size: original_size,
                status: Status::Skipped, message: Some(message),
            };
        }
    }
    if args.overwrite == OverwritePolicy::Bigger && output_path.exists() {
        let existing_size = fs::metadata(&output_path).map(|m| m.len()).unwrap_or(0);
        if existing_size <= compressed.len() as u64 {
            return FileResult {
                input, output: output_path, original_size, output_size: original_size,
                status: Status::Skipped,
                message: Some("File already exists, skipped due overwrite policy".to_string()),
            };
        }
    }
    let keep_times = if args.keep_dates {
        fs::metadata(&input).ok().map(|m| (m.accessed().unwrap_or(SystemTime::UNIX_EPOCH), m.modified().unwrap_or(SystemTime::UNIX_EPOCH)))
    } else { None };
    let out_len = compressed.len() as u64;
    if fs::write(&output_path, &compressed).is_err() {
        return FileResult {
            input, output: output_path, original_size, output_size: 0,
            status: Status::Error, message: Some("Error creating output file".to_string()),
        };
    }
    if let Some((atime, mtime)) = keep_times {
        set_file_times(&output_path, atime, mtime);
    }
    FileResult {
        input, output: output_path, original_size, output_size: out_len,
        status: Status::Success, message: None,
    }
}

// ---------- formatting ----------
pub fn format_size(bytes: u64) -> String {
    const UNITS: [&str; 7] = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
    if bytes < 1024 { return format!("{} B", bytes); }
    let mut value = bytes as f64;
    let mut unit = 0usize;
    while value >= 1024.0 && unit < UNITS.len() - 1 {
        value /= 1024.0;
        unit += 1;
    }
    format!("{:.1} {}", value, UNITS[unit])
}

pub struct ReportStyle {
    pub color: bool,
}
impl ReportStyle {
    fn paint(&self, code: &str, s: &str) -> String {
        if self.color { format!("\x1b[{}m{}\x1b[0m", code, s) } else { s.to_string() }
    }
    pub fn size_line(&self, original: u64, output: u64) -> String {
        let (diff_str, pct_str, code) = diff_parts(original, output);
        format!(
            "{} -> {} [{} | {}]",
            format_size(original), format_size(output),
            self.paint(code, &diff_str), self.paint(code, &pct_str)
        )
    }
}

fn diff_parts(original: u64, output: u64) -> (String, String, &'static str) {
    if output > original {
        let d = output - original;
        let pct = if original == 0 { 0.0 } else { d as f64 / original as f64 * 100.0 };
        (format!("+{}", format_size(d)), format!("+{:.2}%", pct), "31")
    } else {
        let d = original - output;
        let pct = if original == 0 { 0.0 } else { d as f64 / original as f64 * 100.0 };
        (format!("-{}", format_size(d)), format!("-{:.2}%", pct), "32")
    }
}

pub fn result_line(result: &FileResult, style: &ReportStyle) -> String {
    let (label, code) = match result.status {
        Status::Success => ("Success", "32"),
        Status::Skipped => ("Skipped", "33"),
        Status::Error => ("Error", "31"),
    };
    let mut s = format!(
        "[{}] {} -> {}\n{}\n",
        style.paint(code, label),
        result.input.display(), result.output.display(),
        style.size_line(result.original_size, result.output_size)
    );
    if let Some(msg) = &result.message {
        s.push_str(msg);
        s.push('\n');
    }
    s.push('\n');
    s
}

pub fn summary_line(results: &[FileResult], style: &ReportStyle) -> String {
    let total = results.len();
    let success = results.iter().filter(|r| r.status == Status::Success).count();
    let skipped = results.iter().filter(|r| r.status == Status::Skipped).count();
    let errors = results.iter().filter(|r| r.status == Status::Error).count();
    let total_orig: u64 = results.iter().map(|r| r.original_size).sum();
    let total_out: u64 = results.iter().map(|r| r.output_size).sum();
    format!(
        "Compressed {} files ({} success, {} skipped, {} errors)\n{}\n",
        total,
        style.paint("32", &success.to_string()),
        style.paint("33", &skipped.to_string()),
        style.paint("31", &errors.to_string()),
        style.size_line(total_orig, total_out)
    )
}

// ---------- progress display ----------
fn terminal_width(stdout: bool) -> usize {
    #[cfg(unix)]
    unsafe {
        use std::os::raw::{c_int, c_ulong};
        #[repr(C)]
        struct Winsize { ws_row: u16, ws_col: u16, ws_xpixel: u16, ws_ypixel: u16 }
        extern "C" { fn ioctl(fd: c_int, request: c_ulong, ...) -> c_int; }
        let fd = if stdout { 1 } else { 2 };
        let mut ws = Winsize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
        if ioctl(fd, 0x5413, &mut ws as *mut Winsize) == 0 && ws.ws_col > 0 {
            return ws.ws_col as usize;
        }
    }
    80
}

const SPINNER_FRAMES: [&str; 9] = ["⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠋"];

pub struct Spinner {
    stop: Arc<AtomicBool>,
    handle: Option<std::thread::JoinHandle<()>>,
    active: bool,
}
impl Spinner {
    pub fn start(enabled: bool) -> Self {
        if !enabled || !std::io::IsTerminal::is_terminal(&std::io::stderr()) {
            return Self { stop: Arc::new(AtomicBool::new(true)), handle: None, active: false };
        }
        let color = crate::cli::term_color(false);
        let width = terminal_width(false);
        let write_frame = |first: bool, ch: &str| {
            use std::io::Write;
            let text_plain = format!("{} Collecting files...", ch);
            let visible = text_plain.chars().count();
            let pad = width.saturating_sub(visible);
            let styled_ch = if color && !first { format!("\x1b[36m{}\x1b[0m", ch) } else { ch.to_string() };
            let mut err = std::io::stderr().lock();
            if !first { let _ = write!(err, "\r\x1b[2K"); }
            let _ = write!(err, "{} Collecting files...{}", styled_ch, " ".repeat(pad));
            let _ = err.flush();
        };
        write_frame(true, "⠁");
        write_frame(false, SPINNER_FRAMES[0]);
        let stop = Arc::new(AtomicBool::new(false));
        let stop2 = stop.clone();
        let handle = std::thread::spawn(move || {
            let mut idx = 1usize;
            loop {
                std::thread::sleep(Duration::from_millis(100));
                if stop2.load(Ordering::SeqCst) { break; }
                let ch = SPINNER_FRAMES[idx % SPINNER_FRAMES.len()];
                idx += 1;
                // Write from within the thread (duplicating write_frame to
                // keep the closure simple).
                use std::io::Write;
                let text_plain = format!("{} Collecting files...", ch);
                let visible = text_plain.chars().count();
                let pad = width.saturating_sub(visible);
                let styled_ch = if color { format!("\x1b[36m{}\x1b[0m", ch) } else { ch.to_string() };
                let mut err = std::io::stderr().lock();
                let _ = write!(err, "\r\x1b[2K{} Collecting files...{}", styled_ch, " ".repeat(pad));
                let _ = err.flush();
            }
        });
        Self { stop, handle: Some(handle), active: true }
    }
    pub fn finish(mut self) {
        if !self.active { return; }
        self.stop.store(true, Ordering::SeqCst);
        if let Some(h) = self.handle.take() { let _ = h.join(); }
        use std::io::Write;
        let mut err = std::io::stderr().lock();
        let _ = write!(err, "\r\x1b[2K");
        let _ = err.flush();
    }
}

pub struct Progress {
    state: Arc<Mutex<ProgressState>>,
    stop: Arc<AtomicBool>,
    handle: Option<std::thread::JoinHandle<()>>,
    active: bool,
}
struct ProgressState {
    pos: usize,
    total: usize,
    start: Instant,
    last_drawn_pos: Option<usize>,
    last_draw: Instant,
    first_draw_done: bool,
}
impl Progress {
    pub fn new(total: usize, enabled: bool) -> Self {
        if !enabled || !std::io::IsTerminal::is_terminal(&std::io::stdout()) || total == 0 {
            return Self {
                state: Arc::new(Mutex::new(ProgressState { pos: 0, total, start: Instant::now(), last_drawn_pos: None, last_draw: Instant::now(), first_draw_done: false })),
                stop: Arc::new(AtomicBool::new(true)), handle: None, active: false,
            };
        }
        let state = Arc::new(Mutex::new(ProgressState { pos: 0, total, start: Instant::now(), last_drawn_pos: None, last_draw: Instant::now(), first_draw_done: false }));
        draw_progress(&state, true);
        let stop = Arc::new(AtomicBool::new(false));
        let stop2 = stop.clone();
        let state2 = state.clone();
        let handle = std::thread::spawn(move || {
            let mut last_second = 0u64;
            loop {
                std::thread::sleep(Duration::from_millis(50));
                if stop2.load(Ordering::SeqCst) { break; }
                let sec = { state2.lock().unwrap().start.elapsed().as_secs() };
                if sec != last_second {
                    last_second = sec;
                    draw_progress(&state2, false);
                }
            }
        });
        Self { state, stop, handle: Some(handle), active: true }
    }
    pub fn inc(&self) {
        if !self.active { return; }
        let do_draw;
        {
            let mut st = self.state.lock().unwrap();
            st.pos += 1;
            do_draw = st.pos >= st.total || st.last_draw.elapsed() >= Duration::from_millis(50);
        }
        if do_draw { draw_progress(&self.state, false); }
    }
    pub fn finish(mut self) {
        if !self.active { return; }
        {
            let st = self.state.lock().unwrap();
            if st.last_drawn_pos != Some(st.total) {
                drop(st);
                draw_progress(&self.state, true);
            }
        }
        self.stop.store(true, Ordering::SeqCst);
        if let Some(h) = self.handle.take() { let _ = h.join(); }
    }
}

fn draw_progress(state: &Arc<Mutex<ProgressState>>, _force: bool) {
    use std::io::Write;
    let mut st = state.lock().unwrap();
    let pos = st.pos;
    let total = st.total;
    let elapsed = st.start.elapsed();
    let first = !st.first_draw_done;
    st.first_draw_done = true;
    st.last_drawn_pos = Some(pos);
    st.last_draw = Instant::now();
    drop(st);
    let secs = elapsed.as_secs();
    let elapsed_str = format!("[{:02}:{:02}:{:02}]", secs / 3600, (secs / 60) % 60, secs % 60);
    let suffix = format!("] {}/{}", pos, total);
    let prefix_len = elapsed_str.len() + 2; // "[..] ["
    let width = terminal_width(true);
    let bar_width = width.saturating_sub(prefix_len + suffix.len());
    let frac = if total == 0 { 0.0 } else { pos as f64 / total as f64 };
    let filled = if pos == 0 { 0 } else if pos >= total { bar_width } else { ((frac * bar_width as f64).ceil() as usize).min(bar_width) };
    let current: String = if pos >= total {
        "#".repeat(bar_width)
    } else if filled == 0 {
        String::new()
    } else {
        format!("{}>", "#".repeat(filled - 1))
    };
    let bg = "-".repeat(bar_width - filled);
    let bar = if crate::cli::term_color(true) {
        format!("\x1b[36m{}\x1b[34m{}\x1b[0m\x1b[0m", current, bg)
    } else {
        format!("{}{}", current, bg)
    };
    let mut out = std::io::stdout().lock();
    if !first { let _ = write!(out, "\r\x1b[2K"); }
    let _ = write!(out, "{} [{}{}", elapsed_str, bar, suffix);
    let _ = out.flush();
}

// ---------- top-level run ----------
pub fn run(args: &Args) -> i32 {
    if args.files.is_empty() {
        eprintln!("No files to compress");
        return 0;
    }
    let verbosity = if args.quiet { 0 } else { args.verbose };
    let spinner = Spinner::start(verbosity >= 1);
    let files = collect_files(&args.files, args.recursive);
    spinner.finish();
    let Some(base_path) = compute_base_path(&files) else {
        eprintln!("Unable to compute the base path for the files.");
        return 255;
    };
    let base_path = Arc::new(base_path);
    let progress = Arc::new(Progress::new(files.len(), verbosity >= 1));

    let available = std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1);
    let num_threads: usize = if args.threads == 0 || (args.threads as usize) > available { available } else { args.threads as usize }.max(1);
    let results: Arc<Mutex<Vec<Option<FileResult>>>> = Arc::new(Mutex::new(vec![None; files.len()]));
    let next = Arc::new(AtomicUsize::new(0));
    let files = Arc::new(files);
    let progress_main = progress.clone();

    std::thread::scope(|scope| {
        let worker = |next: Arc<AtomicUsize>, results: Arc<Mutex<Vec<Option<FileResult>>>>, files: Arc<Vec<Collected>>, base_path: Arc<PathBuf>, progress: Arc<Progress>| {
            loop {
                let idx = next.fetch_add(1, Ordering::SeqCst);
                if idx >= files.len() { break; }
                let result = process_file(&files[idx], args, &base_path);
                { results.lock().unwrap()[idx] = Some(result); }
                progress.inc();
            }
        };
        let mut handles = Vec::new();
        for _ in 0..num_threads.saturating_sub(1) {
            let (n, r, f, b, p) = (next.clone(), results.clone(), files.clone(), base_path.clone(), progress.clone());
            handles.push(scope.spawn(move || worker(n, r, f, b, p)));
        }
        worker(next.clone(), results.clone(), files.clone(), base_path.clone(), progress_main);
        for h in handles { let _ = h.join(); }
    });

    // Finish progress (consumes one Arc reference's inner value via a
    // dedicated finishing call on a clone is awkward; instead use the
    // shared state through a final draw + stop by dropping via try_unwrap
    // loop is over-engineered. We kept `progress` in an Arc for workers;
    // finish it by unwrapping when possible.)
    let progress = match Arc::try_unwrap(progress) {
        Ok(p) => p,
        Err(p) => { let _ = p; Progress::new(0, false) }
    };
    progress.finish();

    let results: Vec<FileResult> = {
        let guard = results.lock().unwrap();
        guard.iter().map(|r| r.clone().unwrap_or_else(|| FileResult {
            input: PathBuf::new(), output: PathBuf::new(), original_size: 0, output_size: 0,
            status: Status::Error, message: Some("Error compressing file: internal error".into()),
        })).collect()
    };

    if verbosity >= 1 {
        let style = ReportStyle { color: crate::cli::report_color() };
        use std::io::Write;
        let mut out = std::io::stdout().lock();
        for r in &results {
            let show = verbosity >= 3 || (verbosity == 2 && r.status != Status::Success);
            if show {
                let _ = write!(out, "{}", result_line(r, &style));
            }
        }
        let _ = write!(out, "{}", summary_line(&results, &style));
        let _ = out.flush();
    }
    0
}
