end=s.index('struct HuffEnc',start)
new=r'''fn gen_optimal_table(freq_in: &[u32; 257]) -> ([u8;16], Vec<u8>) {
    let mut freq = *freq_in;
    freq[256] = 1; // reserve the all-ones code
    let mut codesize = [0u32; 257];
    let mut others = [-1i32; 257];
    loop {
        // Find the two smallest nonzero frequencies.
        let mut c1: i32 = -1;
        let mut c2: i32 = -1;
        let mut v = u32::MAX;
        for i in 0..257 {
            if freq[i] > 0 && freq[i] <= v { v = freq[i]; c1 = i as i32; }
        }
        if c1 < 0 { break; }
        let mut v2 = u32::MAX;
        for i in 0..257 {
            if freq[i] > 0 && freq[i] <= v2 && i as i32 != c1 { v2 = freq[i]; c2 = i as i32; }
        }
        if c2 < 0 { break; }
        freq[c1 as usize] += freq[c2 as usize];
        freq[c2 as usize] = 0;
        codesize[c1 as usize] += 1;
        let mut node = c1;
        while others[node as usize] >= 0 {
            node = others[node as usize];
            codesize[node as usize] += 1;
        }
        others[node as usize] = c2;
        codesize[c2 as usize] += 1;
        let mut node2 = c2;
        while others[node2 as usize] >= 0 {
            node2 = others[node2 as usize];
            codesize[node2 as usize] += 1;
        }
    }
    // Count the number of symbols of each code size (including the
    // pseudo-symbol 256), then adjust sizes over 16 bits (JPEG F.12).
    let max_len = codesize.iter().max().copied().unwrap_or(0) as usize;
    let mut bits = vec![0i32; max_len + 2];
    for i in 0..257 {
        if codesize[i] > 0 { bits[codesize[i] as usize] += 1; }
    }
    if max_len > 16 {
        for l in (17..=max_len).rev() {
            while bits[l] > 0 {
                let mut moved = false;
                for i in (1..l - 1).rev() {
                    if bits[i] > 0 {
                        bits[i] -= 1;
                        bits[i + 1] += 2;
                        bits[l] -= 1;
                        moved = true;
                        break;
                    }
                }
                if !moved { break; }
            }
        }
    }
    // Remove the pseudo-symbol from the largest code length present.
    for l in (1..=16usize).rev() {
        if bits[l] > 0 { bits[l] -= 1; break; }
    }
    let mut out_bits = [0u8; 16];
    for l in 1..=16usize {
        out_bits[l - 1] = bits[l].clamp(0, 255) as u8;
    }
    // Symbols ordered by (code length, symbol value), pseudo-symbol excluded.
    let mut symbols: Vec<u8> = Vec::new();
    for len in 1..=(max_len as u32) {
        for i in 0..256usize {
            if codesize[i] == len { symbols.push(i as u8); }
        }
    }
    (out_bits, symbols)
}

