fn kmeans_refine(hist: &std::collections::HashMap<[u8;4], u32>, init: Vec<[u8;4]>) -> Vec<[u8;4]> {
    let k = init.len();
    if k == 0 { return init; }
    let colors: Vec<([u8;4], u32)> = hist.iter().map(|(c, n)| (*c, *n)).collect();
    let mut centers: Vec<[f32;4]> = init.iter().map(|c| [c[0] as f32, c[1] as f32, c[2] as f32, c[3] as f32]).collect();
    let iterations = if colors.len() <= 20_000 { 16 } else if colors.len() <= 100_000 { 6 } else { 2 };
    let premult = |c: [f32;4]| -> [f32;4] {
        let a = c[3] / 255.0;
        [c[0] * a, c[1] * a, c[2] * a, c[3]]
    };
    let mut assignment: Vec<usize> = vec![0; colors.len()];
    for _ in 0..iterations {
        let center_pm: Vec<[f32;4]> = centers.iter().map(|c| premult(*c)).collect();
        let mut changed = false;
        let mut worst_dist = -1.0f32;
        let mut worst_idx = 0usize;
        for (i, (c, _)) in colors.iter().enumerate() {
            let cp = premult([c[0] as f32, c[1] as f32, c[2] as f32, c[3] as f32]);
            let mut best = 0usize;
            let mut bestd = f32::INFINITY;
            for (j, cen) in center_pm.iter().enumerate() {
                let d = (cp[0]-cen[0]).powi(2) + (cp[1]-cen[1]).powi(2) + (cp[2]-cen[2]).powi(2) + (cp[3]-cen[3]).powi(2);
                if d < bestd { bestd = d; best = j; }
            }
            if assignment[i] != best { changed = true; assignment[i] = best; }
            if bestd > worst_dist { worst_dist = bestd; worst_idx = i; }
        }
        // Recompute centres.
        let mut sums = vec![[0f64; 4]; k]; // premultiplied rgb sums + alpha sum
        let mut counts = vec![0f64; k];
        for (i, (c, n)) in colors.iter().enumerate() {
            let a = c[3] as f64 / 255.0;
            let j = assignment[i];
            let wgt = *n as f64;
            sums[j][0] += c[0] as f64 * a * wgt;
            sums[j][1] += c[1] as f64 * a * wgt;
            sums[j][2] += c[2] as f64 * a * wgt;
            sums[j][3] += c[3] as f64 * wgt;
            counts[j] += wgt;
        }
        for j in 0..k {
            if counts[j] > 0.0 {
                let alpha = sums[j][3] / counts[j];
                if sums[j][3] > 0.0 {
                    centers[j] = [
                        (sums[j][0] * 255.0 / sums[j][3]) as f32,
                        (sums[j][1] * 255.0 / sums[j][3]) as f32,
                        (sums[j][2] * 255.0 / sums[j][3]) as f32,
                        alpha as f32,
                    ];
                } else {
                    centers[j][3] = 0.0;
                }
            } else {
                // Re-seed an empty cluster at the worst-served colour.
                let c = colors[worst_idx].0;
                centers[j] = [c[0] as f32, c[1] as f32, c[2] as f32, c[3] as f32];
                changed = true;
            }
        }
        if !changed { break; }
    }
    let mut out: Vec<[u8;4]> = Vec::new();
    for c in centers {
        let v = [c[0].clamp(0.0,255.0).round() as u8, c[1].clamp(0.0,255.0).round() as u8, c[2].clamp(0.0,255.0).round() as u8, c[3].clamp(0.0,255.0).round() as u8];
        if !out.contains(&v) { out.push(v); }
    }
    out
}
