{"command":"cat >> src/webp.rs << 'RS'

// ---------- animated WebP ----------
#[derive(Clone, Debug)]
pub struct AnimFrame {
    pub raster: Raster, // composited full-canvas frame
    pub duration_ms: u32,
}

#[derive(Clone, Debug)]
pub struct WebpAnimation {
    pub width: u32,
    pub height: u32,
    pub loop_count: u16,
    pub background: [u8; 4], // RGBA
    pub frames: Vec<AnimFrame>,
    pub metadata: Metadata,
}

fn read_u24le(b: &[u8]) -> u32 {
    b[0] as u32 | (b[1] as u32) << 8 | (b[2] as u32) << 16
}

pub fn is_animated_webp(data: &[u8]) -> bool {
    if data.len() < 21 || &data[12..16] != b"VP8X" { return false; }
    data[20] & 0x02 != 0
}

pub fn decode_webp_animation(data: &[u8]) -> CResult<Option<WebpAnimation>> {
    if !is_animated_webp(data) { return Ok(None); }
    let metadata = parse_webp_chunks(data);
    let mut width = 0u32;
    let mut height = 0u32;
    let mut loop_count = 0u16;
    let mut background = [0u8; 4];
    struct RawAnimFrame {
        x: u32, y: u32, w: u32, h: u32, duration: u32, flags: u8,
        bitstream: Vec<u8>, // a complete still-image WebP file
    }
    let mut raw_frames: Vec<RawAnimFrame> = Vec::new();
    let mut pos = 12usize;
    while pos + 8 <= data.len() {
        let typ = &data[pos..pos+4];
        let len = u32::from_le_bytes([data[pos+4], data[pos+5], data[pos+6], data[pos+7]]) as usize;
        if pos + 8 + len > data.len() { break; }
        let payload = &data[pos + 8..pos + 8 + len];
        match typ {
            b"VP8X" if payload.len() >= 10 => {
                width = read_u24le(&payload[4..7]) + 1;
                height = read_u24le(&payload[7..10]) + 1;
            }
            b"ANIM" if payload.len() >= 6 => {
                background = [payload[2], payload[1], payload[0], payload[3]];
                loop_count = u16::from_le_bytes([payload[4], payload[5]]);
            }
            b"ANMF" if payload.len() >= 16 => {
                let fx = read_u24le(&payload[0..3]) * 2;
                let fy = read_u24le(&payload[3..6]) * 2;
                let fw = read_u24le(&payload[6..9]) + 1;
                let fh = read_u24le(&payload[9..12]) + 1;
                let dur = read_u24le(&payload[12..15]);
                let flags = payload[15];
                let sub = &payload[16..];
                // Build a standalone still WebP from the frame's chunks.
                let has_alpha = sub.windows(4).any(|w| w == b"ALPH");
                let mut still: Vec<u8> = Vec::new();
                still.extend_from_slice(b"RIFF");
                still.extend_from_slice(&[0,0,0,0]);
                still.extend_from_slice(b"WEBP");
                if sub.len() >= 4 && (&sub[0..4] == b"VP8 " || &sub[0..4] == b"VP8L" || &sub[0..4] == b"ALPH") {
                    if has_alpha {
                        let mut vp8x = vec![0x10u8, 0, 0, 0];
                        vp8x.extend_from_slice(&(fw - 1).to_le_bytes()[..3]);
                        vp8x.extend_from_slice(&(fh - 1).to_le_bytes()[..3]);
                        write_chunk(&mut still, b"VP8X", &vp8x);
                    }
                    still.extend_from_slice(sub);
                } else {
                    // Raw bitstream without a chunk header: guess the type.
                    let is_lossless = sub.first().copied() == Some(0x2F);
                    let typ2: &[u8;4] = if is_lossless { b"VP8L" } else { b"VP8 " };
                    write_chunk(&mut still, typ2, sub);
                }
                let riff_size = (still.len() - 8) as u32;
                still[4..8].copy_from_slice(&riff_size.to_le_bytes());
                raw_frames.push(RawAnimFrame { x: fx, y: fy, w: fw, h: fh, duration: dur, flags, bitstream: still });
            }
            _ => {}
        }
        pos += 8 + len + (len & 1);
    }
    if raw_frames.is_empty() || width == 0 { return Ok(None); }

    let npix = (width as usize) * (height as usize);
    let mut canvas = vec![0u8; npix * 4];
    for i in 0..npix { canvas[i*4..i*4+4].copy_from_slice(&background); }
    let mut frames: Vec<AnimFrame> = Vec::new();
    for raw in &raw_frames {
        let (frame_raster, _) = decode_webp(&raw.bitstream)?;
        let frgba = frame_raster.rgba8();
        let dispose = raw.flags & 1 != 0;
        let no_blend = raw.flags & 2 != 0;
