    // VP8X
    {
        let mut vp8x = vec![0x02u8, 0, 0, 0];
        vp8x.extend_from_slice(&(width - 1).to_le_bytes()[..3]);
        vp8x.extend_from_slice(&(height - 1).to_le_bytes()[..3]);
        write_chunk(&mut body, b"VP8X", &vp8x);
    }
    // ANIM
    {
        let mut anim = vec![background[2], background[1], background[0], background[3]];
        anim.extend_from_slice(&loop_count.to_le_bytes());
        write_chunk(&mut body, b"ANIM", &anim);
    }
    for (i, frame) in frames.iter().enumerate() {
        let still = encode_webp_still_raw(&frame.raster, quality)?;
        // Extract the frame's chunks (skipping a VP8X header if present).
        let mut subchunks: Vec<u8> = Vec::new();
        let mut pos = 12usize;
        while pos + 8 <= still.len() {
            let typ = &still[pos..pos+4];
            let len = u32::from_le_bytes([still[pos+4], still[pos+5], still[pos+6], still[pos+7]]) as usize;
            if pos + 8 + len > still.len() { break; }
            if typ != b"VP8X" {
                subchunks.extend_from_slice(&still[pos..pos + 8 + len + (len & 1)]);
            }
            pos += 8 + len + (len & 1);
        }
        let mut header: Vec<u8> = Vec::with_capacity(16);
        header.extend_from_slice(&0u32.to_le_bytes()[..3]); // x / 2
        header.extend_from_slice(&0u32.to_le_bytes()[..3]); // y / 2
        header.extend_from_slice(&(width - 1).to_le_bytes()[..3]);
        header.extend_from_slice(&(height - 1).to_le_bytes()[..3]);
        header.extend_from_slice(&frame.duration_ms.to_le_bytes()[..3]);
        header.push(if i == 0 { 2 } else { 0 }); // first frame: do not blend
        header.extend_from_slice(&subchunks);
        write_chunk(&mut body, b"ANMF", &header);
    }
    let mut out: Vec<u8> = Vec::new();
    out.extend_from_slice(b"RIFF");
    out.extend_from_slice(&(body.len() as u32).to_le_bytes());
    out.extend_from_slice(&body);
    if include_metadata && (metadata.icc.is_some() || metadata.exif.is_some()) {
        // The original inserts ICCP immediately after the RIFF/WEBP
        // header (before VP8X) and appends EXIF at the end.
        let mut result: Vec<u8> = Vec::new();
        result.extend_from_slice(&out[..12]);
        if let Some(icc) = &metadata.icc { write_chunk(&mut result, b"ICCP", icc); }
        result.extend_from_slice(&out[12..]);
        if let Some(exif) = &metadata.exif { write_chunk(&mut result, b"EXIF", exif); }
        let riff_size = (result.len() - 8) as u32;
        result[4..8].copy_from_slice(&riff_size.to_le_bytes());
        out = result;
    }
    Ok(out)
}
