        let in_durations: Vec<u32> = frames.iter().map(|f| f.duration_ms).collect();
        let out_durations = webp::transform_webp_durations(&in_durations);
        for (f, d) in frames.iter_mut().zip(out_durations.iter()) { f.duration_ms = *d; }
