  try:
   A=decode(f);B=decode(o)
  except Exception as e:
   # python decoder lacks interlace for input; use Go compare via converting both? just check Go decode output
   v=subprocess.run(['/tmp/goimg/img',o],capture_output=True,text=True)
   if 'err' in v.stdout:issues+=1;print('invalid',f,mode,v.stdout)
   continue
  if A[:2]!=B[:2] or A[-1]!=B[-1]:
   issues+=1;print('PIXDIFF',f,mode,A[:5],B[:5],'samefrac',sum(x==y for x,y in zip(A[-1],B[-1]))/max(1,len(A[-1])))
print('issues',issues)
