  b:=fr.Bounds()
  for y:=b.Min.Y;y<b.Max.Y;y++ {
   for x:=b.Min.X;x<b.Max.X;x++ {
    r,gg,bb,a:=fr.At(x,y).RGBA()
    if a>0 {canvas[y*w+x]=color.RGBA{uint8(r>>8),uint8(gg>>8),uint8(bb>>8),uint8(a>>8)}}
   }
  }
  fmt.Printf("frame%d delay%d disposal%d TL=%v TR=%v BL=%v BR=%v C=%v bounds=%v\n",i,g.Delay[i],g.Disposal[i],canvas[0],canvas[w-1],canvas[(h-1)*w],canvas[h*w-1],canvas[(h/2)*w+w/2],b)
  switch g.Disposal[i] {
  case gif.DisposalBackground:
   for y:=b.Min.Y;y<b.Max.Y;y++{for x:=b.Min.X;x<b.Max.X;x++{canvas[y*w+x]=color.RGBA{}}}
  case gif.DisposalPrevious:
   copy(canvas,snapshot)
  }
 }
}
