import json,math
words=['quality','lossless','max-size','width','height','long-edge','short-edge','no-upscale','output','same-folder-as-input','format','png-opt-level','jpeg-chroma-subsampling','jpeg-baseline','zopfli','exif','keep-dates','strip-icc','suffix','recursive','keep-structure','dry-run','threads','overwrite','min-savings','quiet','verbose','help','version']
data=json.load(open('/tmp/sugg.json'))
def jaro(a,b,use_minus=True):
 if not a and not b:return 1.0
 if not a or not b:return 0.0
 if a==b:return 1.0
 md=max(len(a),len(b))//2-1 if use_minus else max(len(a),len(b))//2
 if md<0:md=0
 am=[False]*len(a);bm=[False]*len(b);matches=0
 for i,ca in enumerate(a):
  lo=max(0,i-md);hi=min(len(b),i+md+1)
  for j in range(lo,hi):
   if not bm[j] and ca==b[j]:am[i]=bm[j]=True;matches+=1;break
 if matches==0:return 0.0
 t=0;j=0
 for i in range(len(a)):
  if am[i]:
   while not bm[j]:j+=1
   if a[i]!=b[j]:t+=1
   j+=1
 return (matches/len(a)+matches/len(b)+(matches-t//2)/matches)/3
def jw(a,b,use_minus=True,boost=0.7):
 j=jaro(a,b,use_minus)
 if j>boost:
  pref=0
  for x,y in zip(a,b):
   if x==y and pref<4:pref+=1
   else:break
  return j+pref*0.1*(1-j)
 return j
def lev_norm(a,b):
 # levenshtein distance normalized
 prev=list(range(len(b)+1))
 for i,ca in enumerate(a,1):
  cur=[i]
  for j,cb in enumerate(b,1):cur.append(min(prev[j]+1,cur[j-1]+1,prev[j-1]+(ca!=cb)))
  prev=cur
 return 1-prev[-1]/max(len(a),len(b),1)
results=[]
for input_mode in ['strip','full']:
 for cand_mode in ['strip','full']:
  for metric_name in ['jaro','jw','jaro_plus','jw_plus','lev']:
   for threshold in [0.7,0.75,0.8,0.85]:
    for selection in ['max','min']:
     for order_name in ['def','alpha','revdef','revalpha']:
      cand_words=words[:]
      if order_name=='alpha':cand_words=sorted(words)
      elif order_name=='revdef':cand_words=words[::-1]
      elif order_name=='revalpha':cand_words=sorted(words,reverse=True)
      correct=0
      for token,expected in data.items():
       inp=('--'+token) if input_mode=='full' else token
       cands=[]
       for idx,w in enumerate(cand_words):
        cand=('--'+w) if cand_mode=='full' else w
        if metric_name=='jaro':score=jaro(inp,cand,True)
        elif metric_name=='jw':score=jw(inp,cand,True)
        elif metric_name=='jaro_plus':score=jaro(inp,cand,False)
        elif metric_name=='jw_plus':score=jw(inp,cand,False)
        else:score=lev_norm(inp,cand)
        if score>threshold:cands.append((score,idx,w))
       if not cands:pred=None
       elif selection=='max':
        # max by score, ties keep first candidate in order sequence (max with key in Python first max)
        pred='--'+max(cands,key=lambda x:x[0])[2]
       else:pred='--'+min(cands,key=lambda x:x[0])[2]
       if pred==expected:correct+=1
      results.append((correct,input_mode,cand_mode,metric_name,threshold,selection,order_name))
for r in sorted(results,reverse=True)[:30]:print(r, '/',len(data))
