{"command":"cat > src/z.rs << 'RS'
// zlib is loaded at runtime so that linking does not require the
// development symlink (libz.so) to be present.
use std::ffi::CString;
use std::os::raw::{c_char, c_int, c_ulong, c_void};
use std::sync::OnceLock;

#[cfg(unix)]
extern "C" {
    fn dlopen(filename: *const c_char, flag: c_int) -> *mut c_void;
    fn dlsym(handle: *mut c_void, symbol: *const c_char) -> *mut c_void;
}

type FnCompressBound = unsafe extern "C" fn(c_ulong) -> c_ulong;
type FnCompress2 = unsafe extern "C" fn(*mut u8, *mut c_ulong, *const u8, c_ulong, c_int) -> c_int;
type FnUncompress = unsafe extern "C" fn(*mut u8, *mut c_ulong, *const u8, c_ulong) -> c_int;

struct LibZ {
    compress_bound: FnCompressBound,
    compress2: FnCompress2,
    uncompress: FnUncompress,
}

static LIB: OnceLock<Option<LibZ>> = OnceLock::new();

fn lib() -> Option<&'static LibZ> {
    LIB.get_or_init(|| {
        #[cfg(unix)]
        unsafe {
            let mut handle: *mut c_void = std::ptr::null_mut();
            for name in ["libz.so.1", "libz.so"] {
                let cname = CString::new(name).unwrap();
                handle = dlopen(cname.as_ptr(), 1);
                if !handle.is_null() {
                    break;
                }
            }
            if handle.is_null() {
                return None;
            }
            macro_rules! sym {
                ($name:literal, $ty:ty) => {{
                    let cname = CString::new($name).unwrap();
                    let p = dlsym(handle, cname.as_ptr());
                    if p.is_null() {
                        return None;
                    }
                    std::mem::transmute::<*mut c_void, $ty>(p)
                }};
            }
            Some(LibZ {
                compress_bound: sym!("compressBound", FnCompressBound),
                compress2: sym!("compress2", FnCompress2),
                uncompress: sym!("uncompress", FnUncompress),
            })
        }
        #[cfg(not(unix))]
        {
            None
        }
    })
    .as_ref()
}

fn adler32(data: &[u8]) -> u32 {
    let mut a: u32 = 1;
    let mut b: u32 = 0;
    for chunk in data.chunks(5552) {
        for &byte in chunk {
            a += byte as u32;
            b += a;
        }
        a %= 65521;
        b %= 65521;
    }
    (b << 16) | a
}

/// A stored-block (uncompressed) zlib stream, used only if libz is
/// unavailable at runtime.
fn compress_stored(data: &[u8]) -> Vec<u8> {
    let mut out = vec![0x78u8, 0x01];
    if data.is_empty() {
        out.extend_from_slice(&[0x01, 0x00, 0x00, 0xFF, 0xFF]);
    } else {
        for (i, block) in data.chunks(65535).enumerate() {
            let is_last = (i + 1) * 65535 >= data.len();
            out.push(if is_last { 0x01 } else { 0x00 });
            out.extend_from_slice(&(block.len() as u16).to_le_bytes());
            out.extend_from_slice(&(!(block.len() as u16)).to_le_bytes());
            out.extend_from_slice(block);
        }
    }
    out.extend_from_slice(&adler32(data).to_be_bytes());
    out
}

pub fn compress(data: &[u8], level: i32) -> Vec<u8> {
    match lib() {
        Some(lib) => unsafe {
            let bound = (lib.compress_bound)(data.len() as c_ulong) as usize;
            let mut out = vec![0u8; bound.max(1)];
            let mut out_len = out.len() as c_ulong;
            let rc = (lib.compress2)(
                out.as_mut_ptr(),
                &mut out_len,
                data.as_ptr(),
                data.len() as c_ulong,
                level as c_int,
            );
            if rc != 0 {
                let mut out_len2 = out.len() as c_ulong;
                let _ = (lib.compress2)(
                    out.as_mut_ptr(),
                    &mut out_len2,
